function folderIconSvg(key, size){
  const def = FOLDER_ICONS.find(i => i[0] === key) || FOLDER_ICONS[0];
  const d = def[1].split('|').map(p => '<path d="' + p + '"/>').join('');
  const s = size || 28;
  return '<svg viewBox="0 0 24 24" width="' + s + '" height="' + s + '" fill="none" ' +
         'stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">' + d + '</svg>';
}
function setFolderStyle(id, patch){
  const arr = loadFolders();
  const f = arr.find(x => x.id === id);
  if(!f) return;
  Object.assign(f, patch);
  saveFolders(arr);
}
// Colour + icon in one readout, anchored to whatever opened it.
function openFolderStylePop(folder, anchor){
  document.querySelectorAll('.folder-style-pop').forEach(e => e.remove());
  const pop = document.createElement('div');
  pop.className = 'folder-style-pop';

  const ch = document.createElement('div'); ch.className = 'fsp-head'; ch.textContent = 'Colour';
  const row = document.createElement('div'); row.className = 'fsp-colours';
  PASTEL_PRESETS.forEach(hex => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'fsp-swatch' + ((folder.color || '') === hex ? ' on' : '');
    b.style.background = hex; b.title = hex;
    b.addEventListener('click', () => {
      setFolderStyle(folder.id, { color: hex });
      pop.remove(); renderProjectsPanel();
    });
    row.appendChild(b);
  });

  const ih = document.createElement('div'); ih.className = 'fsp-head'; ih.textContent = 'Icon';
  const grid = document.createElement('div'); grid.className = 'fsp-icons';
  FOLDER_ICONS.forEach(([key]) => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'fsp-icon' + ((folder.icon || 'folder') === key ? ' on' : '');
    b.title = key; b.innerHTML = folderIconSvg(key, 20);
    b.addEventListener('click', () => {
      setFolderStyle(folder.id, { icon: key });
      pop.remove(); renderProjectsPanel();
    });
    grid.appendChild(b);
  });

  pop.append(ch, row, ih, grid);
  // Inside #projectsModal, not body: the library is always-light and scopes its
  // own tokens, so a popover parented to body comes out in the dark theme.
  // #projectsModal itself carries no transform/filter, so position:fixed still
  // resolves against the viewport (.modal-panel would NOT — it has a
  // backdrop-filter, which makes it a containing block for fixed children).
  (document.getElementById('projectsModal') || document.body).appendChild(pop);
  const r = anchor.getBoundingClientRect();
  pop.style.left = Math.max(10, Math.min(window.innerWidth - pop.offsetWidth - 10, r.left)) + 'px';
  pop.style.top  = Math.min(window.innerHeight - pop.offsetHeight - 10, r.bottom + 8) + 'px';
  const away = ev => {
    if(pop.contains(ev.target) || anchor.contains(ev.target)) return;
    pop.remove(); document.removeEventListener('pointerdown', away, true);
  };
  setTimeout(() => document.addEventListener('pointerdown', away, true), 0);
}
function renameFolder(id, name){
  const folders = loadFolders();
  const f = folders.find(x => x.id === id);
  if(f){ f.name = name; saveFolders(folders); }
}
async function moveProjectToFolder(projectId, folderId){
  if(HAS_TAURI){
    try {
      const s = await storage.loadProjectState(projectId);
      if(!s._meta) s._meta = {};
      s._meta.folderId = folderId || null;
      await storage.saveProjectState(projectId, s);
      renderProjectsPanel();
    } catch(e){ console.error('moveProjectToFolder', e); note('Could not move project'); }
    return;
  }
  const idx = loadProjectsIndex();
  const p = idx.find(x => x.id === projectId);
  if(p){ p.folderId = folderId || null; saveProjectsIndex(idx); }
}
// Move a SET in one go. Dragging a card that is part of the current selection
// used to move only that card, because the drag carried a single id and the
// selection was never consulted. Re-rendering per project would also make a
// multi-drag re-read the whole library N times under Tauri, so this batches.
// Returns how many actually moved. Callers do NOT need to re-render.
async function moveProjectsToFolder(ids, folderId){
  const list = (ids || []).filter(Boolean);
  if(!list.length) return 0;
  let moved = 0;
  if(HAS_TAURI){
    for(const id of list){
      try {
        const s = await storage.loadProjectState(id);
        if(!s._meta) s._meta = {};
        s._meta.folderId = folderId || null;
        await storage.saveProjectState(id, s);
        moved++;
      } catch(e){ console.error('moveProjectsToFolder', id, e); }
    }
  } else {
    const idx = loadProjectsIndex();
    list.forEach(id => {
      const p = idx.find(x => x.id === id);
      if(p){ p.folderId = folderId || null; moved++; }
    });
    saveProjectsIndex(idx);
  }
  renderProjectsPanel();
  return moved;
}
// What a drag off THIS card should carry: the whole selection when the card is
// part of it, otherwise just the card. Dragging an unselected card never moves
// the selected ones — that would be a surprise you cannot undo.
function _draggedProjectIds(id){
  return (_projectsSelected.has(id) && _projectsSelected.size > 1)
    ? Array.from(_projectsSelected)
    : [id];
}
// "3 projects" / "1 project", for the confirmation note.
function _projCountLabel(n){ return n + (n === 1 ? ' project' : ' projects'); }

// Module-scoped UI state for the projects modal
let _projectsSearch = '';
let _projectsFolder = null;
let _projectsSelected = new Set();
// #51 library-wide search caches and async state
let _libSearchCache = new Map();   // project ref → full state (loaded lazily)
let _libSearchToken = 0;            // increments per typed query; lets us drop stale results
let _libSearchResults = null;       // last-rendered result array
let _libSearchPending = false;
function _invalidateLibSearchCacheFor(ref){ if(_libSearchCache.has(ref)) _libSearchCache.delete(ref); }

// Build a short context snippet around the first match of `q` in `text`.
function _libSnippet(text, q){
  if(!text) return '';
  const t = String(text);
  const idx = t.toLowerCase().indexOf(q.toLowerCase());
  if(idx < 0) return t.slice(0, 90);
  const start = Math.max(0, idx - 30);
  const end = Math.min(t.length, idx + q.length + 60);
  let s = t.slice(start, end).replace(/\s+/g, ' ').trim();
  if(start > 0) s = '…' + s;
  if(end < t.length) s = s + '…';
  return s;
}
function _libEscape(s){ return (s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function _libHighlight(s, q){
  if(!s || !q) return _libEscape(s);
  const esc = _libEscape(s);
  const escQ = _libEscape(q).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return esc.replace(new RegExp(escQ, 'gi'), m => '<mark>' + m + '</mark>');
}

// Run a deep search across every project in the library. Results carry a
// pointer back to the element so a click can openProject + jumpToNode.
async function performLibrarySearch(query){
  query = (query || '').trim();
  if(query.length < 3) return [];
  const token = ++_libSearchToken;
  const idx = await storage.listProjects();
  const out = [];
  for(const meta of idx){
    if(token !== _libSearchToken) return null; // newer search superseded us
    const ref = meta.id;
    // Round 48: the OPEN project's disk file lags the live edits by up to
    // 600ms (the debounced write) — search the in-memory state directly so
    // results never miss a just-typed beat.
    let s = (ref === currentProjectId && state) ? state : _libSearchCache.get(ref);
    if(!s){
      try { s = await storage.loadProjectState(ref); } catch(e){ continue; }
      if(!s) continue;
      _libSearchCache.set(ref, s);
    }
    const matches = [];
    const q = query.toLowerCase();
    // Collect every document attached to this project — both board-level
    // (s.documents) and per-beat (n.documents from #84) — for full-text
    // search via macOS Spotlight (#85). Resolved as { ownerKind, ownerId,
    // d, text } so the match list can point back at the right anchor.
    const allDocs = [];
    (s.documents || []).forEach(d => allDocs.push({ ownerKind: 'board', ownerId: d.id, d }));
    (s.nodes || []).forEach(n => (n.documents || []).forEach(d => allDocs.push({ ownerKind: 'node', ownerId: n.id, d })));
    let docTexts = [];
    if(HAS_TAURI && allDocs.length){
      docTexts = await Promise.all(allDocs.map(async entry => {
        const src = entry.d.src;
        if(!src || /^(data:|https?:)/.test(src)) return '';
        const filename = String(src).replace(/^assets[\\/]/, '');
        const absPath = ref + '/assets/' + filename;
        try {
          const t = await window.__TAURI__.core.invoke('read_doc_text', { path: absPath });
          return (t || '').toLowerCase();
        } catch(e){ return ''; }
      }));
    } else {
      docTexts = allDocs.map(() => '');
    }
    (s.nodes || []).forEach(n => {
      const hay = [n.title, n.body, n.slug, n.product, n.shotType, n.duration, (n.tones || []).join(' ')]
        .filter(Boolean).join(' ').toLowerCase();
      if(hay.indexOf(q) < 0) return;
      let kind = n.type || 'beat';
      const title = (n.title || '').trim() || ('(' + kind + ')');
      const snipSource = [n.title, n.body, n.slug].filter(Boolean).join(' ');
      matches.push({
        kind, id: n.id, title,
        snippet: _libSnippet(snipSource, query)
      });
    });
    (s.links || []).forEach(l => {
      const hay = ((l.title || '') + ' ' + (l.url || '')).toLowerCase();
      if(hay.indexOf(q) < 0) return;
      matches.push({
        kind: 'link', id: l.id,
        title: l.title || l.url || 'Link',
        snippet: _libSnippet(l.url || l.title || '', query)
      });
    });
    allDocs.forEach((entry, i) => {
      const d = entry.d;
      const text = docTexts[i] || '';
      const hay = ((d.filename || '') + ' ' + (d.mimeType || '') + ' ' + text).toLowerCase();
      if(hay.indexOf(q) < 0) return;
      // Snippet prefers the indexed text (where the match actually is);
      // falls back to the filename for filename-only matches.
      const snipSource = text && text.indexOf(q) >= 0 ? text : (d.filename || '');
      matches.push({
        kind: 'doc',
        id: entry.ownerId,
        title: d.filename || 'Document',
        snippet: _libSnippet(snipSource, query),
        ownerKind: entry.ownerKind
      });
    });
    (s.videoEmbeds || []).forEach(v => {
      const hay = ((v.title || '') + ' ' + (v.url || '') + ' ' + (v.platform || '')).toLowerCase();
      if(hay.indexOf(q) < 0) return;
      matches.push({
        kind: 'video', id: v.id,
        title: v.title || v.url || 'Video',
        snippet: _libSnippet((v.url || '') + ' ' + (v.title || ''), query)
      });
    });
    (s.groups || []).forEach(g => {
      const hay = (g.name || '').toLowerCase();
      if(hay.indexOf(q) < 0) return;
      matches.push({
        kind: 'group', id: g.id,
        title: g.name || 'Group',
        snippet: g.name || ''
      });
    });
    if(matches.length){
      // Cap to 12 per project so the modal doesn't drown in one project's hits.
      out.push({
        ref, name: meta.name || 'Untitled',
        matches: matches.slice(0, 12),
        truncated: matches.length > 12,
        totalMatches: matches.length
      });
    }
  }
  return out;
}

// Open a project, then pan/zoom to the matched element (after the render
// settles). Called when the user clicks a library-search result.
async function openProjectAtElement(ref, kind, elementId, ownerKind){
  await openProject(ref);
  // #84 — doc matches attached to a beat point at the BEAT id; jump there.
  if(kind === 'doc' && ownerKind === 'node'){
    setTimeout(() => {
      if(!state) return;
      const t = (state.nodes || []).find(n => n.id === elementId);
      if(t) jumpToNode(t);
    }, 60);
    return;
  }
  // The render in openProject is synchronous, but give one frame for the
  // DOM to settle before trying to find the node element.
  setTimeout(() => {
    if(!state) return;
    let target = null;
    if(kind === 'beat' || kind === 'thought' || kind === 'gallery' || kind === 'character' ||
       kind === 'location' || kind === 'prop' || kind === 'note' || kind === 'palette' ||
       kind === 'title' || kind === 'sketch'){
      target = (state.nodes || []).find(n => n.id === elementId);
      if(target) jumpToNode(target);
    } else if(kind === 'group'){
      const g = (state.groups || []).find(x => x.id === elementId);
      if(g){
        const rect = viewport.getBoundingClientRect();
        const z = state.view.zoom || 1;
        const cx = g.x + (g.w || 400) / 2;
        const cy = g.y + (g.h || 280) / 2;
        state.view.panX = rect.width / 2 - cx * z;
        state.view.panY = rect.height / 2 - cy * z;
        applyTransform();
        const el = document.querySelector('.group-box[data-id="' + elementId + '"]');
        if(el){ el.classList.add('jump-flash'); setTimeout(() => el.classList.remove('jump-flash'), 1200); }
      }
    } else if(kind === 'link' || kind === 'doc' || kind === 'video'){
      const arr = kind === 'link' ? state.links : kind === 'doc' ? state.documents : state.videoEmbeds;
      const item = (arr || []).find(x => x.id === elementId);
      if(item){
        const rect = viewport.getBoundingClientRect();
        const z = state.view.zoom || 1;
        const cx = item.x + ((item.w || 320) / 2);
        const cy = item.y + 80;
        state.view.panX = rect.width / 2 - cx * z;
        state.view.panY = rect.height / 2 - cy * z;
        applyTransform();
      }
    }
  }, 60);
}

function _kindLabel(k){
  switch(k){
    case 'beat':      return 'Beat';
    case 'note':      return 'Note';
    case 'thought':   return 'Thought';
    case 'gallery':   return 'Gallery';
    case 'character': return 'Character';
    case 'location':  return 'Location';
    case 'prop':      return 'Prop';
    case 'palette':   return 'Palette';
    case 'title':     return 'Title';
    case 'group':     return 'Group';
    case 'link':      return 'Link';
    case 'doc':       return 'Doc';
    case 'video':     return 'Video';
    default:          return k || 'Item';
  }
}

