const _loadedScripts = new Set();
function loadScript(src){
  return new Promise((resolve, reject) => {
    if(_loadedScripts.has(src)) return resolve();
    const existing = document.querySelector('script[src="'+src+'"]');
    if(existing){ _loadedScripts.add(src); return resolve(); }
    const s = document.createElement('script');
    s.src = src; s.async = true;
    s.onload = ()=>{ _loadedScripts.add(src); resolve(); };
    s.onerror = ()=>reject(new Error('Failed to load ' + src));
    document.head.appendChild(s);
  });
}

// Leaflet is vendored; loaded on first map use. CSS injected once; explicit
// imagePath skips L.Icon.Default's runtime path detection (unreliable in webviews).
let _leafletReady = null;
function loadLeaflet(){
  if(_leafletReady) return _leafletReady;
  _leafletReady = (async () => {
    if(!document.querySelector('link[data-leaflet]')){
      const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = 'vendor/leaflet/leaflet.css'; l.dataset.leaflet = '1';
      document.head.appendChild(l);
    }
    await loadScript('vendor/leaflet/leaflet.js');
    if(window.L && L.Icon && L.Icon.Default) L.Icon.Default.imagePath = 'vendor/leaflet/images/';
    return window.L;
  })().catch(e => { _leafletReady = null; throw e; }); // reset memo so a later attempt retries
  return _leafletReady;
}
// Esri's keyless street basemap. Was tile.openstreetmap.org, which OSM's own
// tile usage policy asks third party apps NOT to use (Stephen Follows, audit
// 2026-09-08). Esri already serves the satellite layer below, same terms,
// attribution required and given.
const OSM_TILES = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}';
const OSM_ATTR = 'Tiles &copy; Esri &mdash; Source: Esri, DeLorme, NAVTEQ, USGS, Intermap, iPC, NRCAN, Esri Japan, METI, TomTom';
// Esri World Imagery — keyless satellite basemap, attribution required.
const ESRI_SAT_TILES = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';
const ESRI_SAT_ATTR = 'Tiles &copy; Esri &mdash; Source: Esri, Maxar, Earthstar Geographics';
// Canvas-style map navigation: two-finger swipe pans, pinch (wheel+ctrlKey)
// zooms — the same gestures as Beat's canvas. Leaflet's scrollWheelZoom is
// disabled on these maps; this non-passive listener replaces it (zoom steps
// throttled to one per 80ms so trackpad pinches don't fly through levels).
function wireCanvasMapNav(map, el){
  let lastZoomAt = 0;
  el.addEventListener('wheel', ev => {
    ev.preventDefault();
    if(ev.ctrlKey){
      const now = Date.now();
      if(now - lastZoomAt < 80) return;
      lastZoomAt = now;
      map.setZoomAround(map.mouseEventToLatLng(ev), map.getZoom() + (ev.deltaY < 0 ? 1 : -1));
    } else {
      map.panBy([ev.deltaX, ev.deltaY], { animate: false });
    }
  }, { passive: false });
}

function hexToHsl(hex){
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex || '');
  if(!m) return { h: 16, s: 47, l: 64 };
  const r = parseInt(m[1],16)/255, g = parseInt(m[2],16)/255, b = parseInt(m[3],16)/255;
  const max = Math.max(r,g,b), min = Math.min(r,g,b);
  let h, s, l = (max+min)/2;
  if(max === min){ h = 0; s = 0; }
  else {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch(max){
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }
    h *= 60;
  }
  return { h: Math.round(h), s: Math.round(s*100), l: Math.round(l*100) };
}
function hslStr(h, s, l, a){
  if(a == null) return 'hsl('+h+','+s+'%,'+l+'%)';
  return 'hsla('+h+','+s+'%,'+l+'%,'+a+')';
}
function derivePastelPalette(mainHex){
  const { h } = hexToHsl(mainHex);
  return {
    '--bg':              hslStr(h, 38, 95),
    '--bg-bar':          hslStr(h, 42, 90),
    '--bg-bar-border':   hslStr(h, 32, 82),
    '--bg-modal-head':   hslStr(h, 42, 91),
    '--bg-input':        hslStr(h, 40, 96),
    '--bg-input-focus':  hslStr(h, 50, 98),
    '--bg-prod':         hslStr(h, 38, 92),
    '--bg-thumb':        hslStr(h, 38, 92),
    '--bg-add-img':      hslStr(h, 50, 92),
    '--bg-add-img-hover':hslStr(h, 45, 88),
    '--bg-tag-hover':    hslStr(h, 50, 88),
    '--bg-act-hover':    hslStr(h, 40, 90),
    '--surface':         hslStr(h, 60, 98),
    '--surface-alt':     hslStr(h, 50, 95),
    '--surface-sel':     hslStr(h, 50, 92),
    '--border':          hslStr(h, 30, 86),
    '--border-soft':     hslStr(h, 28, 89),
    '--border-input':    hslStr(h, 30, 86),
    '--border-tag':      hslStr(h, 20, 30, 0.22),
    '--border-bar':      hslStr(h, 32, 82),
    '--border-head':     hslStr(h, 32, 86),
    '--border-dashed':   hslStr(h, 30, 70),
    '--border-alt':      hslStr(h, 28, 68),
    '--border-action':   hslStr(h, 30, 80),
    '--border-hover':    hslStr(h, 38, 70),
    '--text':            hslStr(h, 18, 20),
    '--text-body':       hslStr(h, 14, 26),
    '--text-soft':       hslStr(h, 14, 36),
    '--text-mute':       hslStr(h, 22, 46),
    '--text-faint':      hslStr(h, 18, 54),
    '--text-hint':       hslStr(h, 16, 60),
    '--text-add-img':    hslStr(h, 30, 38),
    '--text-tag-none':   hslStr(h, 14, 52),
    '--text-x-hover':    hslStr(h, 50, 42),
    '--accent':          mainHex,
    '--accent-hover':    hslStr(h, 42, 56),
    '--accent-deep':     hslStr(h, 42, 44),
    '--accent-on':       hslStr(h, 60, 96),
    '--accent-shadow':   hslStr(h, 50, 60, 0.30),
    // Default (pastel) keeps pointing in the user's own colour — the ink/amber
    // split is a Light/Dark decision, not this theme's.
    '--point':           mainHex,
    '--point-hover':     hslStr(h, 42, 56),
    '--point-on':        hslStr(h, 60, 96),
    '--point-shadow':    hslStr(h, 50, 60, 0.30),
    '--edge':            mainHex,
    '--grid-dot':        hslStr(h, 32, 82),
    '--shadow-node':     '0 1px 2px ' + hslStr(h, 18, 20, 0.04),
    '--shadow-bimg':     '0 1px 3px ' + hslStr(h, 18, 20, 0.06),
    '--shadow-port':     '0 1px 4px '  + hslStr(h, 18, 20, 0.22),
    '--shadow-modal':    '0 2px 6px ' + hslStr(h, 18, 20, 0.05) + ', 0 22px 56px ' + hslStr(h, 18, 20, 0.13),
    '--backdrop':        hslStr(h, 18, 20, 0.42),
    // ===== Lumen tokens (V1.5 redesign) =====
    '--hue-note':        '#C99C3A',
    '--hue-thought':     '#7E96C8',
    '--hue-char':        '#A87CA0',
    '--glow':            '0',
    '--corelight':       '#FFFFFF',
    '--frost':           hslStr(h, 45, 97, 0.86),
    '--frostline':       'rgba(255,255,255,.85)',
    // Alternative-beat tint — shift the user's hue ~180° (cool complement) at low saturation.
    '--alt-beat-bg':     hslStr((h + 180) % 360, 22, 92),
    '--alt-beat-border': hslStr((h + 180) % 360, 18, 72),
    '--alt-beat-head':   hslStr((h + 180) % 360, 18, 86),
  };
}

const _pastelVarNames = ['--bg','--bg-bar','--bg-bar-border','--bg-modal-head','--bg-input','--bg-input-focus','--bg-prod','--bg-thumb','--bg-add-img','--bg-add-img-hover','--bg-tag-hover','--bg-act-hover','--surface','--surface-alt','--surface-sel','--border','--border-soft','--border-input','--border-tag','--border-bar','--border-head','--border-dashed','--border-alt','--border-action','--border-hover','--text','--text-body','--text-soft','--text-mute','--text-faint','--text-hint','--text-add-img','--text-tag-none','--text-x-hover','--accent','--accent-hover','--accent-deep','--accent-on','--accent-shadow','--point','--point-hover','--point-on','--point-shadow','--edge','--grid-dot','--shadow-node','--shadow-bimg','--shadow-port','--shadow-modal','--backdrop','--alt-beat-bg','--alt-beat-border','--alt-beat-head','--hue-note','--hue-thought','--hue-char','--glow','--corelight','--frost','--frostline'];

// ===== Accent mode — hybrid (ink chrome, amber pointer) / mono / amber =====
// A token switch while the accent is being chosen. No UI: the attribute rides
// on <body> and the CSS does the rest. Absent attribute = hybrid, so the app
// is already right before this runs.
const ACCENT_MODES = ['hybrid', 'mono', 'amber'];
function accentMode(){
  let m = null;
  try { m = localStorage.getItem('bts:accent'); } catch(e){}
  return ACCENT_MODES.includes(m) ? m : 'hybrid';
}
function _writeAccentAttr(m){
  if(m === 'hybrid') document.body.removeAttribute('data-accent');
  else document.body.setAttribute('data-accent', m);
}
function applyAccentMode(mode){
  const m = ACCENT_MODES.includes(mode) ? mode : accentMode();
  try { localStorage.setItem('bts:accent', m); } catch(e){}
  _writeAccentAttr(m);
  // Wires and the minimap paint the accent onto canvases — repaint both.
  try { renderMinimap(); render(); } catch(e){}
  return m;
}
_writeAccentAttr(accentMode());
window.beatAccent = applyAccentMode;

// ===== The card design (2026-08-09): A/'sheet' WON the testing round. =====
// The attribute stays because the card CSS is scoped to it; the switch, the
// other candidates and the Preferences section are gone.
document.body.setAttribute('data-cards', 'sheet');
function cardMode(){ return 'sheet'; }

function applyTheme(themeObj){
  const root = document.documentElement;
  const body = document.body;
  _pastelVarNames.forEach(v => root.style.removeProperty(v));
  let mode = (themeObj && themeObj.mode) || 'default';
  if(mode === 'pastel') mode = 'default'; // legacy alias — pastel became Default
  if(mode === 'light' || mode === 'dark'){
    body.setAttribute('data-theme', mode);
  } else {
    body.setAttribute('data-theme', 'default');
    const color = (themeObj && themeObj.color) || '#C8825F';
    const palette = derivePastelPalette(color);
    Object.keys(palette).forEach(k => root.style.setProperty(k, palette[k]));
  }
  // The minimap paints theme colors onto a cached canvas — rebuild it so a
  // theme switch doesn't leave the old theme's accent rect / node fills behind.
  if(typeof renderMinimap === 'function') renderMinimap();
}
