function migrateCommentsToInline(s){
  if(!s || !Array.isArray(s.comments)) return;
  s.comments.forEach(c => {
    if(!c || !c.targetType || !c.targetId) return;
    let anchor = null;
    if(c.targetType === 'node') anchor = (s.nodes || []).find(n => n.id === c.targetId);
    else if(c.targetType === 'group') anchor = (s.groups || []).find(g => g.id === c.targetId);
    if(!anchor) return;
    const txt = (c.text || '').trim();
    if(!txt) return;
    if(!anchor.comment) anchor.comment = txt;
    else anchor.comment = anchor.comment + '\n\n' + txt;
  });
  delete s.comments;
}

function normalizeState(s, fallbackName){
  if(!s || !Array.isArray(s.nodes)) return null;
  // Round 48: a shared/hand-edited/connector-written file can carry null or
  // non-object entries (e.g. nodes:[null]). Every forEach below dereferences
  // entries unchecked — one bad entry threw and left the project unopenable
  // with no message. Sanitize each object-collection ONCE, up front (mirrors
  // the edge filter already present below). Cheap; runs on load only.
  const _objs = a => Array.isArray(a) ? a.filter(x => x && typeof x === 'object' && !Array.isArray(x)) : [];
  s.nodes = _objs(s.nodes);
  if(Array.isArray(s.groups)) s.groups = _objs(s.groups);
  if(Array.isArray(s.images)) s.images = _objs(s.images);
  if(Array.isArray(s.links)) s.links = _objs(s.links);
  if(Array.isArray(s.documents)) s.documents = _objs(s.documents);
  if(Array.isArray(s.mediaShelf)) s.mediaShelf = _objs(s.mediaShelf);
  if(Array.isArray(s.videoEmbeds)) s.videoEmbeds = _objs(s.videoEmbeds);
  s.nodes.forEach(n => {
    if(Array.isArray(n.shots)) n.shots = _objs(n.shots);
    if(Array.isArray(n.scenes)) n.scenes = _objs(n.scenes);
  });
  if(!Array.isArray(s.images)) s.images = [];
  if(!Array.isArray(s.edges)) s.edges = [];
  if(!s.view) s.view = {panX:0,panY:0,zoom:1};
  if(typeof s.view.writeOpen !== 'boolean') s.view.writeOpen = false;   // Writing Mode pane
  if(typeof s.view.writeFocus !== 'boolean') s.view.writeFocus = false; // Writing Mode focus (dim non-active blocks)
  if(s.view.writeTheme !== 'light' && s.view.writeTheme !== 'dark') s.view.writeTheme = ''; // '' = follow the app theme
  const ws = s.view.writeSplit;                                          // doc-pane share, 0.2–1 (1 = full doc)
  if(typeof ws !== 'number' || !(ws >= 0.2 && ws <= 1)) s.view.writeSplit = 0.44;
  if(typeof s.context !== 'string') s.context = '';
  if(!s.theme) s.theme = Object.assign({}, DEFAULT_THEME);
  // Theme restructure: 'pastel' became 'default' (same tint engine) — keep the
  // user's saved color so their project looks unchanged. Unknown/missing modes
  // fall back to the Default theme with the stock terracotta tint.
  if(s.theme.mode === 'pastel') s.theme.mode = 'default';
  if(s.theme.mode !== 'default' && s.theme.mode !== 'light' && s.theme.mode !== 'dark') s.theme = Object.assign({}, DEFAULT_THEME);
  if(s.theme.mode === 'default' && !s.theme.color) s.theme.color = '#C8825F';
  if(!s.templateId) s.templateId = 'blank';
  // Edges must point at things that exist — a dangling edge claims a socket
  // slot and renders a plugged ring with no wire. The app's own deletes cascade;
  // this catches files written by hand or by the connector.
  if(Array.isArray(s.edges)){
    const endpointIds = new Set([].concat(
      (s.nodes || []).map(n => n && n.id),
      (s.groups || []).map(g => g && g.id)).filter(Boolean));
    s.edges = s.edges.filter(e => e && endpointIds.has(e.from) && endpointIds.has(e.to));
  }
  if(typeof s.name !== 'string') s.name = fallbackName || 'Untitled project';
  if(s.numberingMode !== 'manual' && s.numberingMode !== 'none') s.numberingMode = 'auto';
  if(typeof s.showAuthorCredit !== 'boolean') s.showAuthorCredit = true; // Wave 2: per-project export-credit opt-out
  // W1.7 — project identity (company / contact / logo) printed on export covers.
  // Project-owned: independent of showAuthorCredit, which governs only the
  // PERSONAL credit. logo = asset filename (Tauri) or data URL (legacy).
  if(!s.identity || typeof s.identity !== 'object' || Array.isArray(s.identity)) s.identity = { company:'', contact:'', logo:null };
  if(typeof s.identity.company !== 'string') s.identity.company = '';
  if(typeof s.identity.contact !== 'string') s.identity.contact = '';
  if(typeof s.identity.logo !== 'string' || !s.identity.logo) s.identity.logo = null;
  s.nodes.forEach(n => {
    if(!n.type) n.type = 'beat';
    // Phase A fields. Backwards-compatible — older saves load cleanly.
    if(typeof n.slug !== 'string') n.slug = '';            // #29 slug-line
    if(!Array.isArray(n.tones)) n.tones = [];              // #9  tone tags
    if(!Array.isArray(n.elements)) n.elements = [];       // craft/production element tags (Shot, Prop…)
    if(!n.elementNotes || typeof n.elementNotes !== 'object' || Array.isArray(n.elementNotes)) n.elementNotes = {}; // per-element note ("Prop": "the letter")
    if(!Array.isArray(n.documents)) n.documents = [];       // #84 per-beat attached docs
    if(typeof n.collapsed !== 'boolean') n.collapsed = false; // Phase L collapse
    if(typeof n.hidden !== 'boolean') n.hidden = false;
    if(typeof n.seqStart !== 'boolean') n.seqStart = false;  // sequence/episode start flag
    if(typeof n.seqName !== 'string') n.seqName = '';        // sequence/episode display name
    // Contextual layer: role decoupled from type, explicit group membership + order.
    if(typeof n.role !== 'string') n.role = '';
    if(!('groupId' in n)) n.groupId = null;
    if(!('order' in n)) n.order = null;
    if(typeof n.hiddenInExport !== 'boolean') n.hiddenInExport = false;
    // W4.1 — custom-field values ({ fieldId: value }) + per-card ad-hoc fields.
    // Values for DELETED definitions are kept in `fields` (cheap, safe) — they
    // just don't render. ownFields heal to { id, label, value } strings; ids
    // via _mkNormId (runs during the legacy boot load, before seedUid).
    if(!n.fields || typeof n.fields !== 'object' || Array.isArray(n.fields)) n.fields = {};
    Object.keys(n.fields).forEach(k => { if(typeof n.fields[k] !== 'string') n.fields[k] = String(n.fields[k] == null ? '' : n.fields[k]); });
    if(!Array.isArray(n.ownFields)) n.ownFields = [];
    n.ownFields = n.ownFields
      .filter(f => f && typeof f === 'object' && !Array.isArray(f))
      .map(f => {
        const out = {
          id: (typeof f.id === 'string' && f.id) ? f.id : _mkNormId('cf'),
          label: (typeof f.label === 'string' && f.label.trim()) ? f.label.trim() : 'Field',
          value: (typeof f.value === 'string') ? f.value : String(f.value == null ? '' : f.value)
        };
        // Checklist fields (Casey Cross, beta 3: "can a checklist be an option
        // for a field within a Beat?"). A checklist keeps its ticks in `items`
        // and leaves `value` alone, so a file written by an older Beat still
        // loads and a checklist downgraded back to text keeps whatever it had.
        if(f.kind === 'checklist'){
          out.kind = 'checklist';
          out.items = (Array.isArray(f.items) ? f.items : [])
            .filter(i => i && typeof i === 'object' && !Array.isArray(i))
            .map(i => ({ t: typeof i.t === 'string' ? i.t : String(i.t == null ? '' : i.t), done: !!i.done }));
        }
        return out;
      });
    // Checklist CARD items ({t, done}) — same healing as the checklist field.
    if((n.type || 'beat') === 'checklist'){
      n.items = (Array.isArray(n.items) ? n.items : [])
        .filter(i => i && typeof i === 'object' && !Array.isArray(i))
        .map(i => ({ t: typeof i.t === 'string' ? i.t : String(i.t == null ? '' : i.t), done: !!i.done }));
      if(!n.items.length) n.items = [{ t: '', done: false }];
    }
    // Per-image export marks: drop refs no longer on the node; ABSENT stays absent.
    if(Array.isArray(n.exportImages)) n.exportImages = n.exportImages.filter(r => (n.images||[]).includes(r));
    // Per-image captions (W1.5): { ref: string }. Keep only live refs with
    // non-blank text — empty/whitespace caption VALUES are always dropped.
    // The OBJECT property itself: absent stays absent, and once created it is
    // never deleted, even when emptied (mirrors exportImages).
    if(n.imageCaptions && typeof n.imageCaptions === 'object' && !Array.isArray(n.imageCaptions)){
      const live = {};
      Object.keys(n.imageCaptions).forEach(r => {
        const v = n.imageCaptions[r];
        if(typeof v === 'string' && v.trim() && (n.images||[]).includes(r)) live[r] = v;
      });
      n.imageCaptions = live;
    } else if(n.imageCaptions !== undefined) delete n.imageCaptions;
    // Original filenames per image ref (Chris Walton, 2026-07-28) — same
    // lifecycle as imageCaptions: live refs only, object never deleted.
    if(n.imageNames && typeof n.imageNames === 'object' && !Array.isArray(n.imageNames)){
      const liveN = {};
      Object.keys(n.imageNames).forEach(r => {
        const v = n.imageNames[r];
        if(typeof v === 'string' && v.trim() && (n.images||[]).includes(r)) liveN[r] = v;
      });
      n.imageNames = liveN;
    } else if(n.imageNames !== undefined) delete n.imageNames;
    // Per-image GPS lifted off the ORIGINAL photo at add time (Joao, 2026-08-02)
    // — what the hover "Location from photo" badge on a thumb is gated on. Same
    // lifecycle as imageNames: live refs only, object never deleted once
    // created, an entry without a usable lat/lon dropped.
    if(n.imageGeo && typeof n.imageGeo === 'object' && !Array.isArray(n.imageGeo)){
      const liveG = {};
      Object.keys(n.imageGeo).forEach(r => {
        const v = n.imageGeo[r];
        if(v && typeof v === 'object' && !Array.isArray(v) &&
           typeof v.lat === 'number' && isFinite(v.lat) &&
           typeof v.lon === 'number' && isFinite(v.lon) &&
           (n.images||[]).includes(r)) liveG[r] = v;
      });
      n.imageGeo = liveG;
    } else if(n.imageGeo !== undefined) delete n.imageGeo;
    // W3.7 — sun tracker stamp: heal malformed (non-object → delete); a
    // healthy stamp passes through untouched, absent stays absent.
    if(n.sunInfo !== undefined && (!n.sunInfo || typeof n.sunInfo !== 'object' || Array.isArray(n.sunInfo))) delete n.sunInfo;
    // S1 — the scrubbed shoot time. A stamp from before S1 simply has no
    // timeMin; the scout re-derives solar noon for it, which is exactly what
    // that stamp meant. Garbage (non-number / out of a day) is dropped so the
    // arc can never open on an impossible minute.
    if(n.sunInfo && typeof n.sunInfo === 'object' && !Array.isArray(n.sunInfo) && n.sunInfo.timeMin !== undefined){
      const tm = n.sunInfo.timeMin;
      if(typeof tm !== 'number' || !isFinite(tm) || tm < 0 || tm >= 1440) delete n.sunInfo.timeMin;
    }
    // S4 — a beat's sun plan. It stores ONLY the three inputs; azimuth, phase
    // and shadow are derived live from the location's pin (see beatSunPlan).
    // Heal to null when the shape is wrong, the location is gone, it isn't a
    // location, or it has no pin — a plan we cannot compute must never linger
    // and print a stale moment. (deleteNode / deleteSelection cascade live.)
    if(n.sun !== undefined){
      const p = n.sun;
      const shaped = p && typeof p === 'object' && !Array.isArray(p) &&
        typeof p.locationId === 'string' && p.locationId &&
        typeof p.dateISO === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(p.dateISO) &&
        typeof p.timeMin === 'number' && isFinite(p.timeMin) && p.timeMin >= 0 && p.timeMin < 1440;
      const loc = shaped ? s.nodes.find(x => x.id === p.locationId) : null;
      // S7 — showPlot is the one non-input the plan carries: the per-beat opt-in
      // for the full diagram on the card (Joao asked for the big plot, but only
      // where he wants it). Kept ONLY when strictly true, so a non-boolean — or
      // a beat that turned it back off — simply drops out of the saved file.
      n.sun = (loc && loc.type === 'location' && loc.geo &&
               typeof loc.geo.lat === 'number' && typeof loc.geo.lon === 'number')
        ? Object.assign({ locationId: p.locationId, dateISO: p.dateISO, timeMin: Math.round(p.timeMin) },
                        p.showPlot === true ? { showPlot: true } : null)
        : null;
    }
    // W4.2 — audio-timeline timecode stamp (seconds); null = none.
    if(typeof n.tc !== 'number' || !isFinite(n.tc) || n.tc < 0) n.tc = null;
    if(n.type === 'setplan') n.plan = normalizeSetPlan(n.plan);
    // W3.6 — a Set Plan links to ANY card via linkId. One-time migration folds
    // the T1.3-era locationId into linkId (when linkId is absent), then the
    // heal drops a dangling link: target gone, self, or another setplan.
    // deleteNode cascades the same cleanup live; this catches older saves.
    if(n.type === 'setplan'){
      if(n.locationId !== undefined){
        if(!n.linkId && n.locationId) n.linkId = n.locationId;
        delete n.locationId;
      }
      if(!('linkId' in n)) n.linkId = null;
      if(n.linkId){
        const t = s.nodes.find(x => x.id === n.linkId);
        if(!t || t.id === n.id || t.type === 'setplan') n.linkId = null;
      }
    }
    if(n.type === 'shotlist'){
      if(typeof n.title !== 'string' || !n.title) n.title = 'Shot list';
      if(!Array.isArray(n.shots)) n.shots = [];
      if(n.orderMode !== 'custom') n.orderMode = 'story';           // round 27: the AD's order
      n.onsetElapsed = (typeof n.onsetElapsed === 'number' && n.onsetElapsed > 0) ? Math.floor(n.onsetElapsed) : 0;
      n.onsetRunning = n.onsetRunning === true;
      // Round 34: the day's CALL TIME ('HH:MM') — when set, the day clock
      // anchors to the schedule instead of the ▶ button.
      n.callTime = (typeof n.callTime === 'string' && /^\d{2}:\d{2}$/.test(n.callTime)) ? n.callTime : null;
      // Item 7 (round 79) — the shoot day: date, location reference, crew, notes.
      // The stored fields are the three INPUTS; sun times, scene names and cast
      // are computed at print time from live nodes (the sun-plan pattern).
      n.shootDate = (typeof n.shootDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(n.shootDate)) ? n.shootDate : null;
      if(n.shootLocationId !== undefined && n.shootLocationId !== null){
        const _sdLoc = (typeof n.shootLocationId === 'string' && n.shootLocationId)
          ? s.nodes.find(x => x.id === n.shootLocationId) : null;
        n.shootLocationId = (_sdLoc && _sdLoc.type === 'location') ? n.shootLocationId : null;
      } else n.shootLocationId = null;
      if(!Array.isArray(n.crew)) n.crew = [];
      { const seenP = new Set();
        n.crew = n.crew
          .filter(c => c && typeof c === 'object' && !Array.isArray(c) &&
                       typeof c.personId === 'string' && c.personId &&
                       !seenP.has(c.personId) && seenP.add(c.personId))
          .map(c => ({ personId: c.personId,
                       call: (typeof c.call === 'string' && /^\d{2}:\d{2}$/.test(c.call)) ? c.call : '' })); }
      if(typeof n.dayNotes !== 'string') n.dayNotes = '';
      // numberStyle (round 1): 'flat' = 1,2,3 continuous; 'scene' = 1A,1B,2A… industry.
      if(n.numberStyle !== 'flat' && n.numberStyle !== 'scene') n.numberStyle = 'flat';
      // Item 9 (round 81): the day strip's only stored bit — kept ONLY when
      // strictly true (the n.sun.showPlot pattern), so saves stay tidy.
      if(n.dayStripHidden !== true) delete n.dayStripHidden;
      // Item 8 (round 80): the wrap marker — the day is closed. wrappedAt is the
      // stored FACT (ISO datetime at the wrap moment); wrappedTo points at the
      // day the rest was carried to. A dangling wrappedTo (destination deleted)
      // heals to null so the wrap bar never points at a ghost.
      n.wrappedAt = (typeof n.wrappedAt === 'string' && n.wrappedAt) ? n.wrappedAt : null;
      n.wrappedTo = (typeof n.wrappedTo === 'string' && n.wrappedTo) ? n.wrappedTo : null;
      if(n.wrappedTo && !(s.nodes || []).some(x => x && x.id === n.wrappedTo && x.type === 'shotlist'))
        n.wrappedTo = null;
      n.shots.forEach(sh => {
        if(!sh.id) sh.id = _mkNormId('sh');
        // Text fields heal to a string. The four dropdown fields are handled
        // separately below because they may legitimately hold an ARRAY (a multi-
        // value column, round 11) — clobbering those to '' would lose data on load.
        ['subject','description','script','duration'].forEach(k => {
          if(typeof sh[k] !== 'string') sh[k] = '';
        });
        // Dropdown fields (intext/shot/lens/move): keep an array as-is (multi), keep
        // a string as-is (single/legacy), and normalise anything else to ''. A stray
        // array of junk is filtered to clean strings so nothing downstream chokes.
        // Round 16: INT/EXT became Location. A value that is ONLY the old
        // binary carries no information the slug-line doesn't — clear it so
        // the beat-pulled location shows through. Typed real values survive.
        if(Array.isArray(sh.intext)) sh.intext = sh.intext.filter(v => !/^(INT|EXT|INT\/EXT|I\/E)\.?$/i.test(String(v).trim())).join(' / ');
        if(typeof sh.intext === 'string' && /^(INT|EXT|INT\/EXT|I\/E)\.?$/i.test(sh.intext.trim())) sh.intext = '';
        // On set (round 17): the operator's marks live on the shot.
        // Round 19: a linked beat's first image becomes the shot's reference
        // automatically (Joao) — only when the shot has none of its own.
        if(!sh.ref && sh.beatId){
          const _b = (s.nodes || []).find(x => x.id === sh.beatId);
          if(_b && Array.isArray(_b.images) && _b.images[0]) sh.ref = _b.images[0];
        }
        sh.skipped = sh.skipped === true;
        sh.takes = Number.isInteger(sh.takes) && sh.takes > 0 ? sh.takes : 0;
        // Round 48: the OLD clamp `sh.take <= sh.takes` used to run here and
        // nulled the chosen take whenever takes was 0 — which is ALWAYS true
        // for On-set-only shooting (every take control writes sh.take alone,
        // never sh.takes). That silently wiped the shoot-day record on reload.
        // Line below (round 27's rule) is the whole contract: chosen take is
        // any integer >= 1, independent of the retired count.
        if(typeof sh.obs !== 'string') sh.obs = '';
        sh.secs = (typeof sh.secs === 'number' && sh.secs > 0) ? Math.floor(sh.secs) : 0; // time on the shot (round 24)
        // round 27: the CHOSEN take stands alone (count retired from the UI);
        // shootOrder is the AD's running order when the list runs custom.
        if(!(Number.isInteger(sh.take) && sh.take >= 1)) sh.take = null;
        sh.shootOrder = Number.isInteger(sh.shootOrder) ? sh.shootOrder : null;
        // round 28: anything on the canvas can hang off a shot (and a scene)
        if(!Array.isArray(sh.linkIds)) sh.linkIds = [];
        sh.linkIds = sh.linkIds.filter(x => typeof x === 'string');
        if(sh.done && sh.skipped) sh.skipped = false; // mutually exclusive; done wins
        ['intext','shot','lens','move'].forEach(k => {
          const v = sh[k];
          if(Array.isArray(v)) sh[k] = v.map(x => String(x == null ? '' : x)).filter(Boolean);
          else if(typeof v !== 'string') sh[k] = '';
        });
        // sceneColor (v1, per-shot) is retired in favour of first-class scenes below,
        // but keep the value around during migration so its colour carries onto the scene.
        if(typeof sh.sceneColor !== 'string') sh.sceneColor = null;
        // ref (round 2a): a single per-shot reference image — FILENAME under Tauri,
        // dataURL in legacy, null when empty. Kept out of the string-field loop above
        // so a dataURL isn't clobbered to ''.
        if(typeof sh.ref !== 'string') sh.ref = null;
        // round 25: refs[] — a shot can carry several stills; ref mirrors refs[0]
        if(!Array.isArray(sh.refs)) sh.refs = [];
        sh.refs = sh.refs.filter(r => typeof r === 'string' && r);
        if(sh.ref && !sh.refs.includes(sh.ref)) sh.refs.unshift(sh.ref);
        sh.ref = sh.refs[0] || null;
        // custom (round 4): free-text values for user-added columns, keyed by the
        // column's key. Heal to an object so custom cells never read undefined.
        if(!sh.custom || typeof sh.custom !== 'object' || Array.isArray(sh.custom)) sh.custom = {};
      });
      // Custom columns (round 4): node.columns is an ordered column config. A list
      // with none → seed the nine built-ins in order. Heal shape so each entry has
      // a key/label/type; drop any built-in duplicates and any entry missing a key.
      if(!Array.isArray(n.columns) || !n.columns.length){
        n.columns = _defaultShotColumns();
      } else {
        const seen = new Set();
        n.columns = n.columns.filter(c => c && typeof c.key === 'string' && c.key && !seen.has(c.key) && seen.add(c.key)).map(c => {
          const bi = _shotlistBuiltin(c.key);
          // `multi` (round 11) only rides on dropdown columns; preserve it so a
          // multi list survives a reload. Text/# built-ins never carry it.
          if(bi) return { key:c.key, label:(typeof c.label === 'string' && c.label) ? c.label : bi.label, type:'builtin', builtin:true, hidden: !!c.hidden, multi: _shotlistBuiltinIsDropdown(c.key) ? !!c.multi : false };
          // W4.1 — beat-field column: keep its fieldId (the definition it
          // mirrors); a fieldId-less entry is junk and is dropped below.
          if(c.type === 'beatfield') return { key:c.key, label:(typeof c.label === 'string' && c.label) ? c.label : 'Beat field', type:'beatfield', fieldId:(typeof c.fieldId === 'string' ? c.fieldId : ''), builtin:false, hidden: !!c.hidden, multi:false };
          const isDrop = (c.type === 'dropdown');
          return { key:c.key, label:(typeof c.label === 'string' ? c.label : 'Column'), type:(isDrop ? 'dropdown' : 'text'), builtin:false, hidden: !!c.hidden, multi: isDrop ? !!c.multi : false };
        }).filter(c => c.type !== 'beatfield' || c.fieldId);
        // Ensure every built-in is present (append any missing at the end, unhidden)
        // so an older/partial config never loses structured columns.
        SHOTLIST_BUILTINS.forEach(bi => {
          if(!n.columns.some(c => c.key === bi.key)) n.columns.push({ key:bi.key, label:bi.label, type:'builtin', builtin:true, hidden:false, multi:false });
        });
        if(!n.columns.length) n.columns = _defaultShotColumns();
      }
      // The reference-image column shipped as 'Ref' (cryptic — users didn't find
      // it). Relabel any UN-customized built-in ref column to 'Image' so existing
      // lists read clearly; a user's own rename (any other text) is preserved.
      const _refCol = n.columns.find(c => c && c.builtin && c.key === 'ref');
      if(_refCol && _refCol.label === 'Ref') _refCol.label = 'Image';
      // First-class scenes (round 1): node.scenes = [{id, heading, color, collapsed}];
      // each shot carries sceneId. Migrate legacy lists (shots but no scenes): make one
      // default scene, adopt any per-shot sceneColor as the scene colour, assign all shots.
      if(!Array.isArray(n.scenes) || !n.scenes.length){
        const carried = (n.shots.find(sh => sh.sceneColor) || {}).sceneColor || null;
        const sc = { id:_mkNormId('sc'), heading:'', color:carried, collapsed:false };
        n.scenes = [sc];
        n.shots.forEach(sh => { sh.sceneId = sc.id; });
      }
      n.scenes.forEach(sc => {
        if(!sc.id) sc.id = _mkNormId('sc');
        if(typeof sc.heading !== 'string') sc.heading = '';
        if(typeof sc.color !== 'string') sc.color = null;
        if(!Array.isArray(sc.linkIds)) sc.linkIds = [];
        sc.linkIds = sc.linkIds.filter(x => typeof x === 'string');
        if(typeof sc.collapsed !== 'boolean') sc.collapsed = false;
        // Round 53: the canvas group a scene was born from (editable name after)
        if(typeof sc.groupId !== 'string') sc.groupId = null;
      });
      // Heal orphan shots (sceneId missing or pointing at a deleted scene) → first scene.
      const sceneIds = new Set(n.scenes.map(s => s.id));
      n.shots.forEach(sh => { if(!sh.sceneId || !sceneIds.has(sh.sceneId)) sh.sceneId = n.scenes[0].id; });
    }
  });
  if(!Array.isArray(s.groups)) s.groups = [];
  s.groups.forEach(g => {
    if(typeof g.hidden !== 'boolean') g.hidden = false;
    if(typeof g.role !== 'string') g.role = '';
    if(!('order' in g)) g.order = null;
    if(typeof g.hiddenInExport !== 'boolean') g.hiddenInExport = false;
  });
  if(!Array.isArray(s.links)) s.links = [];
  if(!Array.isArray(s.documents)) s.documents = [];
  if(!Array.isArray(s.mediaShelf)) s.mediaShelf = [];
  if(!Array.isArray(s.videoEmbeds)) s.videoEmbeds = [];
  // Shot list (roadmap 19) — project-level preset "cheat sheet", shared across all
  // shot lists in the project. Seed defaults when missing; heal individual lists.
  // Each preset may carry an optional `color` (a TAG_COLORS hex, or null) rendered
  // as an at-a-glance chip; missing colour normalises to null (round 3).
  // Item 7 (round 79) — the project contact pool. One pool every shoot day
  // draws from: Day 2 and Day 3 share the same gaffer, her phone is typed once.
  // People are NOT characters: a character is a story entity on the canvas, a
  // person is a phone number on a call sheet.
  if(!Array.isArray(s.people)) s.people = [];
  s.people = s.people
    .filter(p => p && typeof p === 'object' && !Array.isArray(p) && typeof p.name === 'string')
    .map(p => ({ id: (typeof p.id === 'string' && p.id) ? p.id : _mkNormId('pp'),
                 name: p.name, role: typeof p.role === 'string' ? p.role : '',
                 phone: typeof p.phone === 'string' ? p.phone : '',
                 email: typeof p.email === 'string' ? p.email : '' }));
  if(!s.shotPresets || typeof s.shotPresets !== 'object') s.shotPresets = {};
  if(!Array.isArray(s.shotPresets.intext) || !s.shotPresets.intext.length) s.shotPresets.intext = SHOT_PRESETS_DEFAULT.intext.slice();
  if(!Array.isArray(s.shotPresets.lens)   || !s.shotPresets.lens.length)   s.shotPresets.lens   = SHOT_PRESETS_DEFAULT.lens.slice();
  if(!Array.isArray(s.shotPresets.shot)   || !s.shotPresets.shot.length)   s.shotPresets.shot   = SHOT_PRESETS_DEFAULT.shot.map(o => ({ name:o.name, def:o.def, color:o.color||null }));
  if(!Array.isArray(s.shotPresets.move)   || !s.shotPresets.move.length)   s.shotPresets.move   = SHOT_PRESETS_DEFAULT.move.map(o => ({ name:o.name, def:o.def, color:o.color||null }));
  // Heal per-preset shape on already-saved lists: shot/move entries become
  // { name, def, color }; intext/lens stay strings unless a colour was assigned
  // (then { name, color }). Tolerates the pre-colour object/string forms.
  ['shot','move'].forEach(col => {
    s.shotPresets[col] = (s.shotPresets[col] || []).map(it => {
      if(typeof it === 'string') return { name:it, def:'', color:null };
      return { name:it.name, def:it.def || '', color:(typeof it.color === 'string' && it.color) ? it.color : null };
    });
  });
  ['intext','lens'].forEach(col => {
    s.shotPresets[col] = (s.shotPresets[col] || []).map(it => {
      if(typeof it === 'string') return it;                       // plain value, no colour
      if(it && typeof it === 'object'){
        return (typeof it.color === 'string' && it.color) ? { name:it.name, color:it.color } : it.name;
      }
      return it;
    });
  });
  // W4.1 — custom fields on beats: project-level definitions { id, label,
  // presets: [] } (order = display order). Heal malformed entries; preset
  // lists collapse to clean non-empty strings. Ids via _mkNormId (legacy boot
  // runs before seedUid — same rule as shot/scene ids above).
  if(!Array.isArray(s.customFields)) s.customFields = [];
  s.customFields = s.customFields
    .filter(f => f && typeof f === 'object' && !Array.isArray(f))
    .map(f => ({
      id: (typeof f.id === 'string' && f.id) ? f.id : _mkNormId('cf'),
      label: (typeof f.label === 'string' && f.label.trim()) ? f.label.trim() : 'Field',
      presets: Array.isArray(f.presets) ? f.presets.map(p => String(p == null ? '' : p).trim()).filter(Boolean) : []
    }));
  // W3.3 — custom set-plan palette symbols: { id, label, glyph } with glyph one
  // of SP_CUSTOM_GLYPHS. Project-level (same extend-a-library idea as
  // shotPresets). Heal malformed entries; placed 'custom:<id>' elements whose
  // symbol is gone fall back to a box at render time — never orphan-crash.
  if(!Array.isArray(s.spCustomProps)) s.spCustomProps = [];
  s.spCustomProps = s.spCustomProps
    .filter(c => c && typeof c === 'object' && typeof c.id === 'string' && c.id)
    .map(c => ({
      id: c.id,
      label: (typeof c.label === 'string' && c.label.trim()) ? c.label.trim() : 'Symbol',
      glyph: SP_CUSTOM_GLYPHS.includes(c.glyph) ? c.glyph : 'box'
    }));
  // Bindings (Phase L) — invisible bonds between items so they move
  // together when any one is dragged. Created via Shift-multi-select +
  // Link button. Item ids can be nodes, board images, links, video
  // embeds, documents, groups. Each item belongs to at most one binding.
  if(!Array.isArray(s.bindings)) s.bindings = [];
  { // Bindings only ever reference LIVE ids, and only in pairs or more —
    // older saves could carry members whose cards are long gone.
    const live = new Set([].concat((s.nodes||[]).map(n=>n.id), (s.images||[]).map(i=>i.id), (s.links||[]).map(l=>l.id), (s.documents||[]).map(d=>d.id), (s.videoEmbeds||[]).map(v=>v.id), (s.groups||[]).map(g=>g.id)));
    s.bindings.forEach(b => { b.members = (Array.isArray(b.members) ? b.members : []).filter(m => live.has(m)); });
    s.bindings = s.bindings.filter(b => (b.members || []).length >= 2);
    // A node pointing at a deleted group is an orphan, not a member.
    const liveGroups = new Set((s.groups||[]).map(g => g.id));
    (s.nodes||[]).forEach(n => { if(n.groupId && !liveGroups.has(n.groupId)) n.groupId = null; });
  }
  // Phase 17c: fill in extract-related fields if missing. Older entries
  // without these fall back to the legacy iframe renderer.
  for(const e of s.videoEmbeds){
    if(typeof e.platform !== 'string' && typeof e.platform !== 'object') e.platform = e.kind || null;
    if(!('title' in e)) e.title = null;
    if(!('thumbnailUrl' in e)) e.thumbnailUrl = null;
    if(!('extractKind' in e)) e.extractKind = null;
    if(!('durationS' in e)) e.durationS = null;
    // transient UI state — never persisted (see save())
    delete e.extractState;
    delete e.extractJobId;
    delete e.extractPercent;
  }
  // W4.2 — audio timeline: ONE track per project, { ref, name, duration,
  // markers: [{ id, t, label, beatId }] }. Heal shape or null; marker ids via
  // _mkNormId (legacy boot runs before seedUid — same rule as shot/scene ids);
  // beatId → null when the beat no longer exists (deleteNode/deleteSelection
  // cascade live; this catches older saves).
  if(s.audio && typeof s.audio === 'object' && !Array.isArray(s.audio) && typeof s.audio.ref === 'string' && s.audio.ref){
    const a = s.audio;
    if(typeof a.name !== 'string') a.name = 'Audio';
    if(typeof a.duration !== 'number' || !isFinite(a.duration) || a.duration < 0) a.duration = 0;
    if(!Array.isArray(a.markers)) a.markers = [];
    a.markers = a.markers
      .filter(m => m && typeof m === 'object' && !Array.isArray(m) && typeof m.t === 'number' && isFinite(m.t) && m.t >= 0)
      .map(m => ({
        id: (typeof m.id === 'string' && m.id) ? m.id : _mkNormId('am'),
        t: m.t,
        label: (typeof m.label === 'string') ? m.label : '',
        beatId: (typeof m.beatId === 'string' && m.beatId && s.nodes.some(n => n.id === m.beatId)) ? m.beatId : null
      }));
  } else s.audio = null;
  s.edges.forEach(e => {
    if(!e.type) e.type = 'continues';
    if(typeof e.label !== 'string') e.label = '';
    // Phase B #26 — optional condition string ("if Olivia trusts Marco").
    if(typeof e.condition !== 'string') e.condition = '';
  });
  if(Array.isArray(s.palette)) s.palette = s.palette.filter(c => typeof c === 'string' && /^#[0-9a-fA-F]{3,8}$/.test(c));
  if(!Array.isArray(s.palette) || !s.palette.length) s.palette = TAG_COLORS.slice();
  // Brainstorm panel removed in Phase 10a — drop any legacy field so it doesn't bloat saves.
  delete s.brainstorm;
  if(typeof s.snapToGrid !== 'boolean') s.snapToGrid = false;
  // GIF export width (px). 0 = original video width. Larger = crisper GIFs for treatments.
  if(typeof s.gifExportWidth !== 'number') s.gifExportWidth = 320;
  // V1.1 — "Customize Beat Nodes": which optional beat fields render on cards.
  // body + images are always shown and are NOT in this map. All default true so
  // existing projects look identical until the user changes something.
  if(!s.nodeFields || typeof s.nodeFields !== 'object') s.nodeFields = {};
  ['slug','tones','product','shotType','duration','color','comments'].forEach(k => {
    if(typeof s.nodeFields[k] !== 'boolean') s.nodeFields[k] = true;
  });
  // Clean cards (Casey): hide EMPTY optional fields until the card is hovered or
  // focused — zero-config tidy cards. Off by default so nothing changes unasked.
  if(typeof s.cleanBeatCards !== 'boolean') s.cleanBeatCards = false; // healed for old saves
  // One-time heal (2.0.5): the forced quiet-cards era left `true` baked into
  // projects nobody chose it for. Everyone restarts OFF (Joao's call: cards
  // show their fields by default); flipping the toggle after this sticks.
  if(!s._cleanCardsReset205){ s.cleanBeatCards = false; s._cleanCardsReset205 = true; }
  // P4 — card density. Absent on every pre-rework save: infer honestly. A board
  // already using the production family loads as 'pro' so nothing seems to
  // vanish; a clean story board starts 'simple'.
  if(s.cardDensity !== 'simple' && s.cardDensity !== 'pro'){
    const proSignal = (Array.isArray(s.customFields) && s.customFields.length > 0)
      || (s.nodes || []).some(n =>
           (n.product && String(n.product).trim()) ||
           (n.shotType && String(n.shotType).trim()) ||
           (n.duration && String(n.duration).trim()) ||
           (Array.isArray(n.tones) && n.tones.length) ||
           (Array.isArray(n.ownFields) && n.ownFields.length) ||
           n.seqStart === true ||
           n.type === 'shotlist' || n.type === 'setplan');
    s.cardDensity = proSignal ? 'pro' : 'simple';
  }
  // Zoom-out simplification is opt-in per project: hiding card chrome at low
  // zoom got in the way of organising the board, which is exactly what you
  // zoom out to do.
  if(typeof s.lodSimplify !== 'boolean') s.lodSimplify = false;
  // V1.1 — outline order mode: 'auto' (by canvas reading position) or 'custom'
  // (explicit group/node order from the Outline drives exports). Default auto.
  if(s.outlineOrder !== 'custom' && s.outlineOrder !== 'auto') s.outlineOrder = 'auto';
  // #101 Pomodoro state — per-project minutes default + session log.
  if(typeof s.pomodoroMinutes !== 'number' || s.pomodoroMinutes < 1 || s.pomodoroMinutes > 180) s.pomodoroMinutes = 30;
  if(!Array.isArray(s.pomodoroSessions)) s.pomodoroSessions = [];
  // Phase 8c: migrate legacy floating comments into per-element inline comment
  if((s.schemaVersion || 1) < 2){
    migrateCommentsToInline(s);
  }
  delete s.comments; // legacy field removed regardless
  if(!s.exportInclude || typeof s.exportInclude !== 'object') s.exportInclude = {};
  // W3.8 — Export Center: last chosen format + option values, per project.
  if(!s.exportCenter || typeof s.exportCenter !== 'object' || Array.isArray(s.exportCenter)) s.exportCenter = { lastFormat: 'overview', options: {} };
  if(typeof s.exportCenter.lastFormat !== 'string') s.exportCenter.lastFormat = 'overview';
  if(!s.exportCenter.options || typeof s.exportCenter.options !== 'object' || Array.isArray(s.exportCenter.options)) s.exportCenter.options = {};
  if(s.exportCenter.options.photos !== 'all') s.exportCenter.options.photos = 'marked';
  if(typeof s.exportCenter.options.brand !== 'boolean') s.exportCenter.options.brand = true;
  if(s.exportCenter.options.paper !== 'letter') s.exportCenter.options.paper = 'a4';
  // Print Layout designer — page frames placed over the canvas (world coords),
  // saved with the project. frames: [{id, x, y, w, h, order}].
  if(!s.printLayout || !Array.isArray(s.printLayout.frames)) s.printLayout = { paper:'a4-l', mode:'clean', frames: [] };
  if(typeof s.printLayout.paper !== 'string') s.printLayout.paper = 'a4-l';
  if(s.printLayout.mode !== 'clean' && s.printLayout.mode !== 'screen') s.printLayout.mode = 'clean';
  // Every content type defaults to ON; missing keys read as included downstream.
  s.schemaVersion = SCHEMA_VERSION;
  return s;
}

function snap(v){ return (state && state.snapToGrid) ? Math.round(v / 20) * 20 : v; }

function createProjectFromLegacyLoop(){
  let raw;
  try{ raw = localStorage.getItem(KEY_LEGACY); }catch(e){ return null; }
  if(!raw) return null;
  let s;
  try{ s = JSON.parse(raw); }catch(e){ return null; }
  if(!s || !Array.isArray(s.nodes)) return null;
  const id = genProjectId();
  const project = normalizeState(s, 'Loop');
  project.name = 'Loop';
  project.context = "LOOP is a 60-90s film for Lubs, a Brazilian intimate-wellness brand. One couple, one warm sunlit afternoon bedroom, filmed in a single unbroken camera move (motion-control arm plus probe lens) that circles the room. Tone: delicate, sensorial, romantic, suggestive but never explicit; the couple never speaks. Products appear naturally, never as product shots.";
  saveProjectState(id, project);
  const idx = loadProjectsIndex();
  idx.push({ id, name: project.name, createdAt: nowMs(), lastEditedAt: nowMs(), beatCount: project.nodes.length, theme: project.theme });
  saveProjectsIndex(idx);
  setCurrentProjectId(id);
  return id;
}

function loadCurrentState(){
  let id = getCurrentProjectId();
  if(id){
    const s = loadProjectState(id);
    if(s) return normalizeState(s, 'Untitled project');
    setCurrentProjectId(null);
    id = null;
  }
  const idx = loadProjectsIndex();
  if(idx.length === 0){
    const newId = createProjectFromLegacyLoop();
    if(newId) return normalizeState(loadProjectState(newId), 'Untitled project');
    return null;
  }
  const recent = idx.slice().sort((a,b)=>(b.lastEditedAt||0)-(a.lastEditedAt||0))[0];
  if(recent){ setCurrentProjectId(recent.id); return normalizeState(loadProjectState(recent.id), 'Untitled project'); }
  return null;
}

// Under Tauri, projects live on disk — never auto-load at boot. The Projects
// modal is always the launch surface; the user picks which project to open.
let state = HAS_TAURI ? null : loadCurrentState();
let currentProjectId = HAS_TAURI ? null : getCurrentProjectId();

// ============================================================
// Phase I — Onboarding
// #130 First-launch walkthrough — 5 spotlit tooltips on real controls.
// #131 Sample project — "The Last Roll", a small but complete story.
// ============================================================

const ONBOARDING_KEY = 'bts:onboardingDone';
function _onboardingDone(){
  try { return !!localStorage.getItem(ONBOARDING_KEY); } catch(e){ return false; }
}
function _markOnboardingDone(){
  try { localStorage.setItem(ONBOARDING_KEY, '1'); } catch(e){}
}

