window.addEventListener('pagehide', _saveFlush);
window.addEventListener('beforeunload', _saveFlush);
document.addEventListener('visibilitychange', () => { if(document.hidden) _saveFlush(); });
function byId(id){ return state.nodes.find(n=>n.id===id); }

const LOD_ZOOM = 0.5; // below this, drop invisible per-card detail to keep pan smooth
let _lastLod = null;

// Popovers opened from a card are appended to <body>, so panning or zooming
// slides the card out from under them and leaves the panel stranded mid-screen.
// Anything registered here is re-placed against its anchor on every transform,
// and closes itself once the anchor leaves the DOM (deleted card, re-render).
// Held in a hoisted function's own state rather than a top-level const because
// applyTransform runs during boot, before a const declared here would exist.
function _anchoredPops(){ return _anchoredPops._set || (_anchoredPops._set = new Set()); }
