  const hasContent = !!(state && (
    (state.nodes && state.nodes.length) || (state.groups && state.groups.length) ||
    (state.images && state.images.length) || (state.links && state.links.length) ||
    (state.documents && state.documents.length) || (state.videoEmbeds && state.videoEmbeds.length)));
