  // floor and redistribute what is left among the rest
  let widths = val.map(v => v / total * usable);
  const locked = widths.map(w => w < minPx);
  const lockedPx = locked.filter(Boolean).length * minPx;
  const freeTotal = val.reduce((a, v, i) => a + (locked[i] ? 0 : v), 0);
  const freePx = usable - lockedPx;
  if(freeTotal > 0 && freePx > 0) widths = widths.map((w, i) => locked[i] ? minPx : val[i] / freeTotal * freePx);
  else widths = widths.map(() => usable / beats.length);
