    ctx.fillStyle = faint; ctx.font = '10px "IBM Plex Mono", ui-monospace, monospace';
    ctx.textAlign = 'center'; ctx.globalAlpha = 0.8;
    ctx.fillText('No beats yet', W / 2, 35);
