// groups use the vertical midpoint of their right edge (out) or left edge
// (in), so the line visually exits/enters the group's border.
function endpointEntity(id, idx){
  if(idx) return idx.get(id) || null;
  const n = (state && state.nodes || []).find(x => x.id === id);
  if(n) return { kind:'node', obj:n };
  const g = (state && state.groups || []).find(x => x.id === id);
  if(g) return { kind:'group', obj:g };
  return null;
}
// #5 — true when an endpoint is a Character / Location / Prop node. Those
// connections are references ("involves"), not story-flow.
// Contextual role presets — a role is a free, editable label decoupled from the
// technical node/group type. It drives export treatment + suggested layout.
const ROLE_PRESETS = ['cover','slide','section','scene','sequence','step','timeline','reference','mood','character','location','prop','act','episode','theme','concept','note','caption','freeform'];
// Round 55: a scene's NAME resolves LIVE from its canvas group — rename the
