// Clamp any typed/loose width or height into the sane band (the Custom body and
// the MCP can both supply anything; 1e308 draws a flat 180 cone).
function _spClampW(w){ return Math.min(SP_SENSOR_MAX, Math.max(SP_SENSOR_MIN, +w)); }
function _spClampH(h){ return Math.min(90, Math.max(SP_SENSOR_MIN, +h)); }

// Look up a body+format. Returns { bodyId, bodyLabel, formatId, formatLabel, w, h }
// or null. Matching by id keeps the picker and the stored cam in step.
function spCamLookup(bodyId, formatId){
  const b = SP_CAMERAS.find(c => c.id === bodyId); if(!b) return null;
  const f = (b.formats || []).find(r => r[0] === formatId) || b.formats[0]; if(!f) return null;
  return { bodyId:b.id, bodyLabel:b.label, formatId:f[0], formatLabel:f[1], w:f[2], h:f[3] };
}

// The FOV angles (degrees) and desqueezed aspect for an active area + lens.
// Vertical and aspect are null when the active height is unknown (a bare legacy
// camera inheriting only a plan width). Horizontal is always defined.
function spFovAngles(w, h, squeeze, focal){
  const f = Math.max(8, +focal || 35);
  const sq = (+squeeze > 0 ? +squeeze : 1);
  const hA = 2 * Math.atan((w * sq) / (2 * f)) * 180 / Math.PI;
  const vA = (h > 0) ? 2 * Math.atan(h / (2 * f)) * 180 / Math.PI : null;
  const asp = (h > 0) ? (w * sq) / h : null;
  return { h: hA, v: vA, aspect: asp };
}
// </camera-model>

// <camera-wiring>
// The active recording area for a camera element, in mm. An explicit `cam`
// (body+format+squeeze the user picked) wins; a bare/legacy camera inherits the
// plan's sensorW as its width with squeeze 1 and no known height, which is exactly
// the pre-2.0.9 geometry, so no drawn plan changes shape on upgrade.
function spCamActive(el, plan){
  const c = el && el.cam;
  if(c && typeof c.w === 'number' && c.w > 0){
    return { w:_spClampW(c.w), h:(typeof c.h === 'number' && c.h > 0) ? _spClampH(c.h) : null,
             squeeze: Math.min(SP_SQUEEZE_MAX, Math.max(1, +c.squeeze || 1)), body:c.body || null, format:c.format || null, explicit:true };
  }
  return { w: spSensorW(plan), h:null, squeeze:1, body:null, format:null, explicit:false };
}
// The width the horizontal cone is actually cut from: active width times squeeze.
function spCamActiveW(el, plan){ const a = spCamActive(el, plan); return a.w * a.squeeze; }
// Full FOV readout for a camera element (uses its lens + its active area).
function spCamFov(el, plan){ const a = spCamActive(el, plan); return spFovAngles(a.w, a.h, a.squeeze, el.focal || 35); }
// A camera's format, named for the stamp / label / export. A bare camera reports
// the inherited plan sensor so the plan still names itself on a one-camera plan.
function spCamName(el, plan){
  const a = spCamActive(el, plan);
  if(a.explicit){
    let s = (a.body || 'Custom');
    if(a.format) s += ' · ' + a.format;
    else s += ' · ' + (+a.w.toFixed(2)) + 'mm';   // a Custom body names itself by its width
    if(a.squeeze > 1) s += ' · ' + a.squeeze + '×';
    return s;
  }
  const w = spSensorW(plan);
  return spSensorLabel(w) + ' · ' + (+w.toFixed(2)) + 'mm';
}
// Seed a new camera's cam from the plan default (the inherited sensorW), so a
// camera dropped in 2.0.9 carries its own format instead of a bare width. Matches
// the plan width to a known format where one exists, else a Custom of that width.
// The pre-2.0.9 plan-sensor presets, each mapped to the GENERIC body that carries
// that exact width — so a legacy "Super 35" plan (24.89) seeds the Super 35 body,
// not the Alexa 35 4K crop that happens to share 24.89mm. Order/labels mirror the
// old SP_SENSORS list.
const _SP_SEED_MAP = [[24.89,'s35','s35_3p'],[36,'ff','ff'],[27.99,'alexa35','og46'],[36.7,'alexalf','lfog'],[17.3,'mft','mft'],[12.52,'s16','s16']];
function spCamSeed(plan){
  const w = spSensorW(plan);
  for(const [mm, bid, fid] of _SP_SEED_MAP){
    if(Math.abs(mm - w) < 0.02){ const lk = spCamLookup(bid, fid); if(lk) return { body:lk.bodyLabel, bodyId:bid, format:lk.formatLabel, formatId:fid, w:lk.w, h:lk.h, squeeze:1 }; }
  }
  // Any other exact width match in the table, else a Custom of that width.
  for(const b of SP_CAMERAS){ for(const f of b.formats){ if(Math.abs(f[2] - w) < 0.02){ return { body:b.label, bodyId:b.id, format:f[1], formatId:f[0], w:f[2], h:f[3], squeeze:1 }; } } }
  return { body:'Custom', bodyId:'custom', format:null, formatId:null, w:_spClampW(w), h:null, squeeze:1 };
}
