    ' C' + f(bx + L * 0.62) + ' ' + f(-mx) + ' ' + f(bx + L) + ' ' + f(-mx * 0.70) + ' ' + f(bx + L) + ' 0' +
    ' C' + f(bx + L) + ' ' + f(mx * 0.70) + ' ' + f(bx + L * 0.62) + ' ' + f(mx) + ' ' + f(bx + L * 0.32) + ' ' + f(mx) +
    ' C' + f(bx + L * 0.20) + ' ' + f(mx) + ' ' + f(bx + L * 0.10) + ' ' + f(mx) + ' ' + f(bx) + ' ' + f(back) + ' Z';
