function openCheatSheet(){
  let el = document.getElementById('cheatSheet');
  if(!el){
    el = document.createElement('div');
    el.id = 'cheatSheet'; el.hidden = true;
    let html = '<div class="cheat-backdrop"></div><div class="cheat-card">'
      + '<button class="cheat-close" title="Close (Esc)">✕</button>'
      + '<h2>Keyboard shortcuts</h2><div class="cheat-grid">';
    SHORTCUTS.forEach(g => {
      html += '<div class="cheat-group"><h3>' + g.group + '</h3><dl>';
      g.items.forEach(([k, v]) => {
        html += '<dt>' + k.replace(/⌘/g, '<kbd>⌘</kbd>').replace(/Ctrl/g, '<kbd>Ctrl</kbd>').replace(/Shift/g, '<kbd>Shift</kbd>') + '</dt><dd>' + v + '</dd>';
      });
      html += '</dl></div>';
    });
    html += '</div></div>';
    el.innerHTML = html;
    document.body.appendChild(el);
    el.querySelector('.cheat-backdrop').addEventListener('click', closeCheatSheet);
    el.querySelector('.cheat-close').addEventListener('click', closeCheatSheet);
  }
  el.hidden = false;
}
function closeCheatSheet(){
  const el = document.getElementById('cheatSheet');
  if(el) el.hidden = true;
}
function toggleCheatSheet(){
  const el = document.getElementById('cheatSheet');
  if(el && !el.hidden) closeCheatSheet();
  else openCheatSheet();
}
document.addEventListener('keydown', ev => {
  if(ev.key === '?' && !ev.target.matches('input, textarea, [contenteditable]')){
    ev.preventDefault();
    toggleCheatSheet();
    return;
  }
  // I toggles the inspector — the panel is opt-in (Joao, beta 3 round 2).
  if((ev.key === 'i' || ev.key === 'I') && !ev.metaKey && !ev.ctrlKey && !ev.altKey
     && !ev.target.matches('input, textarea, [contenteditable]')
     && typeof toggleInspector === 'function' && state){
    ev.preventDefault();
    toggleInspector();
    return;
  }
  if(ev.key === 'Escape'){
    const el = document.getElementById('cheatSheet');
    if(el && !el.hidden) closeCheatSheet();
  }
}, true);
const _helpBtn = document.getElementById('helpBtn');
if(_helpBtn) _helpBtn.addEventListener('click', toggleCheatSheet);

// ---------- Lightbox (image viewer with prev/next) ----------
let lightboxImages = null;
let lightboxIdx = 0;
// W1.5 — the node whose images are being viewed (null for board images /
// shot refs); owning-node lightboxes get the per-image caption field.
let lightboxNode = null;
// Sidecar info for lightboxes with no owning node (board images): { name }.
let lightboxMeta = null;

function openLightbox(images, startIdx, ownerNode, meta){
  if(!Array.isArray(images) || !images.length) return;
  lightboxImages = images.slice();
  lightboxIdx = Math.max(0, Math.min(startIdx || 0, images.length - 1));
  lightboxNode = ownerNode || null;
  lightboxMeta = meta || null;
  renderLightbox();
  // W4.4 — first-open coach for captions + the Edit / Palette actions. Only
  // when the image belongs to a card (board images have no caption field).
  if(lightboxNode && !IS_VIEWER && !toolWalkthroughSeen('lightbox')) setTimeout(runLightboxTour, 450);
}
// First-open coach for the lightbox (W4.4) — captions and the action row.
// Fires from openLightbox when an owning card is present; replayable from the
// "Show me around" hub (which opens a lightbox on the first card with images).
function runLightboxTour(){
  const el = document.getElementById('lightbox');
  if(!el || el.hidden || !lightboxNode) return;
  if(document.querySelector('.onboard-card')) return;
  document.querySelectorAll('.sp-coach, .sp-coach-spot').forEach(n => n.remove());
  runToolWalkthrough('lightbox', el, [
    { sel: '.lightbox-caption', place: 'above', title: 'Caption this photo',
      body: 'Type here and the caption prints under this exact photo in your exports. Every image keeps its own.' },
    { sel: '.lightbox-actions', place: 'above', title: 'Edit or extract',
      body: 'Edit image opens the crop-and-annotate editor without leaving the lightbox. Palette reads this photo\'s colours into a palette card placed beside its owner.' }
  ], null, document.body);
}
function closeLightbox(){
  lightboxImages = null;
  lightboxNode = null;
  lightboxMeta = null;
  const el = document.getElementById('lightbox');
  if(el) el.hidden = true;
}
function lightboxNav(delta){
  if(!lightboxImages || !lightboxImages.length) return;
  lightboxIdx = (lightboxIdx + delta + lightboxImages.length) % lightboxImages.length;
  renderLightbox();
}
function renderLightbox(){
  let el = document.getElementById('lightbox');
  if(!el){
    el = document.createElement('div');
    el.id = 'lightbox'; el.hidden = true;
    el.innerHTML = '<div class="lightbox-backdrop"></div>'
      + '<button class="lightbox-prev" title="Previous (←)">‹</button>'
      + '<button class="lightbox-next" title="Next (→)">›</button>'
      + '<div class="lightbox-stage"><img alt=""/><input class="lightbox-caption" type="text" placeholder="Caption (prints under this photo in exports)"/><div class="lightbox-actions"><button class="lightbox-edit" title="Edit image">Edit image</button><button class="lightbox-palette" title="Make a palette node from this image">Palette</button></div></div>'
      + '<button class="lightbox-close" title="Close (Esc)">✕</button>'
      + '<div class="lightbox-counter"></div>';
    document.body.appendChild(el);
    el.querySelector('.lightbox-backdrop').addEventListener('click', closeLightbox);
    el.querySelector('.lightbox-close').addEventListener('click', closeLightbox);
    // W1.5 — per-image caption. Saves on input WITHOUT re-render (text-edit
    // rule); blank/whitespace deletes the key so empties are never stored.
    el.querySelector('.lightbox-caption').addEventListener('input', ev => {
      if(!lightboxNode || !lightboxImages) return;
      const ref = lightboxImages[lightboxIdx];
      const v = ev.target.value;
      if(v.trim()){
        if(!lightboxNode.imageCaptions) lightboxNode.imageCaptions = {};
        lightboxNode.imageCaptions[ref] = v;
      } else if(lightboxNode.imageCaptions){
        delete lightboxNode.imageCaptions[ref];
      }
      save();
    });
    el.querySelector('.lightbox-edit').addEventListener('click', ev => {
      ev.stopPropagation();
      if(!lightboxImages || IS_VIEWER) return;
      const oldRef = lightboxImages[lightboxIdx];
      openImageEditor(oldRef, async (newRef) => {
        replaceAssetRef(oldRef, newRef);
        lightboxImages[lightboxIdx] = newRef;
        save(); render(); renderLightbox();
      });
    });
    // W1.6 — palette from the viewed image. Places beside the owning node
    // when there is one (its title becomes the palette title), else view
    // center. Closes the lightbox so the new node is visible.
    el.querySelector('.lightbox-palette').addEventListener('click', ev => {
      ev.stopPropagation();
      if(!lightboxImages || IS_VIEWER) return;
      const ref = lightboxImages[lightboxIdx];
      const owner = lightboxNode;
      closeLightbox();
      paletteFromRef(ref, owner ? (owner.title || '') : '', owner);
    });
    el.querySelector('.lightbox-prev').addEventListener('click', ev => { ev.stopPropagation(); lightboxNav(-1); });
    el.querySelector('.lightbox-next').addEventListener('click', ev => { ev.stopPropagation(); lightboxNav(1); });
    el.querySelector('.lightbox-stage').addEventListener('click', ev => ev.stopPropagation());
  }
  el.hidden = false;
  el.querySelector('img').src = storage.assetSrc(lightboxImages[lightboxIdx]);
  el.querySelector('.lightbox-counter').textContent = (lightboxIdx + 1) + ' / ' + lightboxImages.length;
  const single = lightboxImages.length <= 1;
  el.querySelector('.lightbox-prev').hidden = single;
  el.querySelector('.lightbox-next').hidden = single;
  const editBtn = el.querySelector('.lightbox-edit');
  if(editBtn) editBtn.hidden = !!IS_VIEWER;
  const palBtn = el.querySelector('.lightbox-palette');
  if(palBtn) palBtn.hidden = !!IS_VIEWER;
  // W1.5 — caption field: hidden entirely without an owning node (board
  // images, shot refs) or in read-only viewer mode; value follows prev/next.
  const capIn = el.querySelector('.lightbox-caption');
  capIn.hidden = !lightboxNode || !!IS_VIEWER;
  capIn.value = (lightboxNode && lightboxNode.imageCaptions && lightboxNode.imageCaptions[lightboxImages[lightboxIdx]]) || '';
  // The photo's own filename, kept at import (Chris Walton) — a quiet line
  // under the stage. Board images pass their name via lightboxMeta.
  {
    let meta = el.querySelector('.lightbox-meta');
    if(!meta){
      meta = document.createElement('div');
      meta.className = 'lightbox-meta';
      const stage = el.querySelector('.lightbox-stage') || el;
      stage.appendChild(meta);
    }
    const ref = lightboxImages[lightboxIdx];
    const nm = (lightboxNode && lightboxNode.imageNames && lightboxNode.imageNames[ref]) ||
      (lightboxMeta && lightboxMeta.name) || '';
    meta.textContent = nm;
    meta.hidden = !nm;
  }
}
document.addEventListener('keydown', ev => {
  const el = document.getElementById('lightbox');
  if(!el || el.hidden) return;
  if(document.querySelector('.ie-overlay')) return; // editor open — it owns keys
  // W1.5 — typing in the caption field: arrows edit text; Esc blurs first.
  if(ev.target && ev.target.classList && ev.target.classList.contains('lightbox-caption')){
    if(ev.key === 'Escape'){ ev.target.blur(); ev.stopPropagation(); }
    return;
  }
  if(ev.key === 'Escape'){ closeLightbox(); ev.stopPropagation(); }
  else if(ev.key === 'ArrowLeft'){ lightboxNav(-1); ev.stopPropagation(); }
  else if(ev.key === 'ArrowRight'){ lightboxNav(1); ev.stopPropagation(); }
}, true);

// ── Image editor (#1) ─────────────────────────────────────────────────────────
// Click-to-expand → Edit: crop (film ratios), rotate/flip, draw (pen / line /
// arrow / rectangle / ellipse) and text. Drawings and text are RETAINED
// annotation objects (`anns`) composited over the base canvas each repaint, so
// the Select tool can grab, move, re-edit (text) or delete them. Crop is a
// RETAINED rect too (nothing is baked) — re-activating the tool shows the full
// base and the rect can be widened back out. Rotate / flip bake crop + anns
// into the base first. Undo/redo restores { base, anns, crop } triples. Saving
// flattens the cropped region + anns into a NEW asset and swaps the reference
// everywhere it was used (replaceAssetRef), so the original file stays.
// Un-baked saves ALSO write a `<newStem>.edits.json` sidecar
// ({ v: 2, source, anns, crop }) so reopening the editor restores editable
// annotations + the re-adjustable crop over the original base — see
// openImageEditor / the ie-save handler. v1 sidecars ({ v: 1 }, no crop) load too.
const IE_RATIOS = [['Free',null],['2.39:1',2.39],['1.85:1',1.85],['16:9',16/9],['2:1',2],['4:3',4/3],['1:1',1],['9:16',9/16]];
function replaceAssetRef(oldRef, newRef){
  if(!state || !oldRef || !newRef || oldRef === newRef) return;
  const sub = v => (v === oldRef ? newRef : v);
  (state.nodes||[]).forEach(n => {
    if(Array.isArray(n.images)) n.images = n.images.map(sub);
    if(Array.isArray(n.exportImages)) n.exportImages = n.exportImages.map(sub);
    if(n.imageCaptions && n.imageCaptions[oldRef] !== undefined){
      n.imageCaptions[newRef] = n.imageCaptions[oldRef];
      delete n.imageCaptions[oldRef];
    }
    if(n.imageNames && n.imageNames[oldRef] !== undefined){
      n.imageNames[newRef] = n.imageNames[oldRef];
      delete n.imageNames[oldRef];
    }
    // The edited copy is the same photograph — it was taken in the same place.
    if(n.imageGeo && n.imageGeo[oldRef] !== undefined){
      n.imageGeo[newRef] = n.imageGeo[oldRef];
      delete n.imageGeo[oldRef];
    }
  });
  (state.images||[]).forEach(im => { if(im && im.src === oldRef) im.src = newRef; });
  (state.mediaShelf||[]).forEach(m => { if(m && m.src === oldRef) m.src = newRef; });
}
function openImageEditor(srcRef, onSave){
  if(!srcRef) return;
  note('Loading image…');
  const openWith = (ref, opts) => {
    const img = new Image(); img.crossOrigin = 'anonymous';
    img.onerror = () => {
      if(opts && opts.anns){ // sidecar source missing — fall back to the flattened asset
        note('Original image for these edits is missing — opening flattened');
        openWith(srcRef, { sourceRef: srcRef });
      } else {
        note('Could not load that image to edit');
      }
    };
    img.onload = () => buildImageEditor(img, onSave, opts);
    img.src = storage.assetSrc(ref);
  };
  const plain = () => openWith(srcRef, { sourceRef: srcRef });
  if(!HAS_TAURI || typeof srcRef !== 'string' || /^(data:|blob:|https?:)/.test(srcRef)){ plain(); return; }
  // Non-destructive reopen: a `<stem>.edits.json` sidecar next to the asset means
  // this image is the flattened result of an earlier annotation session — reopen
  // with the ORIGINAL base + the saved annotations (selectable / movable) instead.
  const stem = srcRef.replace(/^assets[\\/]/, '').replace(/\.[^.]+$/, '');
  fetch(storage.assetSrc(stem + '.edits.json'))
    .then(r => (r.ok ? r.json() : null))
    .then(sc => {
      const ok = sc && typeof sc.source === 'string' && Array.isArray(sc.anns);
      if(ok && sc.v === 1 && sc.anns.length){
        openWith(sc.source, { sourceRef: sc.source, anns: sc.anns });
      } else if(ok && sc.v === 2 && (sc.anns.length || sc.crop)){
        openWith(sc.source, { sourceRef: sc.source, anns: sc.anns, crop: sc.crop || null });
      } else plain();
    })
    .catch(plain);
}
// Hover-revealed "Edit" pill for card image thumbs. Opens the editor directly
// for that image; the save swaps the ref everywhere via replaceAssetRef (same
// path the lightbox edit button uses). Returns null in read-only viewer mode.
function makeThumbEditBtn(src){
  if(IS_VIEWER) return null;
  const b = document.createElement('button');
  b.type = 'button'; b.className = 'thumb-edit'; b.textContent = 'Edit'; b.title = 'Edit image';
  b.draggable = false;
  b.addEventListener('pointerdown', ev => ev.stopPropagation());
  b.addEventListener('click', ev => {
    ev.stopPropagation();
    openImageEditor(src, async (newRef) => { replaceAssetRef(src, newRef); save(); render(); });
  });
  return b;
}
// A photo's caption, shown quietly under the thumb on the card itself — it
// used to live only in the lightbox and the exports, which made captioning
// feel like typing into a void. Returns null when the image has no caption.
function mkThumbCaption(node, ref){
  const cap = node && node.imageCaptions && typeof node.imageCaptions[ref] === 'string'
    ? node.imageCaptions[ref].trim() : '';
  if(!cap) return null;
  const s = document.createElement('span');
  s.className = 'thumb-caption';
  s.textContent = cap;
  s.title = cap;
  return s;
}
// ── Per-image export selection (T1.2, Chris) ─────────────────────────────────
// n.exportImages = array of marked refs (subset of n.images). ABSENT means "no
// explicit selection" — exports keep their default behavior; present-but-empty
// means "no images in exports". Keyed by ref string, never index, so reorder
// can't desync it.
// Marked refs when the user curated this card; null when defaults apply.
// W3.8 — an Export Center run with Photos "All" ignores the curation for that
// run only: null everywhere = each export site's own default set.
function exportImageSel(n){
  if(_exportRun && _exportRun.photos === 'all') return null;
  return Array.isArray(n.exportImages)
    ? (n.images || []).filter(r => n.exportImages.includes(r)) : null;
}
// UI-only (badge display). Export sites must use exportImageSel(): its null means
// "each export site's own default" (first / 3 / 6 / all), NOT first-image.
function _imgMarked(n, ref, ix){
  return Array.isArray(n.exportImages) ? n.exportImages.includes(ref) : ix === 0;
}
function _toggleExportImage(node, ref){
  if(!Array.isArray(node.exportImages)){
    // materialize the default (first image marked), then apply the click
    node.exportImages = (node.images && node.images.length) ? [node.images[0]] : [];
  }
  const k = node.exportImages.indexOf(ref);
  if(k >= 0) node.exportImages.splice(k, 1); else node.exportImages.push(ref);
  save(); render();
}
// Drop a ref's per-image metadata — export mark AND caption (W1.5) — when
// the image leaves the node (✕ remove / move away). Called AFTER the splice:
// if the same ref still exists on the card (legacy duplicate data-URLs), both
// stay — they belong to the surviving copy. The single lifecycle spot.
function _pruneImageRefMeta(node, ref){
  if((node.images || []).includes(ref)) return;
  if(Array.isArray(node.exportImages)){
    const k = node.exportImages.indexOf(ref);
    if(k >= 0) node.exportImages.splice(k, 1);
  }
  if(node.imageCaptions) delete node.imageCaptions[ref];
  if(node.imageNames) delete node.imageNames[ref];
  if(node.imageGeo) delete node.imageGeo[ref];
}
// The per-image export choice used to be a hover badge on every card image
// thumb. It crowded the cards (Joao, round 68), so it lives in the Inspector now
// — see the Images section there. _imgMarked / _toggleExportImage are untouched
// and are what the Inspector drives, so no stored data changed shape.
// ── "Location from photo" badge ──────────────────────────────────────────────
// Reading the GPS out of a photo has worked since the scout landed, but it only
// existed as a right-click item and Joao never found it (2026-08-02: "it's
// still not loading from the metadata"). So the affordance now sits ON the
// photo — and ONLY on photos that actually carry a fix, which is what makes it
// readable: if the badge is there, there is a location in that file.
// A stored fix, validated. Malformed entries are normalizeState's job, but a
// card that hasn't been through it yet (a fresh add this session) can still
// hold whatever readPhotoExif handed back, so never trust the shape blind.
function _photoFixOf(g){
  if(!g || typeof g !== 'object' || Array.isArray(g)) return null;
  if(typeof g.lat !== 'number' || !isFinite(g.lat)) return null;
  if(typeof g.lon !== 'number' || !isFinite(g.lon)) return null;
  return g;
}
function imageGeoFix(node, ref){
  return _photoFixOf(node && node.imageGeo ? node.imageGeo[ref] : null);
}
// The Location card's own pin, at badge scale — both badges wear it.
const GEO_BADGE_SVG = '<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-6-5.3-6-10a6 6 0 0 1 12 0c0 4.7-6 10-6 10Z"/><circle cx="12" cy="11" r="2"/></svg>';
function _mkGeoBadge(fix, onUse){
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'thumb-geo';
  b.title = 'Taken at ' + fix.lat.toFixed(5) + ', ' + fix.lon.toFixed(5);
  b.innerHTML = GEO_BADGE_SVG;
  b.draggable = false;
  b.addEventListener('pointerdown', ev => ev.stopPropagation());
  b.addEventListener('click', ev => { ev.preventDefault(); ev.stopPropagation(); onUse(); });
  return b;
}
// On a card's image thumb. Null — no badge at all — when that photo had no fix.
function makeThumbGeoBtn(node, ref){
  if(IS_VIEWER) return null;
  const fix = imageGeoFix(node, ref);
  if(!fix) return null;
  return _mkGeoBadge(fix, () => useThumbPhotoGeo(node, ref));
}
// On a free-floating board image. Same click as the right-click item, which
// stays where it is — the badge is a second door, not a replacement.
function makeBoardGeoBtn(im){
  if(IS_VIEWER) return null;
  const fix = _photoFixOf(im && im.geo);
  if(!fix) return null;
  return _mkGeoBadge(fix, () => boardImageToLocation(im));
}
