// Picker for board documents — file input that accepts a wide doc-friendly list
function pickBoardDocuments(){
  if(!state) return;
  const inp = document.createElement('input');
  inp.type = 'file';
  // Plain extension list only — the previous MIME wildcard
  // (application/vnd.openxmlformats-officedocument.*) isn't valid in
  // HTML accept syntax and made macOS grey out every file in the picker.
  inp.accept = '.pdf,.docx,.doc,.xlsx,.xls,.xlsm,.pptx,.ppt,.key,.numbers,.pages,.csv,.tsv,.txt,.md,.rtf,.odt,.ods,.odp';
  inp.multiple = true;
  inp.addEventListener('change', () => { if(inp.files && inp.files.length) addBoardDocuments(inp.files); });
  inp.click();
}
