// ── Sections (P3, round 2) — a sidebar tool, not a floating rail ─────────────
// The floating rail collided with the project tabs. Sections now live where
// the other tools live: a button in the left rail that opens a jump list.
function _sectionsList(){
  if(!state) return [];
  const out = [];
  try {
    walkExportOrder(state, { includeExportHidden: true }).forEach(it => {
      if(it.kind === 'group-start' && !it.virtual && !it.sequence && it.group && it.group.id){
        out.push({ kind: 'group', id: it.group.id, name: it.group.name || 'Section' });
      } else if(it.kind === 'node' && (it.node.type === 'title')){
        out.push({ kind: 'title', id: it.node.id, name: (it.node.title || '').trim() || 'Title' });
      }
    });
  } catch(e){ /* a mid-edit walk hiccup must never take the list down */ }
  return out;
}
function _sectionsFlyTo(sec){
  if(sec.kind === 'title'){
    const n = (state.nodes || []).find(x => x.id === sec.id);
    if(n) jumpToNode(n);
    return;
  }
  const g = (state.groups || []).find(x => x.id === sec.id);
  if(!g) return;
  const rect = viewport.getBoundingClientRect();
  const z = state.view.zoom || 1;
  state.view.panX = rect.width / 2 - (g.x + (g.w || 400) / 2) * z;
  state.view.panY = rect.height / 2 - (g.y + (g.h || 280) / 2) * z;
  applyTransform(); scheduleCull();
  const el = document.querySelector('.group-box[data-id="' + sec.id + '"]');
  if(el){ el.classList.add('jump-flash'); setTimeout(() => el.classList.remove('jump-flash'), 1200); }
}
{ const _sb = document.getElementById('sectionsBtn');
  if(_sb) _sb.addEventListener('click', ev => { ev.stopPropagation();
    if(document.querySelector('.sections-pop')) _closeSectionsPop(); else openSectionsPop(_sb); }); }
function _closeSectionsPop(){ document.querySelectorAll('.sections-pop').forEach(e => e.remove()); }
function openSectionsPop(anchor){
  _closeSectionsPop();
  const secs = _sectionsList();
  if(!secs.length){ note('No sections yet — Titles and groups become sections'); return; }
  const pop = document.createElement('div'); pop.className = 'sections-pop';
  const head = document.createElement('div'); head.className = 'sections-pop-head'; head.textContent = 'Sections';
  pop.appendChild(head);
  secs.forEach(sec => {
    const b = document.createElement('button');
    b.className = 'sr-item sr-' + sec.kind;
    b.textContent = sec.name;
    b.addEventListener('click', () => { _closeSectionsPop(); _sectionsFlyTo(sec); });
    pop.appendChild(b);
  });
  const r = anchor.getBoundingClientRect();
  pop.style.left = (r.right + 10) + 'px';
  pop.style.top = Math.max(70, r.top - 8) + 'px';
  document.body.appendChild(pop);
  registerEscLayer(pop, () => _closeSectionsPop());
  _clampPop(pop);
  const dismiss = ev => { if(!pop.contains(ev.target) && !(anchor && anchor.contains(ev.target))){ _closeSectionsPop(); document.removeEventListener('pointerdown', dismiss, true); } };
  setTimeout(() => document.addEventListener('pointerdown', dismiss, true), 0);
}
// The button only offers itself when a board actually has sections.
function renderSectionsRail(){
  _renderSectionChip(); // the rail button retired; the canvas chip IS sections now
}
// "You are here" — a quiet breadcrumb beside the zoom badge naming the section
// under the viewport centre; click opens the full jump list (Joao: the rail
// button read as one more line-stack icon and lived far from the canvas).
function _sectionBoundsOf(sec){
  if(sec.kind === 'group'){
    const g = (state.groups || []).find(x => x.id === sec.id);
    return g ? { x: g.x, y: g.y, w: g.w, h: g.h } : null;
  }
  const n = (state.nodes || []).find(x => x.id === sec.id);
  if(!n) return null;
  // A Title stands for the run below-right of it until the next section: give
  // it a generous claim box so panning near it reads as "in" that section.
  return { x: n.x - 80, y: n.y - 60, w: (n.w || NODE_W) + 900, h: 720 };
}
function _renderSectionChip(){
  const chip = document.getElementById('sectionChip');
  if(!chip) return;
  const secs = (state && !IS_VIEWER) ? _sectionsList() : [];
  if(secs.length < 2){ chip.hidden = true; return; }
  const r = viewport.getBoundingClientRect();
  const v = state.view;
  const cx = (r.width / 2 - v.panX) / v.zoom;
  const cy = (r.height / 2 - v.panY) / v.zoom;
  let current = null, bestArea = Infinity;
  secs.forEach(sec => {
    const b = _sectionBoundsOf(sec);
    if(!b) return;
    if(cx >= b.x && cx <= b.x + b.w && cy >= b.y && cy <= b.y + b.h){
      const area = b.w * b.h;
      if(area < bestArea){ bestArea = area; current = sec; }
    }
  });
  chip.hidden = false;
  chip.classList.toggle('section-chip-idle', !current);
  chip.textContent = current ? current.name : 'Sections';
}
let _chipT = 0;
function _scheduleSectionChip(){ clearTimeout(_chipT); _chipT = setTimeout(_renderSectionChip, 120); }
{ const chip = document.getElementById('sectionChip');
  if(chip) chip.addEventListener('click', () => {
    if(document.querySelector('.sections-pop')){ _closeSectionsPop(); return; }
    openSectionsPop(chip);
  }); }
