// Phase L — keyboard shortcut Cmd/Ctrl+0 for Fit View. The native menu's
// accelerator was inconsistent across builds; wire it at the document level.
document.addEventListener('keydown', ev => {
  if((ev.metaKey || ev.ctrlKey) && ev.key === '0'){
    const inEditable = ev.target && (ev.target.tagName === 'INPUT' || ev.target.tagName === 'TEXTAREA' || ev.target.isContentEditable);
    if(inEditable) return;
    ev.preventDefault();
    fitView();
  }
});

