(function wireMoreMenu(){
  const moreBtn = document.getElementById('moreBtn');
  const moreMenu = document.getElementById('moreMenu');
  if(!moreBtn || !moreMenu) return;
  // ⌘ , is the native Beat menu's accelerator, so it only exists in the Mac
  // app — don't promise it in the legacy web build. (? and ⌘ Z are handled in
  // JS and work in both, so those hints stay.)
  if(!HAS_TAURI){ const k = moreMenu.querySelector('#prefsBtn .add-kbd'); if(k) k.remove(); }
  moreBtn.addEventListener('click', (e)=>{
    e.stopPropagation();
    moreMenu.hidden = !moreMenu.hidden;
    if(!moreMenu.hidden) registerEscLayer(moreMenu, () => { moreMenu.hidden = true; moreBtn.setAttribute('aria-expanded', 'false'); });
    moreBtn.setAttribute('aria-expanded', String(!moreMenu.hidden));
    if(!moreMenu.hidden){
      // Refresh the disabled look each open — the stacks move constantly.
      const ub = document.getElementById('undoMenuBtn');
      const rb = document.getElementById('redoMenuBtn');
      if(ub) ub.disabled = undoStack.length < 2;
      if(rb) rb.disabled = redoStack.length === 0;
    }
  });
  // Clicking any item runs its own action (listeners attached by id) and closes the menu.
  moreMenu.querySelectorAll('button').forEach(b => b.addEventListener('click', ()=>{
    moreMenu.hidden = true; moreBtn.setAttribute('aria-expanded', 'false');
  }));
  document.addEventListener('click', (e)=>{
    if(!moreMenu.hidden && !e.target.closest('.bar-right')){
      moreMenu.hidden = true; moreBtn.setAttribute('aria-expanded', 'false');
    }
  });
})();
