function findBestProjectImage(s){
  if(!s) return null;
  for(const n of (s.nodes || [])){
    if(n.images && n.images.length) return n.images[0];
  }
  for(const im of (s.images || [])){
    if(im.src) return im.src;
  }
  return null;
}

// Regenerate thumb.jpg from the first image in the project (Tauri only).
// findBestProjectImage may return either a filename (Tauri) or a data URL (paste).
// We load it via storage.assetSrc, draw 480x300 cover-fit, JPEG q=0.82, then
// write via storage.writeThumbnail.
async function regenerateProjectThumb(){
  if(!HAS_TAURI || !currentProjectId || !state) return;
  try {
    const src = findBestProjectImage(state);
    if(!src) return;
    if(/^data:/.test(src)){
      // Already a data URL — write directly (still resize to 480x300 cover-fit for consistency)
      const img = new Image();
      await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = src; });
      const targetW = 480, targetH = 300;
      const canvas = document.createElement('canvas');
      canvas.width = targetW; canvas.height = targetH;
      const ctx = canvas.getContext('2d');
      const r = Math.max(targetW / img.width, targetH / img.height);
      const w = img.width * r, h = img.height * r;
      ctx.drawImage(img, (targetW - w) / 2, (targetH - h) / 2, w, h);
      await storage.writeThumbnail(currentProjectId, canvas.toDataURL('image/jpeg', 0.82));
      return;
    }
    // Filename — fetch via assetSrc, draw onto canvas, encode
    const url = storage.assetSrc(src);
    if(!url) return;
    const img = new Image();
    img.crossOrigin = 'anonymous';
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = url; });
    const targetW = 480, targetH = 300;
    const canvas = document.createElement('canvas');
    canvas.width = targetW; canvas.height = targetH;
    const ctx = canvas.getContext('2d');
    const r = Math.max(targetW / img.width, targetH / img.height);
    const w = img.width * r, h = img.height * r;
    ctx.drawImage(img, (targetW - w) / 2, (targetH - h) / 2, w, h);
    await storage.writeThumbnail(currentProjectId, canvas.toDataURL('image/jpeg', 0.82));
  } catch(err){
    console.error('regenerateProjectThumb', err);
  }
}

function saveProjectExplicit(){
  // Explicit save also regenerates thumb.jpg — block the whole thing while
  // previewing a version (nothing on screen may reach disk).
  if(_histPreviewing){ note('Previewing a version — nothing is saved (Restore or Back to current first)'); return; }
  if(!state || !currentProjectId) return;
  const pulse = document.getElementById('savedPulse');
  pulse.hidden = false;
  pulse.textContent = 'Saved';
  pulse.classList.remove('sp-flash'); void pulse.offsetWidth; pulse.classList.add('sp-flash');
  setTimeout(() => { pulse.classList.remove('sp-flash'); pulse.textContent = 'Saved · just now'; }, 950);
  save();
  if(HAS_TAURI){
    regenerateProjectThumb();
  } else {
    // Refresh the thumbnail from the first image we can find in the project.
    const thumb = findBestProjectImage(state);
    const idx = loadProjectsIndex();
    const i = idx.findIndex(p => p.id === currentProjectId);
    if(i >= 0){
      if(thumb) idx[i].thumb = thumb;
      else delete idx[i].thumb;
      saveProjectsIndex(idx);
    }
  }
  setTimeout(()=>{ pulse.hidden = true; }, 900);
}

document.getElementById('saveProjectBtn').addEventListener('click', saveProjectExplicit);
document.addEventListener('keydown', ev => {
  if((ev.metaKey || ev.ctrlKey) && (ev.key === 'f' || ev.key === 'F')){
    if(!state) return;
    const inEditable = ev.target && (ev.target.tagName === 'INPUT' || ev.target.tagName === 'TEXTAREA' || ev.target.isContentEditable);
    if(inEditable && ev.target !== searchInp) return;
    ev.preventDefault();
    searchInp.focus();
    searchInp.select();
    return;
  }
  if((ev.metaKey || ev.ctrlKey) && (ev.key === 's' || ev.key === 'S')){
    if(!state) return;
    // Deliberately NOT typing-gated: Cmd-S saves from anywhere, inputs included.
    ev.preventDefault();
    saveProjectExplicit();
  }
});

let searchMatches = [];
let searchCurrentIdx = -1;
const searchInp = document.getElementById('searchInp');
const searchMeta = document.getElementById('searchMeta');

function performSearch(){
  const q = (searchInp.value || '').trim().toLowerCase();
  searchMatches = [];
  if(!q || !state){ updateSearchHighlight(); return; }
  (state.nodes || []).forEach(n => {
    const hay = ((n.title || '') + ' ' + (n.body || '') + ' ' + (n.product || '') + ' ' + (n.shotType || '')).toLowerCase();
    if(hay.indexOf(q) !== -1) searchMatches.push(n.id);
  });
  (state.links || []).forEach(l => {
    const hay = ((l.title || '') + ' ' + (l.url || '')).toLowerCase();
    if(hay.indexOf(q) !== -1) searchMatches.push(l.id);
  });
  (state.videoEmbeds || []).forEach(e => {
    const hay = ((e.title || '') + ' ' + (e.url || '') + ' ' + (e.platform || '')).toLowerCase();
    if(hay.indexOf(q) !== -1) searchMatches.push(e.id);
  });
  (state.documents || []).forEach(d => {
    const hay = ((d.filename || '') + ' ' + (d.mimeType || '')).toLowerCase();
    if(hay.indexOf(q) !== -1) searchMatches.push(d.id);
  });
  searchCurrentIdx = searchMatches.length ? 0 : -1;
  updateSearchHighlight();
  if(searchMatches.length) jumpToMatch();
}
function updateSearchHighlight(){
  // Clear previous state across all kinds
  document.querySelectorAll('.node, .link-card, .video-embed-card, .bimg, .doc-card')
    .forEach(el => el.classList.remove('match', 'match-current', 'search-hit', 'search-dim'));
  if(!searchInp.value){ searchMeta.textContent = ''; return; }
  if(!searchMatches.length){ searchMeta.textContent = 'No matches'; return; }
  const hitIds = new Set(searchMatches);
  // Dim non-matches; highlight matches
  document.querySelectorAll('.node, .link-card, .video-embed-card, .bimg, .doc-card')
    .forEach(el => {
      const id = el.dataset && el.dataset.id;
      if(!id) return;
      if(hitIds.has(id)){
        el.classList.add('search-hit');
        if(el.classList.contains('node')) el.classList.add('match');
      } else {
        el.classList.add('search-dim');
      }
    });
  // Track current pick for nav arrows
  const currentId = searchMatches[searchCurrentIdx];
  if(currentId){
    const cur = document.querySelector('[data-id="' + currentId + '"]');
    if(cur && cur.classList.contains('node')) cur.classList.add('match-current');
  }
  searchMeta.textContent = (searchCurrentIdx+1) + ' / ' + searchMatches.length;
}
function jumpToMatch(){
  if(searchCurrentIdx < 0 || searchCurrentIdx >= searchMatches.length) return;
  const id = searchMatches[searchCurrentIdx];
  // Search across all kinds of canvas-positioned items.
  const hit = (state.nodes || []).find(x => x.id === id)
           || (state.links || []).find(x => x.id === id)
           || (state.videoEmbeds || []).find(x => x.id === id)
           || (state.images || []).find(x => x.id === id)
           || (state.documents || []).find(x => x.id === id);
  if(!hit) return;
  const r = viewport.getBoundingClientRect();
  const w = (typeof hit.w === 'number' && hit.w) ? hit.w : NODE_W;
  const targetWorldX = hit.x + w / 2;
  const targetWorldY = hit.y + 120;
  const v = state.view;
  v.panX = r.width/2 - targetWorldX * v.zoom;
  v.panY = r.height/2 - targetWorldY * v.zoom;
  applyTransform();
  // Re-render at the new view so a previously-culled match is in the DOM
  // before updateSearchHighlight() tries to mark it. (#audit)
  renderNodes(); renderEdges();
  if(typeof updateSearchHighlight === 'function') updateSearchHighlight();
  // Landing affordance — the same brief glow jumpToNode uses, on whatever
  // kind of element the match resolved to (node, link, embed, image, doc).
  const el = document.querySelector(
    '.node[data-id="' + id + '"], .link-card[data-id="' + id + '"], ' +
    '.video-embed-card[data-id="' + id + '"], .bimg[data-id="' + id + '"], ' +
    '.doc-card[data-id="' + id + '"]');
  if(el){
    el.classList.add('jump-flash');
    setTimeout(() => el.classList.remove('jump-flash'), 1200);
  }
}

searchInp.addEventListener('input', performSearch);
searchInp.addEventListener('keydown', ev => {
  if(!searchMatches.length){
    if(ev.key === 'Escape'){ searchInp.value = ''; performSearch(); searchInp.blur(); }
    return;
  }
  if(ev.key === 'ArrowDown' || (ev.key === 'Enter' && !ev.shiftKey)){
    ev.preventDefault();
    searchCurrentIdx = (searchCurrentIdx + 1) % searchMatches.length;
    updateSearchHighlight(); jumpToMatch();
  } else if(ev.key === 'ArrowUp' || (ev.key === 'Enter' && ev.shiftKey)){
    ev.preventDefault();
    searchCurrentIdx = (searchCurrentIdx - 1 + searchMatches.length) % searchMatches.length;
    updateSearchHighlight(); jumpToMatch();
  } else if(ev.key === 'Escape'){
    searchInp.value = ''; performSearch(); searchInp.blur();
  }
});

// ── Command palette (W2.2) ───────────────────────────────────────────────────
// Cmd+K — jump to anything on the board or run a command. Programmatic modal
// following openSnapshotsModal's pattern (fixed backdrop, capture-phase keys,
// double-open guard). In read-only viewer mode only the Jump group appears —
// every registered command mutates state or opens editor chrome.
const _CMDK_KIND_LABEL = { beat:'Beat', title:'Title', note:'Note', thought:'Thought',
  gallery:'Gallery', character:'Character', location:'Location', prop:'Prop',
  palette:'Palette', sketch:'Sketch', shotlist:'Shot list', setplan:'Set Plan' };

function _cmdkSnippet(text){
  const line = (text || '').split('\n').map(s => s.trim()).find(s => s);
  if(!line) return '';
  return line.length > 44 ? line.slice(0, 44) + '…' : line;
}

// Everything jumpable, using performSearch's field model + groups by name.
function _cmdkJumpables(){
  if(!state) return [];
  const out = [];
  (state.nodes || []).forEach(n => out.push({
    id: n.id, kind: _CMDK_KIND_LABEL[n.type || 'beat'] || 'Card',
    label: (n.title || '').trim() || _cmdkSnippet(n.body) || 'Untitled',
    hay: ((n.title || '') + ' ' + (n.body || '') + ' ' + (n.product || '') + ' ' + (n.shotType || '')).toLowerCase()
  }));
  (state.groups || []).forEach(g => out.push({
    id: g.id, kind: 'Group', label: (g.name || '').trim() || 'Group',
    hay: (g.name || '').toLowerCase()
  }));
  (state.links || []).forEach(l => out.push({
    id: l.id, kind: 'Link', label: (l.title || '').trim() || l.url || 'Link',
    hay: ((l.title || '') + ' ' + (l.url || '')).toLowerCase()
  }));
  (state.videoEmbeds || []).forEach(e => out.push({
    // Legacy embeds carry provider/originalUrl instead of platform/url/title —
    // include both eras so every embed stays findable.
    id: e.id, kind: 'Video', label: (e.title || '').trim() || e.platform || e.provider || 'Video',
    hay: ((e.title || '') + ' ' + (e.url || '') + ' ' + (e.platform || '') + ' ' + (e.provider || '') + ' ' + (e.originalUrl || '')).toLowerCase()
  }));
  (state.documents || []).forEach(d => out.push({
    id: d.id, kind: 'Document', label: (d.filename || '').trim() || 'Document',
    hay: ((d.filename || '') + ' ' + (d.mimeType || '')).toLowerCase()
  }));
  return out;
}

// Pan to a picked entity + flash + select — jumpToNode for nodes, the
// jumpToMatch element-resolution idiom for the rest, and the small group
// equivalent (groups aren't culled, so no re-render needed to find the box).
function _cmdkJumpTo(item){
  if(!state || !state.view) return;
  const flash = sel => {
    const el = document.querySelector(sel);
    if(el){ el.classList.add('jump-flash'); setTimeout(() => el.classList.remove('jump-flash'), 1200); }
  };
  const select = id => { if(!IS_VIEWER){ selectedIds = new Set([id]); } };
  const n = (state.nodes || []).find(x => x.id === item.id);
  if(n){ select(n.id); jumpToNode(n); return; } // jumpToNode flashes + applies selection
  const g = (state.groups || []).find(x => x.id === item.id);
  if(g){
    const r = viewport.getBoundingClientRect();
    const z = state.view.zoom || 1;
    // 680×480 = addGroup's real defaults (not renderGroups' legacy 400×280).
    state.view.panX = r.width / 2 - (g.x + (g.w || 680) / 2) * z;
    state.view.panY = r.height / 2 - (g.y + (g.h || 480) / 2) * z;
    applyTransform();
    select(g.id);
    renderNodes(); renderEdges(); applySelectionToDom();
    flash('.group-box[data-id="' + g.id + '"]');
    return;
  }
  const hit = (state.links || []).find(x => x.id === item.id)
           || (state.videoEmbeds || []).find(x => x.id === item.id)
           || (state.documents || []).find(x => x.id === item.id);
  if(!hit) return;
  const r = viewport.getBoundingClientRect();
  const z = state.view.zoom || 1;
  const w = (typeof hit.w === 'number' && hit.w) ? hit.w : 280;
  state.view.panX = r.width / 2 - (hit.x + w / 2) * z;
  state.view.panY = r.height / 2 - (hit.y + 120) * z;
  applyTransform();
  select(hit.id);
  renderNodes(); renderEdges(); applySelectionToDom();
  flash('.link-card[data-id="' + hit.id + '"], .video-embed-card[data-id="' + hit.id + '"], .doc-card[data-id="' + hit.id + '"]');
}

// ── W4.2 — Audio timeline dock ───────────────────────────────────────────────
// A bottom-docked, NON-modal panel (the canvas stays fully usable above it):
// one audio track per project, drawn as a flat peak waveform (accent on
// surface, no gradients). Click seeks, double-click drops a marker, markers
// spawn beats carrying timecodes (beat.tc). Space toggles play ONLY while the
// dock has focus or the pointer hovers it — the global space stays untouched.
// Esc closes only while focus is inside the dock. Torn down fully on close.
let _audio = null; // { el, wavewrap, canvas, markersEl, playheadEl, timeEl, playBtn, nameEl, emptyEl, hintEl, audioEl, peaks, raf, selId, onResize } while open
const _audioPeaksCache = new Map(); // ref → { peaks: Float32Array, max, duration } (per-session)

function toggleAudioDock(){
  if(_audio){ closeAudioDock(); return; }
  openAudioDock();
}
function openAudioDock(opts){
  opts = opts || {};
  if(!state){ note('Open a project first'); return; }
  if(IS_VIEWER){ note('The audio timeline is not available in the viewer'); return; }
  if(_audio){ // already open — just honor a seek request (the tc-badge path)
    if(typeof opts.seek === 'number') _audioSeek(opts.seek);
    return;
  }
  _audioBuildDock();
  document.body.classList.add('audio-dock-open');
  const b = document.getElementById('audioDockBtn'); if(b) b.classList.add('tool-on');
  document.addEventListener('keydown', _audioDockKey, true);
  window.addEventListener('resize', _audio.onResize);
  _audioAttachTrack(typeof opts.seek === 'number' ? opts.seek : undefined);
  try { _audio.el.focus({ preventScroll: true }); } catch(e){}
  if(!toolWalkthroughSeen('audio')) setTimeout(runAudioTour, 450); // no-ops if closed meanwhile
}
// First-open tour of the audio timeline dock (W4.4) — track, markers, beats.
function runAudioTour(){
  if(!_audio) return;
  if(document.querySelector('.onboard-card')) return;
  document.querySelectorAll('.sp-coach, .sp-coach-spot').forEach(n => n.remove());
  runToolWalkthrough('audio', _audio.el, [
    { sel: '.ad-wavewrap', place: 'above', title: 'Your track under the story',
      body: 'Load a song with the button — or just drag an audio file from Finder onto the dock, or anywhere on the canvas. It becomes a waveform: press and drag to scrub, Space plays and pauses while the dock is focused.' },
    { sel: '.ad-wavewrap', place: 'above', title: 'Drop markers',
      body: 'Double-click the waveform to drop a marker at that moment. Drag a flag left or right to move it, double-click the flag to name it.' },
    { sel: '.ad-side', place: 'left', title: 'Markers become beats',
      body: 'Select a marker and press + Beat: a beat carrying that timecode lands on the canvas, chained to the previous marker beat. The chain button beside it points the marker at a beat you already wrote instead — same result, no new card. Replace swaps the mix and keeps every marker; the timecode badge on a beat card jumps the playhead back here.' }
  ], null, document.body);
}
function closeAudioDock(){
  if(!_audio) return;
  _audioStopRaf();
  if(_audio.audioEl){ try { _audio.audioEl.pause(); } catch(e){} _audio.audioEl.removeAttribute('src'); try { _audio.audioEl.load(); } catch(e){} }
  document.removeEventListener('keydown', _audioDockKey, true);
  window.removeEventListener('resize', _audio.onResize);
  _audio.el.remove();
  _audio = null;
  document.body.classList.remove('audio-dock-open');
  const b = document.getElementById('audioDockBtn'); if(b) b.classList.remove('tool-on');
}
// Pause without closing — Present mode calls this so the deck opens in silence.
function _audioPausePlayback(){
  if(!_audio) return;
  if(_audio.audioEl && !_audio.audioEl.paused){ try { _audio.audioEl.pause(); } catch(e){} }
  _audioStopRaf();
  _audioSyncPlayBtn();
}
function _audioStopRaf(){
  if(_audio && _audio.raf){ cancelAnimationFrame(_audio.raf); _audio.raf = null; }
}
function _audioDur(){
  if(state && state.audio && state.audio.duration) return state.audio.duration;
  const a = _audio && _audio.audioEl;
  return (a && isFinite(a.duration) && a.duration > 0) ? a.duration : 0;
}

function _audioBuildDock(){
  const el = document.createElement('div');
  el.className = 'audio-dock'; el.id = 'audioDock';
  el.tabIndex = -1;
  el.setAttribute('role', 'region'); el.setAttribute('aria-label', 'Audio timeline');

  // Left cluster — play/pause + time readout.
  const left = document.createElement('div'); left.className = 'ad-left';
  const playBtn = document.createElement('button');
  playBtn.className = 'ad-play'; playBtn.type = 'button'; playBtn.title = 'Play / pause (Space while the dock is focused)';
  playBtn.addEventListener('click', () => _audioTogglePlay());
  const timeEl = document.createElement('div'); timeEl.className = 'ad-time'; timeEl.textContent = '0:00 / 0:00';
  left.append(playBtn, timeEl);

  // Waveform strip — canvas + playhead + marker flags + empty state.
  const wavewrap = document.createElement('div'); wavewrap.className = 'ad-wavewrap';
  const canvas = document.createElement('canvas'); canvas.className = 'ad-canvas';
  const playheadEl = document.createElement('div'); playheadEl.className = 'ad-playhead'; playheadEl.style.left = '0%';
  const markersEl = document.createElement('div'); markersEl.className = 'ad-markers';
  const hintEl = document.createElement('div'); hintEl.className = 'ad-hint'; hintEl.textContent = 'Click to seek — double-click to drop a marker';
  const emptyEl = document.createElement('div'); emptyEl.className = 'ad-empty'; emptyEl.hidden = true;
  const emptyTx = document.createElement('span'); emptyTx.className = 'ad-empty-tx';
  emptyTx.textContent = 'Play your track under the story — drop markers, then turn them into timecoded beats.';
  const loadBtn = document.createElement('button'); loadBtn.className = 'btn btn-accent'; loadBtn.type = 'button';
  loadBtn.textContent = 'Load audio…';
  loadBtn.addEventListener('click', () => _audioPickFile());
  emptyEl.append(emptyTx, loadBtn);
  wavewrap.append(canvas, playheadEl, markersEl, hintEl, emptyEl);
  // A track dragged from Finder onto the dock loads it — the gesture everyone
  // tries first. (Dropping it on the canvas works too; the viewport drop
  // handler routes audio files here.)
  el.addEventListener('dragover', ev => {
    const items = ev.dataTransfer && ev.dataTransfer.items;
    if(items && Array.prototype.some.call(items, it => it.kind === 'file')){
      ev.preventDefault();
      ev.dataTransfer.dropEffect = 'copy';
      el.classList.add('ad-dropping');
    }
  });
  el.addEventListener('dragleave', () => el.classList.remove('ad-dropping'));
  el.addEventListener('drop', ev => {
    el.classList.remove('ad-dropping');
    const files = ev.dataTransfer && ev.dataTransfer.files;
    if(!files || !files.length) return;
    ev.preventDefault(); ev.stopPropagation();
    const f = Array.prototype.find.call(files, _isAudioFile);
    if(f) _audioLoadFromFile(f);
    else note('Drop an audio file (mp3, m4a, wav…) to load it');
  });
  // Pointer-based scrub: press seeks, and dragging keeps seeking — a click is
  // just the degenerate no-move case. (Marker flags stopPropagation on their
  // own pointerdown, so they never reach this.)
  wavewrap.addEventListener('pointerdown', ev => {
    if(ev.button !== 0) return;
    if(ev.target.closest('.ad-marker') || ev.target.closest('.ad-empty')) return;
    const d = _audioDur(); if(!d) return;
    ev.preventDefault();
    const rect = wavewrap.getBoundingClientRect();
    const seekAt = (clientX) => _audioSeek(Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) * d);
    seekAt(ev.clientX);
    const onMove = e => seekAt(e.clientX);
    const onUp = () => { window.removeEventListener('pointermove', onMove); window.removeEventListener('pointerup', onUp); };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  });
  wavewrap.addEventListener('dblclick', ev => {
    if(ev.target.closest('.ad-marker') || ev.target.closest('.ad-empty')) return;
    if(!state || !state.audio) return;
    const d = _audioDur(); if(!d) return;
    const rect = wavewrap.getBoundingClientRect();
    const t = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width)) * d;
    const mk = { id: 'am' + (uid++), t, label: '', beatId: null };
    state.audio.markers.push(mk);
    _audio.selId = mk.id;
    save();
    _audioRenderMarkers();
    note('Marker at ' + formatDuration(t) + ' — double-click its flag to name it');
  });

  // Right cluster — track name + actions.
  const side = document.createElement('div'); side.className = 'ad-side';
  const eyebrow = document.createElement('div'); eyebrow.className = 'ad-eyebrow'; eyebrow.textContent = 'Audio timeline';
  const nameEl = document.createElement('div'); nameEl.className = 'ad-name'; nameEl.textContent = '';
  const actions = document.createElement('div'); actions.className = 'ad-actions';
  const replaceBtn = document.createElement('button'); replaceBtn.className = 'btn'; replaceBtn.type = 'button';
  replaceBtn.textContent = 'Replace…'; replaceBtn.title = 'Load a different audio file (markers are kept)';
  replaceBtn.addEventListener('click', () => _audioPickFile());
  const removeBtn = document.createElement('button'); removeBtn.className = 'btn'; removeBtn.type = 'button';
  removeBtn.textContent = 'Remove'; removeBtn.title = 'Remove the audio track from this project';
  removeBtn.addEventListener('click', () => _audioRemoveTrack());
  actions.append(replaceBtn, removeBtn);
  side.append(eyebrow, nameEl, actions);

  const closeBtn = document.createElement('button');
  closeBtn.className = 'ad-close'; closeBtn.type = 'button'; closeBtn.textContent = '✕'; closeBtn.title = 'Close (Esc)';
  closeBtn.addEventListener('click', () => closeAudioDock());

  el.append(left, wavewrap, side, closeBtn);
  document.body.appendChild(el);
  _audio = { el, wavewrap, canvas, markersEl, playheadEl, timeEl, playBtn, nameEl, emptyEl, hintEl,
    audioEl: null, peaks: null, raf: null, selId: null,
    attachedRef: null, onResize: () => { _audioDrawWave(); } };
  _audioSyncPlayBtn();
}

// Space/Esc, scoped: space toggles play while the dock has focus OR hover
// (never while typing, never while a modal overlay owns the keyboard); Esc
// closes only while focus is inside the dock. Registered in capture so the
// Esc we consume can't also clear a canvas selection underneath.
function _audioDockKey(ev){
  if(!_audio) return;
  if(ev.key === 'Escape'){
    const ae = document.activeElement;
    if(_audio.el.contains(ae)){
      // An inline editor inside the dock (marker rename) owns its own Esc —
      // let its handler cancel the edit; closing here would tear the input out
      // and its blur would COMMIT the abandoned text.
      if(ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable)) return;
      ev.preventDefault(); ev.stopPropagation(); closeAudioDock();
    }
    return;
  }
  if(ev.key !== ' ' && ev.code !== 'Space') return;
  const t = ev.target;
  if(t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
  if(_cmdkBlocked()) return; // a modal editor / overlay owns the keyboard
  if(!(_audio.el.contains(document.activeElement) || _audio.el.matches(':hover'))) return;
  ev.preventDefault(); ev.stopPropagation();
  _audioTogglePlay();
}

// (Re)wire the <audio> element + waveform for the current state.audio.ref.
// Peaks decode asynchronously; the timeline is usable off metadata meanwhile.
async function _audioAttachTrack(seekTo){
  if(!_audio) return;
  _audioStopRaf();
  if(_audio.audioEl){ try { _audio.audioEl.pause(); } catch(e){} _audio.audioEl.removeAttribute('src'); try { _audio.audioEl.load(); } catch(e){} }
  _audio.audioEl = null; _audio.peaks = null;
  if(!state || !state.audio || !state.audio.ref){ _audio.attachedRef = null; _audioSyncUI(); return; }
  const ref = state.audio.ref;
  _audio.attachedRef = ref; // render()'s hook compares this to state.audio.ref (undo re-attach)
  const a = new Audio();
  a.preload = 'auto';
  a.src = storage.assetSrc(ref);
  _audio.audioEl = a;
  a.addEventListener('loadedmetadata', () => {
    if(!_audio || _audio.audioEl !== a) return;
    if(state && state.audio && state.audio.ref === ref && isFinite(a.duration) && a.duration > 0
       && Math.abs((state.audio.duration || 0) - a.duration) > 0.5){ state.audio.duration = a.duration; save(); }
    _audioSyncUI();
    if(typeof seekTo === 'number'){ _audioSeek(seekTo); seekTo = undefined; }
  });
  a.addEventListener('ended', () => { if(!_audio || _audio.audioEl !== a) return; _audioStopRaf(); _audioSyncPlayBtn(); _audioSyncTime(); });
  _audioSyncUI();
  try {
    const pk = await _audioPeaks(ref);
    if(!_audio || !state || !state.audio || state.audio.ref !== ref) return; // closed / replaced mid-decode
    if(pk.duration && Math.abs((state.audio.duration || 0) - pk.duration) > 0.5){ state.audio.duration = pk.duration; save(); }
    _audio.peaks = pk;
    _audioDrawWave();
    _audioRenderMarkers();
  } catch(e){ /* undecodable codec — playback + markers still work off <audio> metadata */ }
}

// Decode → peak buckets (max |sample| per bucket), cached per ref for the session.
async function _audioPeaks(ref){
  if(_audioPeaksCache.has(ref)) return _audioPeaksCache.get(ref);
  const resp = await fetch(storage.assetSrc(ref));
  const buf = await resp.arrayBuffer();
  const AC = window.AudioContext || window.webkitAudioContext;
  const ac = new AC();
  let ab;
  try { ab = await ac.decodeAudioData(buf); }
  finally { try { ac.close(); } catch(e){} }
  const ch = ab.getChannelData(0);
  const N = 1200;
  const step = Math.max(1, Math.floor(ch.length / N));
  const stride = Math.max(1, Math.floor(step / 64)); // sample within each bucket — full scans of long files are wasted work
  const peaks = new Float32Array(N);
  let max = 0;
  for(let i = 0; i < N; i++){
    let m = 0;
    const s0 = i * step, s1 = Math.min(ch.length, s0 + step);
    for(let j = s0; j < s1; j += stride){ const v = Math.abs(ch[j]); if(v > m) m = v; }
    peaks[i] = m; if(m > max) max = m;
  }
  const out = { peaks, max: max || 1, duration: ab.duration || 0 };
  _audioPeaksCache.set(ref, out);
  return out;
}

// Flat accent bars on the panel surface — no gradients, single color.
function _audioDrawWave(){
  if(!_audio || !_audio.canvas) return;
  const cv = _audio.canvas;
  const dpr = window.devicePixelRatio || 1;
  const w = cv.clientWidth, h = cv.clientHeight;
  if(!w || !h) return;
  cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
  const ctx = cv.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);
  const accent = (getComputedStyle(document.body).getPropertyValue('--accent') || '').trim() || '#E8792E';
  ctx.fillStyle = accent;
  const pk = _audio.peaks;
  if(!pk){ ctx.globalAlpha = 0.3; ctx.fillRect(0, h / 2 - 1, w, 2); return; } // still decoding / undecodable
  ctx.globalAlpha = 0.8;
  const n = pk.peaks.length;
  const barW = w / n;
  for(let i = 0; i < n; i++){
    const v = pk.peaks[i] / pk.max;
    const bh = Math.max(1.5, v * (h - 4));
    ctx.fillRect(i * barW, (h - bh) / 2, Math.max(0.8, barW * 0.65), bh);
  }
}

function _audioSyncUI(){
  if(!_audio) return;
  const has = !!(state && state.audio && state.audio.ref);
  _audio.emptyEl.hidden = has;
  _audio.canvas.style.visibility = has ? 'visible' : 'hidden';
  _audio.playheadEl.hidden = !has;
  _audio.playBtn.disabled = !has;
  _audio.nameEl.textContent = has ? (state.audio.name || 'Audio') : 'No track loaded';
  _audio.el.querySelectorAll('.ad-actions .btn').forEach(b => { b.hidden = !has; });
  _audio.hintEl.hidden = !has || !!(state.audio.markers && state.audio.markers.length);
  _audioDrawWave();
  _audioRenderMarkers();
  _audioSyncPlayBtn();
  _audioSyncTime();
  _audioSyncPlayhead();
}
function _audioSyncPlayBtn(){
  if(!_audio) return;
  const playing = !!(_audio.audioEl && !_audio.audioEl.paused && !_audio.audioEl.ended);
  _audio.playBtn.innerHTML = playing
    ? '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>'
    : '<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M8 5.5v13a1 1 0 0 0 1.52.86l10.2-6.5a1 1 0 0 0 0-1.72L9.52 4.64A1 1 0 0 0 8 5.5z"/></svg>';
  _audio.playBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function _audioSyncTime(){
  if(!_audio) return;
  const cur = _audio.audioEl ? (_audio.audioEl.currentTime || 0) : 0;
  _audio.timeEl.textContent = formatDuration(cur) + ' / ' + formatDuration(_audioDur());
}
function _audioSyncPlayhead(){
  if(!_audio) return;
  const d = _audioDur();
  const cur = _audio.audioEl ? (_audio.audioEl.currentTime || 0) : 0;
  _audio.playheadEl.style.left = d ? (Math.max(0, Math.min(1, cur / d)) * 100) + '%' : '0%';
}
function _audioTick(){
  if(!_audio || !_audio.audioEl || _audio.audioEl.paused){ if(_audio) _audio.raf = null; return; }
  _audioSyncPlayhead(); _audioSyncTime();
  _audio.raf = requestAnimationFrame(_audioTick);
}
function _audioTogglePlay(){
  if(!_audio || !_audio.audioEl || !state || !state.audio) return;
  const a = _audio.audioEl;
  if(a.paused){
    a.play().then(() => {
      if(!_audio || _audio.audioEl !== a) return;
      _audioSyncPlayBtn();
      if(!_audio.raf) _audio.raf = requestAnimationFrame(_audioTick);
    }).catch(() => note('Could not play that audio file'));
  } else {
    a.pause();
    _audioStopRaf();
  }
  _audioSyncPlayBtn();
}
function _audioSeek(t){
  if(!_audio || !_audio.audioEl) return;
  const d = _audioDur();
  try { _audio.audioEl.currentTime = Math.max(0, d ? Math.min(t, d) : t); } catch(e){}
  _audioSyncTime(); _audioSyncPlayhead();
}

// ----- Markers -----
function _audioRenderMarkers(){
  if(!_audio) return;
  const host = _audio.markersEl;
  host.innerHTML = '';
  const d = _audioDur();
  if(!state || !state.audio || !d) return;
  if(_audio.hintEl) _audio.hintEl.hidden = !!state.audio.markers.length;
  state.audio.markers.slice().sort((a, b) => a.t - b.t).forEach(m => {
    host.appendChild(_audioMarkerEl(m, d));
  });
}
function _audioMarkerEl(m, dur){
  const el = document.createElement('div');
  el.className = 'ad-marker' + (_audio.selId === m.id ? ' sel' : '');
  el.style.left = (Math.max(0, Math.min(m.t, dur)) / dur * 100) + '%';
  el.dataset.id = m.id;

  const stem = document.createElement('div'); stem.className = 'ad-mstem';

  const flag = document.createElement('div'); flag.className = 'ad-mflag';
  const tx = document.createElement('span'); tx.className = 'ad-mtx';
  tx.textContent = (m.label && m.label.trim()) ? m.label.trim() : formatDuration(m.t);
  const x = document.createElement('button'); x.className = 'ad-mx'; x.type = 'button'; x.textContent = '✕'; x.title = 'Remove marker';
  x.addEventListener('pointerdown', ev => ev.stopPropagation());
  x.addEventListener('click', ev => {
    ev.stopPropagation();
    state.audio.markers = state.audio.markers.filter(k => k.id !== m.id);
    if(_audio.selId === m.id) _audio.selId = null;
    save();
    _audioRenderMarkers();
  });
  flag.append(tx, x);
  flag.title = formatDuration(m.t) + ' — drag to move, double-click to rename';

  // Drag repositions; a still click selects/deselects. No _capture here — the
  // dock lives outside the canvas interaction model, window listeners suffice.
  flag.addEventListener('pointerdown', ev => {
    if(ev.button !== 0) return;
    ev.stopPropagation(); ev.preventDefault();
    const rect = _audio.wavewrap.getBoundingClientRect();
    const d = _audioDur(); if(!d) return;
    let moved = false;
    const startX = ev.clientX, startT = m.t;
    const onMove = e => {
      const dx = e.clientX - startX;
      if(!moved && Math.abs(dx) <= 3) return;
      moved = true;
      m.t = Math.max(0, Math.min(d, startT + dx / rect.width * d));
      el.style.left = (m.t / d * 100) + '%';
      if(!(m.label && m.label.trim())) tx.textContent = formatDuration(m.t);
      flag.title = formatDuration(m.t) + ' — drag to move, double-click to rename';
    };
    const onUp = () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      if(!_audio) return;
      if(moved){ save(); }
      else { _audio.selId = (_audio.selId === m.id) ? null : m.id; }
      _audioRenderMarkers();
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  });
  // Double-click the flag → inline rename (the marker label becomes the
  // spawned beat's title, so naming is worth the affordance).
  flag.addEventListener('dblclick', ev => {
    ev.stopPropagation();
    const inp = document.createElement('input');
    inp.className = 'ad-mrename'; inp.type = 'text'; inp.maxLength = 80;
    inp.value = m.label || ''; inp.placeholder = formatDuration(m.t);
    tx.textContent = ''; tx.appendChild(inp);
    inp.focus(); inp.select();
    let closed = false;
    const done = ok => {
      if(closed) return; closed = true;
      if(ok){ m.label = inp.value.trim(); save(); }
      _audioRenderMarkers();
    };
    inp.addEventListener('keydown', e => {
      e.stopPropagation();
      if(e.key === 'Enter') done(true);
      else if(e.key === 'Escape') done(false);
    });
    inp.addEventListener('blur', () => done(true));
    inp.addEventListener('pointerdown', e => e.stopPropagation());
  });

  // Hover/selection action: "+ Beat" spawns; a live beat shows a jump chip.
  const act = document.createElement('div'); act.className = 'ad-mact';
  const live = m.beatId && (state.nodes || []).find(n => n.id === m.beatId);
  if(live) el.classList.add('is-linked');
  const b = document.createElement('button'); b.className = 'ad-mbeat'; b.type = 'button';
  if(live){
    b.textContent = '→ ' + (((live.title || '').trim()) || 'Beat');
    b.title = 'Jump to this marker\'s beat on the canvas';
    b.addEventListener('click', ev => { ev.stopPropagation(); jumpToNode(live); });
  } else {
    b.textContent = '+ Beat';
    b.title = 'Create a beat on the canvas carrying this timecode';
    b.addEventListener('click', ev => { ev.stopPropagation(); _audioSpawnBeat(m); });
  }
  b.addEventListener('pointerdown', ev => ev.stopPropagation());
  act.appendChild(b);
  // Joao: spawning a new beat can't be the only move — a marker has to be able
  // to adopt a beat that already exists. Sits next to the chip in BOTH states
  // (empty marker → link one; linked marker → re-point or unlink). Icon-only so
  // the bubble stays a chip on a waveform, and the chain glyph is already the
  // house sign for "point this at an existing card" (the shot-list rows use it).
  const lk = document.createElement('button'); lk.className = 'ad-mlink'; lk.type = 'button';
  lk.innerHTML = SL_CHAIN_ICON;
  lk.title = live ? 'Link this marker to a different beat, or unlink it' : 'Link this marker to a beat that already exists';
  lk.setAttribute('aria-label', lk.title);
  lk.addEventListener('pointerdown', ev => ev.stopPropagation());
  lk.addEventListener('click', ev => { ev.stopPropagation(); _audioOpenBeatPicker(m, lk); });
  act.appendChild(lk);

  el.append(act, flag, stem);
  return el;
}

// The marker-beat spine: chain consecutive MARKER-beats head-to-tail with
// continues edges (the outline-composer precedent). Only the marker chain is
// touched — unrelated beats keep their edges. Shared by BOTH ways a marker
// gets a beat (spawn and link) so the two land identically. Call it after
// m.beatId is set.
function _audioChainMarkerBeat(m){
  const id = m.beatId; if(!id) return;
  const chain = state.audio.markers
    .filter(mk => mk.beatId && state.nodes.some(x => x.id === mk.beatId))
    .sort((a, b) => a.t - b.t);
  const i = chain.findIndex(mk => mk.id === m.id);
  const prev = i > 0 ? chain[i - 1] : null;
  const next = (i >= 0 && i < chain.length - 1) ? chain[i + 1] : null;
  if(prev && next){
    // Inserting between two linked marker-beats: the old direct hop yields to
    // the new stop, so the chain stays a single spine. A LABELED edge is the
    // user's own annotation, not chain plumbing — never silently drop it.
    state.edges = state.edges.filter(e => !(e.from === prev.beatId && e.to === next.beatId && (e.type || 'continues') === 'continues' && !(e.label && e.label.trim())));
  }
  if(prev && !state.edges.some(e => e.from === prev.beatId && e.to === id)) state.edges.push({ from: prev.beatId, to: id, type: 'continues', label: '' });
  if(next && !state.edges.some(e => e.from === id && e.to === next.beatId)) state.edges.push({ from: id, to: next.beatId, type: 'continues', label: '' });
}

// Marker → beat: spawn at view center (explicit coords bypass the drag-spawn
// finisher — T1.1), stamp beat.tc, then join the spine.
function _audioSpawnBeat(m){
  if(IS_VIEWER || !state || !state.audio) return;
  const existing = (state.nodes || []).find(n => n.id === m.beatId);
  if(existing){ jumpToNode(existing); return; }
  const title = (m.label && m.label.trim()) || ('Beat at ' + formatDuration(m.t));
  const c = viewCenterWorld();
  const sp = freeSpot(c.x - NODE_W / 2, c.y - 70);
  const n = addNode({ type: 'beat', title, x: sp.x, y: sp.y });
  n.tc = m.t;
  m.beatId = n.id;
  _audioChainMarkerBeat(m);
  save(); render();
  note('Beat created at ' + formatDuration(m.t));
}

// Marker → EXISTING beat (Joao's ask). Same write as the spawn path — stamp
// the beat's tc, then join the spine — so a linked marker is indistinguishable
// from a spawned one afterwards. Unlinking is the picker's own clear row.
function _audioOpenBeatPicker(m, anchor){
  if(IS_VIEWER || !state || !state.audio) return;
  openLinkPickerPop({
    anchor,
    // Alts are branches off a beat, not points on the track's timeline.
    items: (state.nodes || []).filter(n => (n.type || 'beat') === 'beat' && !n.alt),
    currentId: m.beatId,
    icon: SL_BEAT_ICON,
    iconClass: 'sl-link-beat',
    placeholder: 'Link a beat…',
    itemFallbackLabel: '(untitled beat)',
    emptyLabel: 'No beats yet. Use + Beat to make one.',
    clearLabel: 'Unlink beat',
    onPick: (n) => {
      if(!n){
        // The edges the marker put on the spine stay — they are the story's
        // flow now, and detaching a timing marker shouldn't tear it up.
        m.beatId = null;
        save(); render();
        note('Marker unlinked');
        return;
      }
      // A beat carries ONE tc, so it can only sit at one marker — an older
      // marker holding this beat lets go rather than contradicting the new time.
      state.audio.markers.forEach(mk => { if(mk !== m && mk.beatId === n.id) mk.beatId = null; });
      m.beatId = n.id;
      n.tc = m.t;
      _audioChainMarkerBeat(m);
      save(); render();
      note('Linked to "' + (((n.title || '').trim()) || 'Beat') + '" at ' + formatDuration(m.t));
    }
  });
}

// ----- Loading / removing the track -----
// True for anything the audio dock should treat as a track. Type sniffing
// alone misses files Finder hands over with an empty MIME, so extensions back
// it up.
function _isAudioFile(f){
  if(!f) return false;
  if(f.type && f.type.indexOf('audio/') === 0) return true;
  return /\.(mp3|m4a|wav|aac|ogg|oga|flac|aiff?|caf)$/i.test(String(f.name || ''));
}
// One funnel for every way a track arrives — the picker, a drop on the dock,
// a drop on the canvas. Opens the dock if it is closed so the load is visible.
function _audioLoadFromFile(f){
  if(IS_VIEWER || !state || !f) return;
  if(!_audio) openAudioDock();
  const r = new FileReader();
  r.onload = () => _audioLoadFromDataUrl(String(r.result || ''), f.name);
  r.onerror = () => note('Could not read that audio file');
  r.readAsDataURL(f);
}
function _audioPickFile(){
  if(IS_VIEWER || !state) return;
  const inp = document.createElement('input');
  inp.type = 'file';
  // Extensions only, no `audio/*` wildcard — same reason pickBoardDocuments
  // spells its list out: a wildcard MIME in accept makes the macOS webview's
  // picker misbehave. Here it never opened the panel at all, which read as a
  // dead "Load audio…" button.
  inp.accept = '.mp3,.m4a,.wav,.aac,.ogg,.oga,.flac,.aiff,.aif,.caf';
  inp.addEventListener('change', () => {
    const f = inp.files && inp.files[0]; if(!f) return;
    _audioLoadFromFile(f);
  });
  inp.click();
}
async function _audioLoadFromDataUrl(dataUrl, name){
  if(!state || !dataUrl) return;
  // Legacy mode stores the data URL itself in project state — warn on big files.
  if(!HAS_TAURI && dataUrl.length * 0.75 > 8 * 1024 * 1024)
    note('Large audio file — browser storage may not hold it. The desktop app keeps audio on disk.');
  let ref;
  try { ref = await storage.writeAssetFromDataUrl('audio', dataUrl, name); }
  catch(e){ note('Could not store that audio file'); return; }
  const old = state.audio && state.audio.ref;
  const markers = (state.audio && state.audio.markers) || []; // replacing keeps markers (a new mix of the same track is the common case)
  state.audio = { ref, name: name || 'Audio', duration: 0, markers };
  save();
  if(old && old !== ref){ _retireAsset(old); _audioPeaksCache.delete(old); }
  _audioAttachTrack();
}
async function _audioRemoveTrack(){
  if(IS_VIEWER || !state || !state.audio) return;
  const nMarkers = (state.audio.markers || []).length;
  const ok = await uiConfirm(
    'Remove the audio track' + (nMarkers ? ' and its ' + nMarkers + ' marker' + (nMarkers === 1 ? '' : 's') : '') + '?\nBeats you created keep their timecodes.',
    { ok: 'Remove audio', danger: true });
  if(!ok) return;
  const old = state.audio.ref;
  _audioPausePlayback();
  state.audio = null;
  save();
  if(old){ _retireAsset(old); _audioPeaksCache.delete(old); }
  if(_audio){ _audio.selId = null; _audioAttachTrack(); }
  note('Audio removed');
}

// ── W3.5 — Presentation mode ─────────────────────────────────────────────────
// Full-screen story walkthrough for pitching a room. Slides come from
// walkExportOrder (the default walk — hiddenInExport respected) and render
// through a DEDICATED slide renderer: big type via the app's CSS tokens on a
// SOLID --bg backdrop, so both themes come for free. Read-only by design —
// no state writes anywhere in here (IS_VIEWER-safe for the same reason).
// Sequence: cover → [section | title | beat | aside]… Sections come from
// non-virtual group-starts (including sequence spines), but only when
// presentable content follows before the next section — an empty section
// slide says nothing to a room. Alt beats and reference/structural cards
// (characters, locations, props, galleries, shot lists, set plans…) are
// skipped: a presentation is the spine, not the binder.
let _present = null; // { el, stage, counter, slides, idx } while presenting

function _presentSlides(){
  // A section header is held back until content accrues from ITS OWN group:
  // group-end (and the virtual orphan bucket) drops an unused header, so a
  // group holding only reference cards can never donate its name to the
  // unrelated slides that follow it (review fix — sections don't nest, so
  // one pending slot is enough).
  const slides = [];
  let kicker = '';
  let pending = null;
  const content = s => { if(pending){ slides.push(pending); pending = null; } slides.push(s); };
  walkExportOrder(state).forEach(it => {
    if(it.kind === 'group-start'){
      kicker = (!it.virtual && it.group && it.group.name) ? String(it.group.name).trim() : '';
      pending = (kicker && !it.virtual) ? { kind: 'section', name: kicker, color: it.group.color || null } : null;
      return;
    }
    if(it.kind === 'group-end'){ kicker = ''; pending = null; return; }
    const n = it.node; if(!n) return;
    const type = n.type || 'beat';
    if(type === 'title') content({ kind: 'title', node: n });
    else if(type === 'beat' && !n.alt) content({ kind: 'beat', node: n, kicker });
    else if(type === 'note' || type === 'thought') content({ kind: 'aside', node: n });
  });
  return slides;
}

function openPresentMode(){
  if(!state){ note('Open a project first'); return; }
  if(_present) closePresentMode();
  if(_cmdkBlocked()) return; // a modal editor owns the keyboard — don't present over it
  closeOnset(); // On set would float over the deck
  _audioPausePlayback(); // W4.2 — a track scrubbing under the deck distracts the room
  const slides = _presentSlides();
  if(!slides.length){ note('Nothing to present yet — add beats or titles first'); return; }
  slides.unshift({ kind: 'cover' });

  const el = document.createElement('div');
  el.className = 'present-overlay';
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-label', 'Presentation');
  const stage = document.createElement('div'); stage.className = 'present-stage';
  const closeBtn = document.createElement('button');
  closeBtn.className = 'present-close'; closeBtn.textContent = '✕'; closeBtn.title = 'Exit (Esc)';
  closeBtn.addEventListener('click', ev => { ev.stopPropagation(); closePresentMode(); });
  const counter = document.createElement('div'); counter.className = 'present-counter';
  el.append(stage, closeBtn, counter);
  // Click-halves navigate: left half back, right half forward.
  el.addEventListener('click', ev => {
    if(!_present) return;
    _presentNav(ev.clientX < window.innerWidth / 2 ? -1 : 1);
  });
  document.body.appendChild(el);
  window.addEventListener('keydown', _presentKey, true);
  _present = { el, stage, counter, slides, idx: 0 };
  _presentRenderSlide();
  if(!toolWalkthroughSeen('present')) setTimeout(runPresentTour, 450); // no-ops if closed meanwhile
}
// First-open coach for Presentation mode (W4.4). Two steps, then the room
// takes over. The coach card lives on document.body, outside the overlay, so
// clicking Next never advances a slide.
function runPresentTour(){
  if(!_present) return;
  if(document.querySelector('.onboard-card')) return;
  document.querySelectorAll('.sp-coach, .sp-coach-spot').forEach(n => n.remove());
  runToolWalkthrough('present', _present.el, [
    { sel: '.present-stage', place: 'over', title: 'Your story on stage',
      body: 'A cover, then one slide per section, title and beat — images included. Nothing on your board changes; this is just a lens on it.' },
    { sel: '.present-stage', place: 'over', title: 'Moving through it',
      body: 'Right arrow, Space or a click on the right half advances; left arrow or the left half goes back. Home jumps to the cover, End to the last slide.' },
    { title: 'Order, and the way out',
      body: 'Slides follow the board\'s reading order — the same order as the Outline and your exports. Hidden-from-export cards stay off stage. Esc leaves the presentation.' }
  ], null, document.body);
}
function closePresentMode(){
  if(!_present) return;
  window.removeEventListener('keydown', _presentKey, true);
  _present.el.remove();
  _present = null;
}
function _presentNav(d){
  if(!_present) return;
  // Clamp, don't wrap — a deck that loops past its ending undercuts the close.
  const nx = Math.max(0, Math.min(_present.idx + d, _present.slides.length - 1));
  if(nx === _present.idx) return;
  _present.idx = nx;
  _presentRenderSlide();
}
// Window capture like the palette: runs before every document-level handler
// regardless of registration order, so Esc never leaks to overlays beneath
// and no canvas shortcut (delete, undo, add…) can fire while a room is
// watching. Unhandled keys are swallowed (stopPropagation only — browser
// defaults like reload stay intact).
function _presentKey(ev){
  if(!_present) return;
  if(ev.key === 'Escape'){ ev.preventDefault(); ev.stopPropagation(); closePresentMode(); return; }
  if(ev.key === 'ArrowLeft'){ ev.preventDefault(); ev.stopPropagation(); _presentNav(-1); return; }
  if(ev.key === 'ArrowRight' || ev.key === ' '){ ev.preventDefault(); ev.stopPropagation(); _presentNav(1); return; }
  // Presenter-remote staples: jump to the cover / the last slide.
  if(ev.key === 'Home'){ ev.preventDefault(); ev.stopPropagation(); _present.idx = 0; _presentRenderSlide(); return; }
  if(ev.key === 'End'){ ev.preventDefault(); ev.stopPropagation(); _present.idx = Math.max(0, _present.slides.length - 1); _presentRenderSlide(); return; }
  ev.stopPropagation();
}
function _presentRenderSlide(){
  if(!_present) return;
  const { stage, counter, slides, idx } = _present;
  const s = slides[idx];
  stage.innerHTML = '';
  const slide = document.createElement('div');
  slide.className = 'present-slide present-' + s.kind;
  let fitBody = null; // beat body element — clamp is re-fitted after append
  const div = (cls, text) => {
    const d = document.createElement('div'); d.className = cls;
    if(text != null) d.textContent = text; // user text — never innerHTML
    return d;
  };

  if(s.kind === 'cover'){
    const company = ((state.identity && state.identity.company) || '').trim();
    if(company) slide.appendChild(div('present-kicker', company));
    slide.appendChild(div('present-cover-name', state.name || 'Untitled project'));
    const credit = state.showAuthorCredit !== false ? exportAuthorCredit() : null;
    if(credit){
      slide.appendChild(div('present-credit', credit.line1));
      if(credit.line2) slide.appendChild(div('present-credit-sub', credit.line2));
    }
  } else if(s.kind === 'section'){
    const bar = div('present-accentbar', null);
    if(s.color) bar.style.background = s.color;
    slide.append(bar, div('present-section-name', s.name));
  } else if(s.kind === 'title'){
    slide.appendChild(div('present-title-main', s.node.title || 'Untitled'));
    const sub = _mdToPlain(s.node.body || '');
    if(sub) slide.appendChild(div('present-title-sub', sub));
  } else if(s.kind === 'aside'){
    const t = (s.node.title || '').trim();
    if(t) slide.appendChild(div('present-aside-title', t));
    slide.appendChild(div('present-aside-body', _mdToPlain(s.node.body || '') || '—'));
  } else { // beat — the star slide: kicker / title / autoscaled body / images
    if(s.kicker) slide.appendChild(div('present-kicker', s.kicker));
    slide.appendChild(div('present-beat-title', s.node.title || 'Untitled beat'));
    const body = _mdToPlain(s.node.body || '');
    const sel = exportImageSel(s.node);
    const imgs = (sel !== null ? sel : (s.node.images || [])).slice(0, 3);
    if(body){
      // Autoscale: three size steps by length; then a line clamp (tighter when
      // images share the slide) so the worst case ellipsizes instead of
      // pushing the image row off screen. These counts are CEILINGS — the
      // fit pass below shrinks them to the measured line budget.
      const step = body.length <= 240 ? 'lg' : body.length <= 600 ? 'md' : 'sm';
      fitBody = div('present-beat-body present-body-' + step, body);
      fitBody.style.webkitLineClamp = String(imgs.length
        ? { lg: 6, md: 8, sm: 10 }[step]
        : { lg: 10, md: 13, sm: 16 }[step]);
      slide.appendChild(fitBody);
    }
    if(imgs.length){
      const row = document.createElement('div');
      row.className = 'present-imgrow' + (imgs.length === 1 ? ' present-imgrow-one' : '');
      imgs.forEach(ref => {
        const img = document.createElement('img');
        img.alt = ''; img.draggable = false;
        img.src = storage.assetSrc(ref);
        row.appendChild(img);
      });
      slide.appendChild(row);
    }
  }
  stage.appendChild(slide);
  // Fit pass (review fix): a clamped 3-line title + kicker + image row can
  // still outgrow a short window with the table counts above, and the stage's
  // vertical centering would then bleed the slide off BOTH edges. Measure the
  // real line budget — stage inner height minus everything that isn't body —
  // and shrink the clamp to it (never grow past the table ceiling).
  if(fitBody){
    const cs = getComputedStyle(stage);
    const avail = stage.clientHeight - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
    const lineH = parseFloat(getComputedStyle(fitBody).lineHeight) || 24;
    const others = slide.scrollHeight - fitBody.offsetHeight;
    const fit = Math.max(1, Math.floor((avail - others) / lineH));
    const cur = parseInt(fitBody.style.webkitLineClamp, 10) || fit;
    if(fit < cur) fitBody.style.webkitLineClamp = String(fit);
  }
  counter.textContent = (idx + 1) + ' / ' + slides.length;
}

// Static command registry. Labels + key hints reuse the SHORTCUTS cheat-sheet
// vocabulary; export commands mirror the Export menu's buttons live so the
// palette never drifts from it. Creates clear any pending drag-spawn first —
// the capture-phase click canceller only covers pointer paths, and a
// keyboard-triggered create must not inherit a stale spawn anchor.
function _cmdkCommands(){
  if(IS_VIEWER) return [];
  const create = t => () => { _closeSpawnMenu(true); dispatchAddType(t); };
  const cmds = [
    { label: 'New beat',      kw: 'new add create card',            act: create('beat') },
    { label: 'New character', kw: 'new add create person cast',     act: create('character') },
    { label: 'New location',  kw: 'new add create place set',       act: create('location') },
    { label: 'New prop',      kw: 'new add create object',          act: create('prop') },
    { label: 'New note',      kw: 'new add create aside text',      act: create('note') },
    { label: 'New gallery',   kw: 'new add create images board',    act: create('gallery') },
    { label: 'New sketch',    kw: 'new add create draw drawing',    act: create('sketch') },
    { label: 'New shot list', kw: 'new add create shots camera',    act: create('shotlist') },
    { label: 'New set plan',  kw: 'new add create floor plan setplan', act: create('setplan') },
    { label: 'Toggle Writing Mode', kw: 'write document treatment editor', key: '⌘ Shift W', act: () => toggleWrite() },
    { label: 'Toggle Outline',      kw: 'outline document reading order',  act: () => toggleOutline() },
    { label: 'Toggle Vault',        kw: 'vault media library images gifs', key: '⌘ B', act: () => toggleMediaTab() },
    { label: 'Toggle Project info', kw: 'settings name theme palette context about', key: '⌘ I', act: () => toggleInfoPanel() },
    { label: 'Toggle Focus mode (Write)', kw: 'focus dim writing distraction', act: () => {
        if(!state || !state.view) return;
        if(!state.view.writeOpen){ state.view.writeFocus = true; openWrite(); }
        else { state.view.writeFocus = !state.view.writeFocus; applyWriteLayout(); save(); }
      } },
    { label: 'On set mode',     kw: 'onset shooting run shot list check off got it', act: () => cmdOnSetMode() },
    { label: 'Audio timeline',  kw: 'audio music track song waveform markers timecode dock', act: () => toggleAudioDock() },
    { label: 'Present story',   kw: 'present presentation slides full screen pitch walkthrough', act: () => openPresentMode() },
    { label: 'Fit view',        kw: 'zoom recenter frame all content',  key: '⌘ 0', act: () => fitView() },
    { label: 'Toggle minimap',  kw: 'map overview navigator',           act: () => toggleMinimap() },
    { label: 'Minimap: map / strip', kw: 'shape film strip timeline duration', act: () => setMinimapMode(_minimapMode === 'strip' ? 'map' : 'strip') },
    { label: 'Open Projects',   kw: 'projects browse switch library',   key: '⌘ T', act: () => openProjectsModal() },
    { label: 'Save now',        kw: 'save project thumbnail',           key: '⌘ S', act: () => saveProjectExplicit() },
    // Everything behind the ⋯ button, searchable. Preferences was the notable
    // absence — the complaint that started this round was that it is hard to
    // find, and a menu you have to know about is not findable. Keywords carry
    // the words people actually type ("settings", "options") and the things
    // that are IN it, since the panel's own sections are what they are after.
    // ⌘ , is the native menu's accelerator, so only the Mac app really has it.
    { label: 'Inspector',       kw: 'inspector panel card fields edit properties', key: 'I', act: () => toggleInspector() },
    { label: 'Toggle Clean cards',  kw: 'clean cards hide empty fields',   act: () => { const b = document.getElementById('cleanCardsBtn'); if(b) b.click(); } },
    { label: 'Preferences',     kw: 'settings options config library folder your name credit exports minimap walkthroughs', key: HAS_TAURI ? '⌘ ,' : '', act: () => openPrefsPanel() },
    { label: 'Version history', kw: 'snapshots restore undo revert earlier backup', act: () => openSnapshotsModal() },
    { label: 'Locations map',   kw: 'map pins places scout geo locations',  act: () => openLocationsMap() },
    { label: 'Show me around',  kw: 'walkthrough tour help guide replay',   act: () => openTourHub() },
  ];
  // Tauri only — the web build has no filesystem to point anywhere.
  if(HAS_TAURI) cmds.push({ label: 'Change library folder…', kw: 'settings library folder move projects location icloud', act: () => {
    const b = document.getElementById('changeLibraryMenuBtn'); if(b) b.click();
  } });
  document.querySelectorAll('#exportMenu button[data-x]').forEach(b => {
    const label = 'Export: ' + (b.textContent || '').replace(/\s+/g, ' ').trim();
    cmds.push({ label, kw: 'export ' + (b.dataset.x || ''), act: () => b.click() });
  });
  cmds.push({ label: 'Show keyboard shortcuts', kw: 'help cheat sheet keys', key: '?', act: () => openCheatSheet() });
  return cmds;
}

// Rank: label prefix, label word-start, label substring, then haystack
// word-start / substring. Multi-word queries: every token must match
// somewhere; the item ranks by its weakest token. Ties break alphabetically.
function _cmdkRank(items, q){
  const toks = q.split(/\s+/).filter(Boolean);
  if(!toks.length) return [];
  const scored = [];
  items.forEach(it => {
    const l = it.label.toLowerCase();
    const h = it.hay || '';
    let worst = -1;
    for(const t of toks){
      let s = -1;
      if(l.startsWith(t)) s = 0;
      else if(l.indexOf(' ' + t) !== -1) s = 1;
      else if(l.indexOf(t) !== -1) s = 2;
      else if((' ' + h).indexOf(' ' + t) !== -1) s = 3;
      else if(h.indexOf(t) !== -1) s = 4;
      if(s < 0){ worst = -1; break; }
      if(s > worst) worst = s;
    }
    if(worst >= 0) scored.push([worst, it]);
  });
  scored.sort((a, b) => a[0] - b[0] || a[1].label.localeCompare(b[1].label));
  return scored.map(p => p[1]);
}

// Modal EDITING contexts that own the keyboard while open — the palette must
// not open over them (they run their own key models: undo stacks, Esc
// semantics, focused inputs; palette actions could corrupt their state).
// Dynamic overlays count as active by DOM presence; the persistent singletons
// (#videoImporter, #docViewer, #welcomeModal) toggle [hidden] instead.
// Passive overlays (cheat sheet, news, tour hub) are deliberately NOT listed —
// the palette legitimately opens above those (z-index 13400, top tier).
// The presentation overlay (W3.5) and the lightbox are listed too — not
// editors, but their capture-phase key handlers own Esc/arrows; a palette or
// a presentation opening above either would fight them for the keyboard.
const _CMDK_BLOCKING_SEL = '.sp-overlay, .ie-overlay, .scout-overlay, .exc-overlay, ' +
  '.shotpreset-overlay, .ui-confirm, .simple-prompt-overlay, .present-overlay, ' +
  '#lightbox:not([hidden]), ' +
  '#videoImporter:not([hidden]), #docViewer:not([hidden]), #welcomeModal:not([hidden])';
function _cmdkBlocked(){ return !!document.querySelector(_CMDK_BLOCKING_SEL); }

let _cmdkClose = null; // set while the palette is open; toggling closes via it
function toggleCommandPalette(){
  if(_cmdkClose){ _cmdkClose(); return; }
  if(_cmdkBlocked()) return; // an editing overlay owns the keyboard — no palette
  if(!state){ note('Open a project first'); return; }
  openCommandPalette();
}
function openCommandPalette(){
  if(document.querySelector('.cmdk-backdrop')) return; // already open
  // A pending drag-spawn must not leak into palette-created cards.
  if(typeof _closeSpawnMenu === 'function' && !IS_VIEWER) _closeSpawnMenu(true);
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop cmdk-backdrop';
  const panel = document.createElement('div');
  panel.className = 'cmdk-panel';
  const input = document.createElement('input');
  input.className = 'cmdk-input'; input.type = 'text'; input.spellcheck = false;
  input.placeholder = IS_VIEWER ? 'Jump to anything…' : 'Jump to anything, or run a command…';
  const list = document.createElement('div'); list.className = 'cmdk-list';
  panel.append(input, list);
  backdrop.appendChild(panel);
  document.body.appendChild(backdrop);

  const jumpables = _cmdkJumpables();
  // Two cards named the same rendered identical rows — Enter always flew to
  // the first with no way to tell which. Duplicates grow a body snippet.
  { const seen = new Map();
    jumpables.forEach(it => seen.set(it.label, (seen.get(it.label) || 0) + 1));
    jumpables.forEach(it => {
      if(seen.get(it.label) > 1 && it.id){
        const n = (state.nodes || []).find(x => x.id === it.id);
        const snip = n ? _cmdkSnippet(n.body) : '';
        if(snip && snip !== it.label) it.label = it.label + ' — ' + snip.slice(0, 32);
      }
    });
  }
  const commands = _cmdkCommands();
  let rows = [], active = 0;

  // Dismissing the palette puts the caret back where it was; executing a
  // command lets the command own focus.
  const prevFocus = document.activeElement;
  const close = (restoreFocus) => {
    _cmdkClose = null;
    window.removeEventListener('keydown', onKey, true);
    backdrop.remove();
    if(restoreFocus && prevFocus && prevFocus.isConnected && typeof prevFocus.focus === 'function'){
      try { prevFocus.focus(); } catch(e){}
    }
  };
  _cmdkClose = close;
  const exec = row => { close(false); row.run(); };

  const paint = () => rows.forEach((r, i) => r.el.classList.toggle('active', i === active));
  const build = () => {
    const q = input.value.trim().toLowerCase();
    // No query = no default action: opening the palette and hitting Enter
    // "to see" must not quietly add a beat to the board.
    rows = []; active = q ? 0 : -1;
    list.innerHTML = '';
    const section = title => {
      const h = document.createElement('div'); h.className = 'cmdk-section';
      h.textContent = title; list.appendChild(h);
    };
    const push = (label, metaHtml, run) => {
      const el = document.createElement('div'); el.className = 'cmdk-row';
      const lab = document.createElement('span'); lab.className = 'cmdk-label';
      lab.textContent = label; el.appendChild(lab);
      if(metaHtml){
        const m = document.createElement('span'); m.className = 'cmdk-meta';
        m.innerHTML = metaHtml; el.appendChild(m);
      }
      const idx = rows.length;
      el.addEventListener('click', () => exec(rows[idx]));
      el.addEventListener('mouseenter', () => { active = idx; paint(); });
      list.appendChild(el);
      rows.push({ el, run });
    };
    // Kinds are our own constants and key hints our own strings — safe as HTML.
    const kindChip = k => '<span class="cmdk-kind">' + k + '</span>';
    const keyHtml = key => key ? key.split(' ').map(t => '<kbd>' + t + '</kbd>').join('') : '';
    const pushJump = it => push(it.label, kindChip(it.kind), () => _cmdkJumpTo(it));
    const pushCmd = c => push(c.label, keyHtml(c.key), c.act);
    if(!q){
      // Empty query: commands only (viewer has none — offer the board instead).
      if(commands.length){ section('Commands'); commands.slice(0, 10).forEach(pushCmd); }
      else if(jumpables.length){ section('Jump to'); jumpables.slice(0, 12).forEach(pushJump); }
    } else {
      const jr = _cmdkRank(jumpables, q).slice(0, 30);
      const cr = _cmdkRank(commands.map(c => ({ ...c, hay: (c.kw + ' ' + c.label).toLowerCase() })), q).slice(0, 10);
      if(jr.length){ section('Jump to'); jr.forEach(pushJump); }
      if(cr.length){ section('Commands'); cr.forEach(pushCmd); }
    }
    if(!rows.length){
      const empty = document.createElement('div'); empty.className = 'cmdk-empty';
      empty.textContent = 'No matches';
      list.appendChild(empty);
    }
    paint();
  };

  const onKey = ev => {
    if(ev.key === 'Escape'){ ev.preventDefault(); ev.stopPropagation(); close(true); return; }
    if(ev.key === 'ArrowDown' || ev.key === 'ArrowUp'){
      ev.preventDefault(); ev.stopPropagation();
      if(!rows.length) return;
      if(active < 0) active = ev.key === 'ArrowDown' ? 0 : rows.length - 1;
      else active = (active + (ev.key === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length;
      paint();
      rows[active].el.scrollIntoView({ block: 'nearest' });
      return;
    }
    if(ev.key === 'Enter'){
      ev.preventDefault(); ev.stopPropagation();
      if(active >= 0 && rows[active]) exec(rows[active]);
    }
  };
  // Window capture, not document: window-capture listeners run BEFORE any
  // document-capture ones regardless of registration order, so the palette's
  // stopPropagation genuinely shields overlays underneath it (e.g. the news
  // panel's own Esc-close never sees the palette's Esc).
  window.addEventListener('keydown', onKey, true);
  backdrop.addEventListener('pointerdown', ev => { if(ev.target === backdrop) close(true); });
  input.addEventListener('input', build);
  build();
  input.focus();
}

if(IS_VIEWER){
  // Render the embedded state instead of normal startup
  document.body.classList.add('beat-view');
  try {
    state = normalizeState(window.__BEAT_VIEWER_STATE__, 'Beat project');
  } catch(e){ state = null; }
  if(state){
    applyTheme(state.theme);
    document.title = (state.name || 'Beat project') + ' — Beat (read-only)';
    // Replace the editable project-name input with a static span
    const projInp = document.getElementById('brandProjectName');
    if(projInp){
      const span = document.createElement('span');
      span.className = 'brand-project brand-project-readonly';
      span.textContent = state.name || '';
      projInp.parentNode.replaceChild(span, projInp);
    }
    seedUid();
    render();
    fitView();
    // Add the view-only badge in the bottom-right
    const badge = document.createElement('div');
    badge.className = 'beat-view-badge';
    badge.innerHTML = 'Shared from <b>Beat</b> · view-only';
    document.body.appendChild(badge);
  } else {
    document.body.innerHTML = '<div style="padding:40px;font-family:sans-serif;color:#555;">This Beat snapshot could not be loaded.</div>';
  }
} else {
  if(HAS_TAURI){
    // Always show the Projects modal at boot under Tauri. Clicking a card
    // populates state via openProject(); closing a project returns here.
    openProjectsModal();
    updateBrandingForCurrentProject();
  } else {
    if(state) applyTheme(state.theme);
    if(state){ render(); fitView(); }
    else { openProjectsModal(); }
    updateBrandingForCurrentProject();
    if(state){ undoStack.push(snapshotState()); }
  }
  // #47 — paint persisted tabs even before a project is opened.
  renderTabBar();
  // #101 — install the pomodoro chip in the toolbar.
  _injectPomodoroChip();
  // #102 — start the 3-minute snapshot cadence (Tauri only).
  if(HAS_TAURI) startSnapshotTimer();
  // #119 — listen for native-menu events from the Rust side.
  if(HAS_TAURI && window.__TAURI__ && window.__TAURI__.event){
    try {
      window.__TAURI__.event.listen('menu-action', ev => handleMenuAction(ev && ev.payload));
    } catch(e){ /* event API not available — fall through to in-app menus */ }
    // Link-to-Claude live reload: the connector signals via .beat-sync.json,
    // the Rust watcher forwards it here. Only react for the open project.
    try {
      const _beatSyncReg = window.__TAURI__.event.listen('beat-sync', ev => {
        const p = ev && ev.payload; if(!p) return;
        const openName = currentProjectId ? String(currentProjectId).split(/[\\/]/).pop() : null;
        // Round 73: the connector can ask Beat to OPEN a project (open_project
        // tool) — so a finished build ends with the user looking at it, not
        // hunting for it in the modal. Must run BEFORE the same-project gate:
        // the whole point is that it is usually a DIFFERENT project.
        if(p.status === 'open'){
          if(openName && p.project === openName) return;      // already showing it
          storage.listProjects().then(list => {
            const hit = (list || []).find(pr => String(pr.path || pr.id || '').split(/[\\/]/).pop() === p.project);
            if(hit) openProject(hit.path || hit.id);
          }).catch(() => {});
          return;
        }
        if(!openName || p.project !== openName) return;
        if(p.status === 'writing'){ _claudeWriting = true; showClaudeEditingCue(p.message || 'Claude is editing…'); return; }
        if(p.status === 'done'){
          _claudeWriting = false;
          hideClaudeEditingCue();
          const inEditable = document.activeElement && /^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName);
          if(inEditable){ showClaudeReloadPrompt(); }
          else { reloadOpenProjectFromDisk(); }
        }
      });
      // listen() is async — a denied/rejected registration would otherwise be swallowed
      // silently (sync try/catch can't catch a Promise rejection). Surface it to the console.
      if(_beatSyncReg && _beatSyncReg.then){
        _beatSyncReg.catch(err => { try { console.warn('beat-sync listen failed:', err); } catch(_e){} });
      }
    } catch(e){ try { console.warn('beat-sync listen threw:', e); } catch(_e){} }
  }
}

// ---------- Link-to-Claude live reload helpers ----------
let _claudeCueEl = null;
function _ensureClaudeCue(){
  if(!_claudeCueEl){ _claudeCueEl = document.createElement('div'); _claudeCueEl.className = 'claude-cue'; document.body.appendChild(_claudeCueEl); }
  return _claudeCueEl;
}
function showClaudeEditingCue(msg){ const el = _ensureClaudeCue(); el.textContent = msg; el.hidden = false; }
function hideClaudeEditingCue(){ if(_claudeCueEl) _claudeCueEl.hidden = true; }
function showClaudeReloadPrompt(){
  const el = _ensureClaudeCue();
  el.innerHTML = 'Claude updated this project · <button class="claude-cue-reload">Reload</button>';
  el.hidden = false;
  const b = el.querySelector('.claude-cue-reload');
  if(b) b.addEventListener('click', () => reloadOpenProjectFromDisk());
}
async function reloadOpenProjectFromDisk(){
  if(!currentProjectId) return;
  if(_histPreviewing) exitHistPreview(); // disk just changed — drop the preview, reload truth
  try {
    const fresh = await storage.loadProjectState(currentProjectId);
    if(fresh){
      // Round 48: never assign null over the LIVE state — a bad connector
      // write would blank the user's open session with no way back.
      const _st = normalizeState(fresh, state && state.name);
      if(!_st){ note('Claude wrote an unreadable file — keeping your version'); return; }
      state = _st;
      _invalidateMentionCache(); // round 49
      seedUid();
      render();
      applyWriteLayout(); if(state.view.writeOpen) renderWriteDoc();
      ensureProjectThumbs(); // pick up thumbs for any media Claude/MCP just added
      hideClaudeEditingCue();
      note('Updated by Claude');
    }
  } catch(e){ console.error('reload from disk', e); }
}

// #119 — route a menu-action id to the right UI handler.
function handleMenuAction(id){
  if(!id) return;
  switch(id){
    // Beat → Preferences… (Cmd ,) used to open the PER-PROJECT info panel, which
    // also refused to open with no project. It's the Mac's front door to global
    // settings, so it goes to Preferences. (The native item said "Settings…"
    // until this round — same room, two names, so nobody found either.)
    case 'open-settings':       return openPrefsPanel();
    case 'file-new':            return openProjectsModal();   // user creates from there
    case 'file-open':
      if(HAS_TAURI){
        (async () => {
          const picked = await storage.pickFolder('Open a Beat project folder');
          if(!picked) return;
          try { await storage.loadProjectState(picked); await openProject(picked); }
          catch(err){ note('That folder is not a Beat project (missing .beat or project.json)'); }
        })();
      } else {
        openProjectsModal();
      }
      return;
    case 'file-projects':       return openProjectsModal();
    case 'file-save': {
      const btn = document.getElementById('saveProjectBtn');
      if(btn) btn.click(); else save();
      return;
    }
    case 'file-reveal':
      if(HAS_TAURI && currentProjectId){
        window.__TAURI__.core.invoke('reveal_path', { path: currentProjectId }).catch(() => {});
      }
      return;
    case 'file-share':
      // #128 — open the project folder in Finder so the user can use the
      // native Share menu / drag-out to Mail / Messages / AirDrop.
      if(HAS_TAURI && currentProjectId){
        window.__TAURI__.core.invoke('reveal_path', { path: currentProjectId }).catch(() => {});
        note('Project revealed in Finder — right-click → Share');
      }
      return;
    // W3.8 — while the Export Center is open it owns exporting: these no-op
    // (the DOCX include modal / AI modal would open UNDER the overlay, and a
    // mid-preview jsPDF run would race the center's _exportRun flags). The
    // jsPDF ones also ride the center's serialized chain so they can never
    // interleave with a preview or a center export still in flight.
    case 'file-export-overview':
      if(document.querySelector('.exc-overlay')) return;
      _excEnqueue(() => printShotListPdf());
      return;
    case 'file-export-storyboard':
      if(document.querySelector('.exc-overlay')) return;
      _excEnqueue(() => printStoryboardPdf());
      return;
    case 'file-export-docx':
      if(document.querySelector('.exc-overlay')) return;
      return runDocxExport('annotated');
    case 'file-export-llm':
      if(document.querySelector('.exc-overlay')) return;
      return openAiExportModal();
    case 'file-close-tab':
      if(currentProjectId) closeTab(currentProjectId);
      return;
    case 'edit-find': {
      const s = document.getElementById('searchInp');
      if(s){ s.focus(); s.select(); }
      return;
    }
    case 'view-toggle-vault':   return toggleMediaTab();
    case 'view-info':           return openInfoPanel();
    case 'locations-map':       return openLocationsMap();
    case 'view-fit':            return fitView();
    case 'view-zoom-in': {
      if(!state) return;
      const r = viewport.getBoundingClientRect();
      zoomAt(r.width / 2, r.height / 2, 1.2);
      return;
    }
    case 'view-zoom-out': {
      if(!state) return;
      const r = viewport.getBoundingClientRect();
      zoomAt(r.width / 2, r.height / 2, 1 / 1.2);
      return;
    }
    // Both of these used to click buttons that do not exist anywhere in the
    // markup (#debugBtn, #updateYtdlpBtn) — leftovers from a toolbar that was
    // taken apart — so View ▸ Debug Panel and Help ▸ Update Extractor were dead
    // menu items. Call the real thing instead.
    case 'view-debug':          return openDebugPanel();
    case 'help-shortcuts': {
      const btn = document.getElementById('helpBtn');
      if(btn) btn.click();
      return;
    }
    case 'help-log':
      if(HAS_TAURI){
        window.__TAURI__.core.invoke('log_dir_path').then(dir => {
          window.__TAURI__.core.invoke('reveal_path', { path: dir });
        }).catch(() => note('Could not open log directory'));
      }
      return;
    case 'help-update-ytdlp': {
      // The only real updater is the Debug panel's button — and the panel is
      // where the result lands anyway (progress on the button, then a fresh
      // diagnostic + log). Open it and press it for the user.
      openDebugPanel();
      const btn = document.querySelector('#debugPanel .debug-update-btn');
      if(btn) btn.click(); else note('Update extractor is unavailable');
      return;
    }
  }
}

// ===== Document viewer =====
function _docKindFor(doc){
  const ext = ((doc.filename || '').split('.').pop() || '').toLowerCase();
  const mime = (doc.mimeType || '').toLowerCase();
  if(mime === 'application/pdf' || ext === 'pdf') return 'pdf';
  if(mime.startsWith('image/') || ['jpg','jpeg','png','gif','webp','svg','bmp'].includes(ext)) return 'image';
  if(ext === 'docx' || mime.includes('wordprocessingml')) return 'docx';
  if(ext === 'xlsx' || ext === 'xls' || mime.includes('spreadsheet') || mime.includes('excel')) return 'xlsx';
  if(ext === 'csv' || mime === 'text/csv') return 'csv';
  if(['txt','md','log','json','xml','rtf'].includes(ext) || mime.startsWith('text/')) return 'text';
  return 'binary';
}
// ── Spreadsheet rendering (SheetJS, import-only) ──────────────────────────────
// Parse an array buffer into per-sheet row arrays. Requires XLSX (loadScript first).
function _xlsxRows(arrayBuffer){
  const wb = XLSX.read(new Uint8Array(arrayBuffer), { type: 'array' });
  return wb.SheetNames.map(name => ({
    name,
    rows: XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, blankrows: false, defval: '' })
  }));
}
function _rowsToTableHtml(rows, maxRows, maxCols){
  const rs = maxRows ? rows.slice(0, maxRows) : rows;
  let html = '<table class="sheet-table">';
  rs.forEach((r, ri) => {
    const cells = maxCols ? (r || []).slice(0, maxCols) : (r || []);
    const tag = ri === 0 ? 'th' : 'td';
    html += '<tr>' + cells.map(c => '<' + tag + '>' + escapeHtml(String(c == null ? '' : c)) + '</' + tag + '>').join('') + '</tr>';
  });
  return html + '</table>';
}
// Full tables, one per sheet. [{ name, html }]
function sheetToTables(arrayBuffer){
  return _xlsxRows(arrayBuffer).map(s => ({ name: s.name, html: _rowsToTableHtml(s.rows, 0, 0) }));
}
// A clamped mini-table of the first sheet (for the card thumbnail).
function sheetPreviewHtml(arrayBuffer, maxRows, maxCols){
  const sheets = _xlsxRows(arrayBuffer);
  if(!sheets.length) return '';
  return _rowsToTableHtml(sheets[0].rows, maxRows || 6, maxCols || 5);
}
async function openDocViewer(doc){
  if(!doc) return;
  const el = document.getElementById('docViewer');
  if(!el) return;
  el.querySelector('.doc-viewer-title').textContent = doc.filename || 'Document';
  const body = el.querySelector('.doc-viewer-body');
  body.innerHTML = '<div class="doc-viewer-loading">Loading…</div>';
  el.hidden = false;
  const dlBtn = el.querySelector('.doc-viewer-download');
  dlBtn.onclick = () => {
    const a = document.createElement('a');
    a.href = storage.assetSrc(doc.src);
    a.download = doc.filename || 'document';
    document.body.appendChild(a); a.click(); a.remove();
  };

  // Remove any page→Vault control left over from a previous (PDF) open.
  const head = el.querySelector('.doc-viewer-head');
  const oldCtl = head.querySelector('.doc-viewer-pagectl');
  if(oldCtl) oldCtl.remove();
  _teardownPdfViewer();

  const kind = _docKindFor(doc);
  const url = storage.assetSrc(doc.src);
  try {
    if(kind === 'pdf'){
      await renderPdfViewer(doc, url, body, head, dlBtn);
    } else if(kind === 'image'){
      body.innerHTML = '';
      const img = document.createElement('img');
      img.className = 'doc-viewer-img';
      img.src = url;
      body.appendChild(img);
    } else if(kind === 'docx'){
      try { await loadScript('vendor/mammoth.browser.min.js'); }
      catch(e){ body.innerHTML = '<div class="doc-viewer-error">Could not load DOCX renderer.</div>'; return; }
      const res = await fetch(url);
      const buf = await res.arrayBuffer();
      const out = await window.mammoth.convertToHtml({ arrayBuffer: buf });
      // Round 48: the .docx is untrusted (shared project asset) — sanitize
      // mammoth's HTML before it enters the privileged webview DOM.
      const _clean = _sanitizeHtmlFragment(out.value || '') || '<i>Empty document</i>';
      body.innerHTML = '<div class="doc-viewer-docx">' + _clean + '</div>';
      if(out.messages && out.messages.length){
        console.warn('mammoth messages:', out.messages);
      }
    } else if(kind === 'text'){
      const res = await fetch(url);
      const text = await res.text();
      body.innerHTML = '';
      const pre = document.createElement('pre');
      pre.className = 'doc-viewer-text';
      pre.textContent = text;
      body.appendChild(pre);
    } else if(kind === 'xlsx' || kind === 'csv'){
      try { await loadScript('vendor/xlsx.full.min.js'); }
      catch(e){ body.innerHTML = '<div class="doc-viewer-error">Could not load the spreadsheet renderer.</div>'; return; }
      let tables;
      try {
        const buf = await (await fetch(url)).arrayBuffer();
        tables = sheetToTables(buf);
      } catch(e){ body.innerHTML = '<div class="doc-viewer-error">Could not read that spreadsheet.</div>'; return; }
      if(!tables.length){ body.innerHTML = '<div class="doc-viewer-error">Empty spreadsheet.</div>'; return; }
      body.innerHTML = '';
      const wrap = document.createElement('div'); wrap.className = 'doc-viewer-sheet';
      const sbody = document.createElement('div'); sbody.className = 'doc-viewer-sheet-body';
      const show = (i) => { sbody.innerHTML = tables[i].html; };
      if(tables.length > 1){
        const tabs = document.createElement('div'); tabs.className = 'doc-viewer-sheet-tabs';
        tables.forEach((t, i) => {
          const b = document.createElement('button'); b.className = 'doc-viewer-sheet-tab' + (i===0?' on':''); b.textContent = t.name || ('Sheet ' + (i+1));
          b.addEventListener('click', () => { tabs.querySelectorAll('.doc-viewer-sheet-tab').forEach(x=>x.classList.remove('on')); b.classList.add('on'); show(i); });
          tabs.appendChild(b);
        });
        wrap.appendChild(tabs);
      }
      wrap.appendChild(sbody);
      body.appendChild(wrap);
      show(0);
    } else {
      body.innerHTML = '<div class="doc-viewer-fallback">Preview not available for this file type. Use Download to save it.</div>';
    }
  } catch(err){
    console.error('openDocViewer', err);
    body.innerHTML = '<div class="doc-viewer-error">Could not preview this document: ' + (err.message || err) + '</div>';
  }
}
function closeDocViewer(){
  const el = document.getElementById('docViewer');
  if(!el) return;
  el.hidden = true;
  const body = el.querySelector('.doc-viewer-body');
  if(body) body.innerHTML = '';
  const ctl = el.querySelector('.doc-viewer-pagectl');
  if(ctl) ctl.remove();
  _teardownPdfViewer();
}

// #3 — PDF.js canvas viewer with live current-page tracking + page→Vault.
let _pdfViewerObserver = null;
function _teardownPdfViewer(){
  if(_pdfViewerObserver){ try { _pdfViewerObserver.disconnect(); } catch(e){} _pdfViewerObserver = null; }
}
async function renderPdfViewer(doc, url, body, head, dlBtn){
  _teardownPdfViewer();
  // Header control: Page [n] / N  + Send page to Vault
  const ctl = document.createElement('span'); ctl.className = 'doc-viewer-pagectl';
  const lbl = document.createElement('span'); lbl.className = 'doc-viewer-pagelbl'; lbl.textContent = 'Page';
  const inp = document.createElement('input'); inp.className = 'doc-viewer-pagenum'; inp.type = 'number'; inp.min = '1'; inp.value = '1';
  inp.title = 'Current page — edit to jump, then “Page to Vault” sends it';
  const ofN = document.createElement('span'); ofN.className = 'doc-viewer-pagelbl doc-viewer-ofn'; ofN.textContent = '/ …';
  const btn = document.createElement('button'); btn.className = 'btn doc-viewer-tovault'; btn.textContent = 'Page to Vault';
  btn.title = 'Send this page to the Vault as an image';
  ctl.append(lbl, inp, ofN, btn);
  head.insertBefore(ctl, dlBtn);

  let pdf;
  try {
    await loadScript('vendor/pdf.min.js');
    if(!window.pdfjsLib) throw new Error('pdfjs unavailable');
    window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'vendor/pdf.worker.min.js';
    const buf = await (await fetch(url)).arrayBuffer();
    pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
  } catch(e){
    console.error('renderPdfViewer', e);
    body.innerHTML = '<div class="doc-viewer-error">Could not render this PDF.</div>';
    return;
  }
  const total = pdf.numPages;
  ofN.textContent = '/ ' + total; inp.max = String(total);
  body.innerHTML = '';
  const scroller = document.createElement('div'); scroller.className = 'doc-viewer-pdfjs';
  body.appendChild(scroller);

  let current = 1;
  const setCurrent = p => { current = p; if(document.activeElement !== inp) inp.value = String(p); };
  btn.addEventListener('click', () => sendPdfPageToVault(doc, parseInt(inp.value, 10) || current));
  inp.addEventListener('change', () => {
    const p = Math.max(1, Math.min(total, parseInt(inp.value, 10) || 1));
    inp.value = String(p);
    const w = scroller.querySelector('[data-page="' + p + '"]');
    if(w) w.scrollIntoView({ block: 'start' });
  });

  const targetW = 820;
  const base = await pdf.getPage(1);
  const baseVp = base.getViewport({ scale: 1 });
  const approxH = Math.round(targetW * (baseVp.height / baseVp.width));
  const wraps = [];
  for(let i = 1; i <= total; i++){
    const w = document.createElement('div'); w.className = 'doc-viewer-pdfpage'; w.dataset.page = String(i);
    w.style.minHeight = approxH + 'px';
    scroller.appendChild(w); wraps.push(w);
  }
  const rendered = new Set();
  async function renderPage(i){
    if(rendered.has(i)) return; rendered.add(i);
    try {
      const page = await pdf.getPage(i);
      const scale = targetW / page.getViewport({ scale: 1 }).width;
      const vp = page.getViewport({ scale });
      const canvas = document.createElement('canvas');
      canvas.width = Math.round(vp.width); canvas.height = Math.round(vp.height);
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
      await page.render({ canvasContext: ctx, viewport: vp }).promise;
      const wrap = wraps[i - 1];
      wrap.style.minHeight = ''; wrap.innerHTML = ''; wrap.appendChild(canvas);
    } catch(e){ rendered.delete(i); }
  }
  _pdfViewerObserver = new IntersectionObserver(entries => {
    entries.forEach(en => { if(en.isIntersecting) renderPage(parseInt(en.target.dataset.page, 10)); });
  }, { root: scroller, rootMargin: '300px 0px' });
  wraps.forEach(w => _pdfViewerObserver.observe(w));

  // Current page = first page whose bottom is below the scroller's top edge.
  scroller.addEventListener('scroll', () => {
    const sr = scroller.getBoundingClientRect();
    for(const w of wraps){
      const r = w.getBoundingClientRect();
      if(r.bottom > sr.top + 8){ setCurrent(parseInt(w.dataset.page, 10)); break; }
    }
  });
  renderPage(1); if(total > 1) renderPage(2);
}

// #3 — render one PDF page to a canvas and push it into the Vault as a still.
async function sendPdfPageToVault(doc, pageNum){
  if(!doc || !state) return;
  note('Rendering page ' + pageNum + '…');
  try {
    await loadScript('vendor/pdf.min.js');
    if(!window.pdfjsLib){ note('PDF tools unavailable'); return; }
    window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'vendor/pdf.worker.min.js';
    const buf = await (await fetch(storage.assetSrc(doc.src))).arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
    const p = Math.max(1, Math.min(pdf.numPages, (pageNum | 0) || 1));
    const page = await pdf.getPage(p);
    const viewport = page.getViewport({ scale: 2 });
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(viewport.width);
    canvas.height = Math.round(viewport.height);
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, canvas.width, canvas.height); // flatten transparency
    await page.render({ canvasContext: ctx, viewport }).promise;
    const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
    if(!Array.isArray(state.mediaShelf)) state.mediaShelf = [];
    const src = HAS_TAURI ? await storage.writeAssetFromDataUrl('img', dataUrl) : dataUrl;
    state.mediaShelf.push({
      id: 'm' + (uid++), type: 'image', src,
      width: canvas.width, height: canvas.height,
      origin: 'pdf-page', capturedFrom: (doc.filename || 'document') + ' — p.' + p, addedAt: nowMs()
    });
    save();
    openMediaTab(); renderMediaTab();
    note('Page ' + p + ' added to Vault');
  } catch(err){
    console.error('sendPdfPageToVault', err);
    note('Could not render that page');
  }
}
(function wireDocViewer(){
  const el = document.getElementById('docViewer');
  if(!el) return;
  el.querySelector('.doc-viewer-close').addEventListener('click', closeDocViewer);
  el.querySelector('.doc-viewer-backdrop').addEventListener('click', closeDocViewer);
})();

// #4(sidebar) watchdog — nothing in normal use should hide the left toolbar
// (only the read-only viewer's body.beat-view does). If something ever flips it
// to display:none / hidden / opacity:0, restore it and log the trigger so we
// can diagnose the transient disappearance the user reported.
(function guardSideTools(){
  if(IS_VIEWER) return;
  const el = document.getElementById('sideTools');
  if(!el || typeof MutationObserver !== 'function') return;
  const restore = () => {
    const cs = getComputedStyle(el);
    if(cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity) === 0){
      console.warn('[Beat] sideTools was hidden — restoring. inline=', el.getAttribute('style'));
      el.style.display = 'flex';
      el.style.visibility = 'visible';
      el.style.opacity = '1';
    }
  };
  const mo = new MutationObserver(restore);
  mo.observe(el, { attributes: true, attributeFilter: ['style', 'class', 'hidden'] });
  mo.observe(document.body, { attributes: true, attributeFilter: ['class'] });
})();
document.addEventListener('keydown', ev => {
  if(ev.key !== 'Escape') return;
  const dv = document.getElementById('docViewer');
  if(dv && !dv.hidden) closeDocViewer();
  const sp = document.getElementById('sidebarPrefs');
  if(sp && !sp.hidden) closeSidebarPrefs();
});
// Escape for the four surfaces that never had it (Joao's tidy-up round):
// Preferences — the only top-level modal with no Esc at all — plus Project
// info, Outline and the Vault.
//
// Bubble phase, deliberately: every overlay that runs its own key model (the
// Export center, the command palette, presentation, the print-layout designer,
// On set, the image / Set Plan editors) already consumes Escape in the capture
// phase with stopPropagation, so none of them can fall through to here. The
// selector below covers the ones that DON'T stop it. The + Add flyout's
// capture handler also stops propagation, so its Escape is untouched.
//
// One press closes ONE thing, topmost first. A field inside a side panel keeps
// its own Escape (blur / cancel); Preferences is exempt from that rule because
// there Escape IS its Cancel button, which is what a modal's Escape means.
document.addEventListener('keydown', ev => {
  if(ev.key !== 'Escape') return;
  if(document.querySelector('.ui-confirm, .simple-prompt-overlay, .el-menu, ' +
    '.news-overlay, .tourhub-overlay, .onboard-card, ' +
    '#lightbox:not([hidden]), #videoImporter:not([hidden]), #videoLightbox:not([hidden]), ' +
    '#docViewer:not([hidden]), #welcomeModal:not([hidden]), #debugPanel:not([hidden]), ' +
    '#sidebarPrefs:not([hidden]), #cheatSheet:not([hidden])')) return;
  if(document.body.classList.contains('print-layout')) return; // the designer owns Esc
  const prefs = document.getElementById('prefsPanel');
  if(prefs && !prefs.hidden){ ev.preventDefault(); ev.stopPropagation(); closePrefsPanel(); return; }
  // With the Projects modal up and Preferences closed, the modal IS the top
  // surface — its own handler above already dismissed it on this same press.
  if(!projectsModal.hidden) return;
  const ae = document.activeElement;
  if(ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable)) return;
  if(mediaTabEl && !mediaTabEl.hidden){ ev.preventDefault(); ev.stopPropagation(); closeMediaTab(); return; }
  if(outlinePanel && !outlinePanel.hidden){ ev.preventDefault(); ev.stopPropagation(); closeOutline(); return; }
  if(infoPanel && !infoPanel.hidden){ ev.preventDefault(); ev.stopPropagation(); closeInfoPanel(); return; }
  // The inspector and its selection are one concept — Esc dismisses both.
  if(inspPanel && !inspPanel.hidden){ ev.preventDefault(); ev.stopPropagation(); closeInspector(true); return; }
});

// ===== Filter panel (filterBtn in the toolbar) =====
function openFilterPanel(){
  const pop = document.getElementById('filterPop');
  if(!pop) return;
  renderFilterPanel();
  pop.hidden = false;
  const _fb = document.getElementById('filterBtn'); if(_fb) _fb.classList.add('active');
}
function closeFilterPanel(){
  const pop = document.getElementById('filterPop');
  if(pop) pop.hidden = true;
  const _fb = document.getElementById('filterBtn'); if(_fb) _fb.classList.remove('active');
}
function renderFilterPanel(){
  const body = document.getElementById('filterBody');
  if(!body || !state) return;
  body.innerHTML = '';

  const TYPE_LABELS = {
    beat: 'Beats', title: 'Titles', note: 'Notes', thought: 'Thoughts',
    gallery: 'Galleries', sketch: 'Sketches', character: 'Characters',
    location: 'Locations', prop: 'Props', palette: 'Palettes', setplan: 'Set Plans',
    shotlist: 'Shot Lists', checklist: 'Checklists'
  };

  const mkSection = (label) => {
    const wrap = document.createElement('div'); wrap.className = 'filter-section';
    const h = document.createElement('h4'); h.textContent = label; wrap.appendChild(h);
    const row = document.createElement('div'); row.className = 'filter-chips';
    wrap.appendChild(row);
    body.appendChild(wrap);
    return row;
  };

  // Colors
  const colorRow = mkSection('Colour');
  const palette = (state.palette && state.palette.length) ? state.palette : TAG_COLORS;
  const colorChip = (val, dotColor, label) => {
    const chip = document.createElement('button'); chip.className = 'filter-chip';
    if(filters.colors.has(val)) chip.classList.add('on');
    const dot = document.createElement('span'); dot.className = 'filter-chip-dot';
    if(dotColor) dot.style.background = dotColor; else dot.classList.add('filter-chip-dot-none');
    const txt = document.createElement('span'); txt.textContent = label;
    chip.append(dot, txt);
    chip.addEventListener('click', () => {
      if(filters.colors.has(val)) filters.colors.delete(val); else filters.colors.add(val);
      chip.classList.toggle('on');
      applyFilters();
    });
    return chip;
  };
  colorRow.appendChild(colorChip('__none__', null, 'No colour'));
  // Palette colors as swatches, not hex labels. (#audit 9.1)
  palette.forEach(hex => {
    const sw = document.createElement('button'); sw.className = 'filter-chip filter-swatch';
    if(filters.colors.has(hex)) sw.classList.add('on');
    sw.title = hex; sw.style.background = hex;
    sw.addEventListener('click', () => {
      if(filters.colors.has(hex)) filters.colors.delete(hex); else filters.colors.add(hex);
      sw.classList.toggle('on');
      applyFilters();
    });
    colorRow.appendChild(sw);
  });

  // Types — only show types that exist in the current project
  const typeRow = mkSection('Type');
  const presentTypes = new Set((state.nodes || []).map(n => n.type || 'beat'));
  Object.keys(TYPE_LABELS).forEach(t => {
    if(!presentTypes.has(t)) return;
    const chip = document.createElement('button'); chip.className = 'filter-chip';
    if(filters.types.has(t)) chip.classList.add('on');
    chip.textContent = TYPE_LABELS[t] || t;
    chip.addEventListener('click', () => {
      if(filters.types.has(t)) filters.types.delete(t); else filters.types.add(t);
      chip.classList.toggle('on');
      applyFilters();
    });
    typeRow.appendChild(chip);
  });

  // Tone — the most useful semantic axis to filter by. (#audit 9.2)
  const usedTones = new Set();
  (state.nodes || []).forEach(n => (Array.isArray(n.tones) ? n.tones : []).forEach(t => usedTones.add(t)));
  if(usedTones.size){
    const toneRow = mkSection('Tone');
    [...usedTones].forEach(name => {
      const chip = document.createElement('button'); chip.className = 'filter-chip';
      if(filters.tones.has(name)) chip.classList.add('on');
      chip.textContent = name;
      chip.style.borderLeft = '10px solid ' + toneColor(name);
      chip.addEventListener('click', () => {
        if(filters.tones.has(name)) filters.tones.delete(name); else filters.tones.add(name);
        chip.classList.toggle('on');
        applyFilters();
      });
      toneRow.appendChild(chip);
    });
  }

  // Groups
  const groups = state.groups || [];
  if(groups.length){
    const groupRow = mkSection('Group');
    groups.forEach(g => {
      const chip = document.createElement('button'); chip.className = 'filter-chip';
      if(filters.groups.has(g.id)) chip.classList.add('on');
      chip.textContent = g.name || 'Unnamed group';
      if(g.color){
        const dot = document.createElement('span'); dot.className = 'filter-chip-dot';
        dot.style.background = g.color;
        chip.prepend(dot);
      }
      chip.addEventListener('click', () => {
        if(filters.groups.has(g.id)) filters.groups.delete(g.id); else filters.groups.add(g.id);
        chip.classList.toggle('on');
        applyFilters();
      });
      groupRow.appendChild(chip);
    });
  }

  if(!body.children.length){
    const empty = document.createElement('div'); empty.className = 'filter-empty';
    empty.textContent = 'Nothing to filter yet.';
    body.appendChild(empty);
  }
}
(function wireFilterPanel(){
  const btn = document.getElementById('filterBtn');
  const pop = document.getElementById('filterPop');
  if(!btn || !pop) return;
  btn.addEventListener('click', ev => {
    ev.stopPropagation();
    if(pop.hidden) openFilterPanel(); else closeFilterPanel();
  });
  document.getElementById('closeFilterBtn').addEventListener('click', closeFilterPanel);
  document.getElementById('clearFiltersBtn').addEventListener('click', () => {
    filters.colors.clear(); filters.groups.clear(); filters.types.clear(); filters.tones.clear();
    applyFilters();
    renderFilterPanel();
  });
  // Click outside closes
  document.addEventListener('click', ev => {
    if(pop.hidden) return;
    if(ev.target.closest('#filterPop') || ev.target.closest('#filterBtn')) return;
    closeFilterPanel();
  });
})();

// ===== Debug panel (Cmd+Shift+D) =====
function openDebugPanel(){
  const el = document.getElementById('debugPanel');
  if(!el) return;
  el.hidden = false;
  // Auto-refresh the log on open.
  refreshDebugLog();
}
function closeDebugPanel(){
  const el = document.getElementById('debugPanel');
  if(el) el.hidden = true;
}
async function runDebugTest(){
  const out = document.querySelector('#debugPanel .debug-result');
  if(!out) return;
  if(!HAS_TAURI){
    out.textContent = '(Debug panel runs full diagnostics only inside the Tauri app)\n\n' +
      'storage.isTauri = false (browser preview).';
    return;
  }
  out.textContent = 'Running…';
  try {
    const d = await window.__TAURI__.core.invoke('extractor_diagnostics');
    out.textContent = JSON.stringify(d, null, 2);
    out.classList.toggle('debug-result-ok',
      d && d.inspect_test && d.inspect_test.supported === true);
    out.classList.toggle('debug-result-err',
      !!(d && (d.ytdlp_path_error || d.ytdlp_version_error || (d.inspect_test && d.inspect_test.supported === false))));
    // Pull log right after — the diagnostic itself appends a line.
    refreshDebugLog();
  } catch(err){
    out.textContent = 'Diagnostic failed: ' + (err && err.message || err);
    out.classList.add('debug-result-err');
  }
}
async function refreshDebugLog(){
  const out = document.querySelector('#debugPanel .debug-log');
  const hint = document.querySelector('#debugPanel .debug-log-hint');
  if(!out) return;
  if(!HAS_TAURI){
    out.textContent = '(Log file only exists inside the Tauri app)';
    return;
  }
  try {
    const text = await window.__TAURI__.core.invoke('read_log_tail', { lines: 300 });
    out.textContent = (text && text.trim()) || '(empty)';
    out.scrollTop = out.scrollHeight;
    if(hint){
      try {
        const dir = await window.__TAURI__.core.invoke('log_dir_path');
        hint.textContent = '— ' + dir + '/beat.log';
      } catch(e){}
    }
  } catch(err){
    out.textContent = 'Log read failed: ' + (err && err.message || err);
  }
}
async function copyText(s){
  try { await navigator.clipboard.writeText(s); note('Copied'); }
  catch(e){ console.error('clipboard', e); note('Copy failed'); }
}
async function copyDebugResult(){
  const out = document.querySelector('#debugPanel .debug-result');
  if(out) copyText(out.textContent || '');
}
async function copyDebugLog(){
  if(!HAS_TAURI){ note('Log only exists inside the app'); return; }
  try {
    const text = await window.__TAURI__.core.invoke('read_log_tail', { lines: 100000 });
    copyText(text || '');
  } catch(err){ note('Log read failed'); }
}
async function revealLogFolder(){
  if(!HAS_TAURI){ note('Log only exists inside the app'); return; }
  try {
    const dir = await window.__TAURI__.core.invoke('log_dir_path');
    // Use macOS `open` via osascript — Tauri's opener plugin would be cleaner
    // but we haven't pulled it in yet. For now this is best-effort.
    window.__TAURI__.core.invoke('reveal_path', { path: dir }).catch(()=>{
      note('Log folder: ' + dir);
    });
  } catch(err){ note('Could not reveal log folder'); }
}

(function wireDebugPanel(){
  const el = document.getElementById('debugPanel');
  if(!el) return;
  el.querySelector('.debug-close-btn').addEventListener('click', closeDebugPanel);
  el.querySelector('.debug-backdrop').addEventListener('click', closeDebugPanel);
  el.querySelector('.debug-run-btn').addEventListener('click', runDebugTest);
  const updateBtn = el.querySelector('.debug-update-btn');
  if(updateBtn){
    updateBtn.addEventListener('click', async () => {
      if(!HAS_TAURI){ note('Update only works inside the Mac app'); return; }
      updateBtn.disabled = true;
      const originalText = updateBtn.textContent;
      updateBtn.textContent = 'Updating…';
      try {
        const v = await window.__TAURI__.core.invoke('update_ytdlp');
        note('Extractor updated to ' + v);
        refreshDebugLog();
        runDebugTest();
      } catch(err){
        note('Update failed: ' + (err && err.message || err));
      } finally {
        updateBtn.disabled = false;
        updateBtn.textContent = originalText;
      }
    });
  }
  el.querySelector('.debug-refresh-log-btn').addEventListener('click', refreshDebugLog);
  el.querySelector('.debug-copy-result-btn').addEventListener('click', copyDebugResult);
  el.querySelector('.debug-copy-log-btn').addEventListener('click', copyDebugLog);
  el.querySelector('.debug-open-log-btn').addEventListener('click', revealLogFolder);
})();
document.addEventListener('keydown', ev => {
  if((ev.metaKey || ev.ctrlKey) && ev.shiftKey && (ev.key === 'd' || ev.key === 'D')){
    ev.preventDefault();
    openDebugPanel();
  }
  if(ev.key === 'Escape'){
    const el = document.getElementById('debugPanel');
    if(el && !el.hidden) closeDebugPanel();
  }
});

// ===== Phase 17b: One-shot import from web-Beat .zip =====
async function importFromWebBeatZip(){
  if(!HAS_TAURI) return;
  const lib = await storage.libraryPath();
  if(!lib){ note('Library not set up yet'); return; }
  const picked = await storage.pickFile('Pick the .zip exported from web Beat', ['zip']);
  if(!picked) return;
  note('Importing…');
  try {
    const report = await window.__TAURI__.core.invoke('import_from_zip', {
      zipPath: picked,
      libraryPath: lib
    });
    let msg = 'Imported ' + report.imported + ' project' + (report.imported === 1 ? '' : 's');
    if(report.skipped) msg += '; skipped ' + report.skipped;
    note(msg);
    renderProjectsPanel();
  } catch(err){
    note('Import failed: ' + (err.message || err));
  }
}

// ===== Phase 17a: First-launch welcome (Tauri only) =====
async function maybeShowWelcomeModal(){
  if(!HAS_TAURI) return false;
  let libPath = null;
  try { libPath = await storage.libraryPath(); } catch(e){}
  // Configured but GONE (folder moved/renamed, or a reinstall wiped it while
  // config.json survived) → re-ask instead of booting into a silently empty
  // library. Probe failure counts as present: never nag over a hiccup.
  let libMissing = false;
  if(libPath){
    try { libMissing = (await _ti('dir_exists', { path: libPath })) === false; }
    catch(e){ libMissing = false; }
    if(!libMissing) return false;
  }

  let def = null;
  try { def = await storage.defaultLibrarySuggestion(); } catch(e){}
  const el = document.getElementById('welcomeModal');
  if(!el){ console.error('welcomeModal element missing'); return false; }
  const pathEl = el.querySelector('#welcomeDefaultPath');
  if(pathEl && def) pathEl.textContent = def;
  // The re-ask case says WHY the welcome is back, and names the folder Beat
  // lost sight of — nothing has been deleted, it just is not where it was.
  const oldNote = el.querySelector('.welcome-lib-missing');
  if(oldNote) oldNote.remove();
  if(libMissing && libPath){
    const warn = document.createElement('p');
    warn.className = 'welcome-lib-missing';
    warn.textContent = 'Beat cannot find your library folder anymore (' + libPath + '). Your projects are wherever that folder went — point Beat at it again, or start fresh below.';
    const host = el.querySelector('.welcome-body, .welcome-panel, .modal-panel') || el;
    host.insertBefore(warn, host.firstChild ? host.firstChild.nextSibling : null);
  }
  el.hidden = false;

  return new Promise(resolve => {
    const useDefaultBtn = el.querySelector('#welcomeUseDefaultBtn');
    const pickBtn = el.querySelector('#welcomePickBtn');
    const lock = () => { useDefaultBtn.disabled = true; pickBtn.disabled = true; };
    const unlock = () => { useDefaultBtn.disabled = false; pickBtn.disabled = false; };

    const useDefault = async () => {
      lock();
      try {
        await storage.setLibraryPath(def);
        el.hidden = true;
        resolve(true);
      } catch(err){
        note('Could not set library: ' + (err.message || err));
        unlock();
      }
    };
    const pick = async () => {
      const picked = await storage.pickFolder('Pick a folder for Beat projects');
      if(!picked) return;
      lock();
      try {
        await storage.setLibraryPath(picked);
        el.hidden = true;
        resolve(true);
      } catch(err){
        note('Could not set library: ' + (err.message || err));
        unlock();
      }
    };
    useDefaultBtn.addEventListener('click', useDefault);
    pickBtn.addEventListener('click', pick);
  });
}

// Boot: in Tauri, ensure the library path is configured before opening anything.
// Beat's main bootstrap above already ran for the legacy codepath; under Tauri
// we still let that bootstrap run (which falls back to localStorage if no Tauri
// projects exist) — Task 8 swaps the Projects modal to read from disk and ties
// the boot order together properly.
(async () => {
  try { _prefsCache = await storage.getPrefs() || {}; } catch(e){ _prefsCache = {}; }
  applyNavPrefs();
  try { await maybeShowWelcomeModal(); } catch(e){ console.error('welcome', e); }
  // Remote news / broadcast channel — fetch ~2.5s after boot, non-blocking. Never
  // throws into the UI; offline / 404 / bad JSON → silent no-op.
  setTimeout(() => { loadNews().catch(() => {}); }, 2500);
  if(HAS_TAURI){
    try { await window.__TAURI__.core.invoke('purge_extract_root'); }
    catch(e){ /* tolerate — first launch may not have the dir yet */ }
    // Load library-level meta (custom templates + folder definitions +
    // sidebar pins) from disk before the Projects modal renders.
    await loadLibraryMeta();
    try { renderSidebarPins(); } catch(e){}
    const pm = document.getElementById('projectsModal');
    if(pm && !pm.hidden){ try { renderProjectsPanel(); } catch(e){} }
  }
})();
